    function esc(value) {
      return String(value ?? "").replace(/[&<>"']/g, function (ch) {
        switch (ch) {
          case "&": return "&amp;";
          case "<": return "&lt;";
          case ">": return "&gt;";
          case '"': return "&quot;";
          default: return "&#39;";
        }
      });
    }

    async function fetchJson(url) {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(url + " -> " + response.status);
      }
      return response.json();
    }

    async function fetchJsonMaybe(url) {
      const response = await fetch(url);
      if (response.status === 404) {
        return null;
      }
      if (!response.ok) {
        throw new Error(url + " -> " + response.status);
      }
      return response.json();
    }

    function sleepMs(delayMs) {
      const wait = Number.isFinite(Number(delayMs)) ? Number(delayMs) : 0;
      return new Promise(resolve => window.setTimeout(resolve, Math.max(0, wait)));
    }

    async function fetchJsonWithRetry(url, options = {}) {
      const attempts = Math.max(1, Number(options.attempts) || 1);
      const delayMs = Math.max(0, Number(options.delayMs) || 0);
      const retryStatuses = Array.isArray(options.retryStatuses) && options.retryStatuses.length
        ? new Set(options.retryStatuses.map(status => Number(status)).filter(Number.isFinite))
        : new Set([404, 502, 503, 504]);
      let lastError = null;
      for (let attempt = 1; attempt <= attempts; attempt += 1) {
        const response = await fetch(url);
        if (response.ok) {
          return response.json();
        }
        lastError = new Error(url + " -> " + response.status);
        if ((attempt >= attempts) || !retryStatuses.has(response.status)) {
          throw lastError;
        }
        await sleepMs(delayMs);
      }
      throw lastError || new Error(url + " -> retry exhausted");
    }

    async function postJson(url, payload) {
      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!response.ok) {
        throw new Error(url + " -> " + response.status);
      }
      return response.json();
    }

