    function studioWorkspacePath(workspaceId = studioWorkspace) {
      return studioWorkspaceSpec(workspaceId).path || "/studio/create";
    }

    function updateStudioWorkspacePath(workspaceId = studioWorkspace, options = {}) {
      if (!window.history || !window.location) {
        return;
      }
      const targetPath = studioWorkspacePath(workspaceId);
      const nextUrl = targetPath + (window.location.search || "") + (window.location.hash || "");
      const currentUrl = window.location.pathname + (window.location.search || "") + (window.location.hash || "");
      if (nextUrl === currentUrl) {
        return;
      }
      const state = { studioWorkspace: normalizeStudioWorkspaceId(workspaceId) };
      if (options.replace === true) {
        window.history.replaceState(state, "", nextUrl);
      } else {
        window.history.pushState(state, "", nextUrl);
      }
    }

