    function creationProjectMatchesRoleTuningFilter(entry, filterId = creationProjectUiState.roleTuning) {
      const normalized = normalizeCreationProjectRoleTuningFilterId(filterId);
      if (normalized === "all") {
        return true;
      }
      const coverage = normalizeCreationRoleRefinementCoverage(entry?.roleTuning, false);
      const totalCount = Number(coverage?.totalCount || 0);
      const tunedCount = Number(coverage?.tunedCount || 0);
      switch (normalized) {
        case "unseeded":
          return totalCount < 1;
        case "complete":
          return totalCount > 0 && tunedCount === totalCount;
        case "untuned":
          return totalCount > 0 && tunedCount < totalCount;
        default:
          return true;
      }
    }

    function creationProjectMatchesProofFilter(entry, filterId = creationProjectUiState.proofState) {
      return creationMatchesProofFilter(creationProjectProofSummary(entry), filterId);
    }

