function buildCreationPublishLowerDetailMeta(entry = {}) {

  const publish = entry && typeof entry === "object" ? entry : {};

  return {

    versionLabel: publish.versionLabel || "v1",

    lifecycle: creationPublishLifecycleSpec(publish.lifecycleState),

    decision: creationPublishDecisionSpec(publish.decision),

    handoff: creationPublishHandoffSpec(publish.handoffState),

    proof: creationPublishProofSummary(publish),

  };

}

function buildCreationPublishLowerDetailLines(entry = {}, options = {}) {

  const detail = options?.detail && typeof options.detail === "object"

    ? options.detail

    : buildCreationPublishLowerDetailMeta(entry);

  const lines = [];

  if (options?.includeVersion !== false) {

    lines.push(`${String(options?.versionLabel || "Version").trim() || "Version"}: ${detail.versionLabel || "v1"}`);

  }

  if (options?.includeLifecycle) {

    lines.push(`Lifecycle: ${detail.lifecycle?.label || "Unknown lifecycle"}`);

  }

  if (options?.includeDecision) {

    lines.push(`Decision: ${detail.decision?.label || "Unknown decision"}`);

  }

  if (options?.includeHandoff) {

    lines.push(`Handoff: ${detail.handoff?.label || "Unknown handoff"}`);

  }

  if (options?.includeProof) {

    lines.push(`Proof: ${creationProofMeta(detail.proof)}`);

  }

  if (options?.includeVersionCount) {

    lines.push(`Version count: ${Math.max(1, Number(options?.versionCount || 0) || 0)}`);

  }

  return lines.concat((Array.isArray(options?.extraLines) ? options.extraLines : []).map(line => String(line || "").trim()).filter(Boolean));

}

function creationPublishedFamilyCardMetaLines(entry, options = {}) {

  const detail = options?.detail || buildCreationPublishLowerDetailMeta(entry);

  const lines = [];

  if (options?.toneLabel) {

    lines.push(`Tone: ${options.toneLabel}`);

  }

  if (options?.includeDecision) {

    lines.push(`Decision: ${detail.decision?.label || "Unknown decision"}`);

  }

  if (options?.familyLabel) {

    lines.push(`Family: ${options.familyLabel}`);

  }

  if (options?.lineageLabel) {

    lines.push(`Family role: ${options.lineageLabel}`);

  }

  if (options?.familySize != null) {

    lines.push(`Family size: ${Number(options.familySize)}`);

  }

  if (options?.versionCount != null) {

    lines.push(`Versions: ${Number(options.versionCount)}`);

  }

  if (options?.archivedCount != null) {

    lines.push(`Archived: ${Number(options.archivedCount)}`);

  }

  if (options?.queueCount != null) {

    lines.push(`Dev-side queue: ${Number(options.queueCount)}`);

  }

  if (options?.includeUpdated) {

    lines.push(`Updated: ${new Date(entry?.updatedAtMs || entry?.createdAtMs || Date.now()).toLocaleString()}`);

  }

  if (options?.includeProof !== false) {

    lines.push(`Proof: ${creationProofMeta(detail.proof)}`);

  }

  return lines;

}

