    function visibleStudioLabTabs() {
      return Array.isArray(studioWorkspaceSpec().visibleTabs) ? studioWorkspaceSpec().visibleTabs : ["create"];
    }

    function isStudioTabVisible(tabId) {
      const normalized = String(tabId || "").trim().toLowerCase();
      return visibleStudioLabTabs().includes(normalized);
    }

    function renderStudioModeChrome() {
      const monitorButton = document.getElementById("studio-workspace-monitor");
      const createButton = document.getElementById("studio-workspace-create");
      const devButton = document.getElementById("studio-workspace-dev");
      const summary = document.getElementById("studio-mode-summary");
      const labTitle = document.getElementById("studio-lab-title");
      const labSummary = document.getElementById("studio-lab-summary");
      const sidebarPanel = document.getElementById("studio-sidebar-panel");
      const detailPanel = document.getElementById("studio-detail-panel");
      const spec = studioWorkspaceSpec();
      document.body.dataset.studioWorkspace = spec.id;
      if (monitorButton) {
        monitorButton.classList.toggle("active", spec.id === "monitor");
      }
      if (createButton) {
        createButton.classList.toggle("active", spec.id === "create");
      }
      if (devButton) {
        devButton.classList.toggle("active", spec.id === "dev");
      }
      if (summary) {
        summary.textContent = spec.summary;
      }
      if (labTitle) {
        labTitle.textContent = spec.labTitle;
      }
      if (labSummary) {
        labSummary.textContent = spec.labSummary;
      }
      if (sidebarPanel) {
        sidebarPanel.style.display = spec.showSidebar ? "" : "none";
      }
      if (detailPanel) {
        detailPanel.style.display = spec.showDetail ? "" : "none";
      }
      if (!isStudioTabVisible(activeLabTab)) {
        activeLabTab = studioWorkspaceTabs[spec.id] && isStudioTabVisible(studioWorkspaceTabs[spec.id])
          ? studioWorkspaceTabs[spec.id]
          : spec.defaultTab;
      }
      document.querySelectorAll("[data-lab-tab-button]").forEach(button => {
        const visible = isStudioTabVisible(button.dataset.labTabButton);
        button.style.display = visible ? "" : "none";
      });
      document.querySelectorAll("[data-lab-tab]").forEach(panel => {
        const visible = isStudioTabVisible(panel.dataset.labTab);
        panel.style.display = visible ? "" : "none";
      });
      syncLabTabs();
      renderCreationModeChrome();
    }

    function setStudioUxMode(mode) {
      setStudioWorkspace(mode === "full" ? "dev" : "create");
    }

    function setStudioWorkspace(workspaceId, options = {}) {
      studioWorkspace = normalizeStudioWorkspaceId(workspaceId);
      saveStudioWorkspace(studioWorkspace);
      if (options.updatePath !== false) {
        updateStudioWorkspacePath(studioWorkspace, { replace: options.replace === true });
      }
      if (!isStudioTabVisible(activeLabTab)) {
        const preferredTab = studioWorkspaceTabs[studioWorkspace];
        activeLabTab = preferredTab && studioWorkspaceSpec().visibleTabs.includes(preferredTab)
          ? preferredTab
          : studioWorkspaceSpec().defaultTab;
      }
      renderStudioModeChrome();
    }

    function renderCreationModeChrome() {
      const rawWizard = document.getElementById("creation-raw-wizard");
      const toggleButton = document.getElementById("creation-advanced-toggle");
      const helper = document.getElementById("creation-advanced-helper");
      const shouldShow = studioWorkspace === "dev" || creationAdvancedVisible;
      if (rawWizard) {
        rawWizard.style.display = shouldShow ? "" : "none";
      }
      if (toggleButton) {
        toggleButton.textContent = shouldShow ? "Hide Advanced Draft Wizard" : "Show Advanced Draft Wizard";
      }
      if (helper) {
        helper.textContent = shouldShow
          ? "Advanced draft fields are visible. Use them when you need fine control over the raw bundle."
          : "Creator mode keeps the raw draft wizard out of the way until you explicitly open it.";
      }
    }

    function toggleCreationAdvancedVisible(forceValue) {
      creationAdvancedVisible = typeof forceValue === "boolean" ? forceValue : !creationAdvancedVisible;
      saveCreationAdvancedVisible(creationAdvancedVisible);
      renderCreationModeChrome();
    }

    function favoriteRosterIds() {
      return loadFavoriteRosterIds();
    }

    function isFavoriteRosterEntry(entryId) {
      const normalized = String(entryId || "").trim().toLowerCase();
      if (!normalized) {
        return false;
      }
      return favoriteRosterIds().includes(normalized);
    }

    function toggleFavoriteRosterEntry(entryId) {
      const normalized = String(entryId || "").trim().toLowerCase();
      if (!normalized) {
        return;
      }
      const favorites = favoriteRosterIds();
      const next = favorites.includes(normalized)
        ? favorites.filter(value => value !== normalized)
        : favorites.concat(normalized);
      saveFavoriteRosterIds(next);
      renderRoster({ entries: latestRosterEntries });
    }

    function rosterFilterValue() {
      return String(document.getElementById("roster-filter")?.value || "").trim().toLowerCase();
    }

    function rosterTypeFilterValue() {
      return String(document.getElementById("roster-type-filter")?.value || "all").trim().toUpperCase();
    }

    function matchesRosterTypeFilter(entry, typeFilter) {
      if (!typeFilter || typeFilter === "ALL") {
        return true;
      }
      return String(entry?.type || "").trim().toUpperCase() === typeFilter;
    }

    function matchesRosterFilter(entry, query) {
      if (!query) {
        return true;
      }
      const haystack = [
        entry?.name,
        entry?.id,
        entry?.type,
        entry?.state,
        entry?.zone,
        entry?.archetype,
        entry?.targetName,
        entry?.leaderName,
      ].join(" ").toLowerCase();
      return haystack.includes(query);
    }

    function renderRosterMeta(totalCount, matchedCount) {
      const host = document.getElementById("roster-meta");
      if (!host) {
        return;
      }
      const favoriteCount = favoriteRosterIds().length;
      if (!totalCount) {
        host.textContent = "No roster entries available.";
        return;
      }
      const base = matchedCount === totalCount
        ? totalCount + " entries available"
        : matchedCount + " of " + totalCount + " entries visible";
      host.textContent = favoriteCount > 0 ? (base + " | favorites " + favoriteCount) : base;
    }

    function renderSelectionMeta(definition, runtime) {
      const host = document.getElementById("selected-meta");
      if (!host) {
        return;
      }
      if (!definition) {
        host.textContent = "No active selection";
        return;
      }
      const name = definition.name || definition.id || "FPC";
      const zone = runtime?.zone || "unknown zone";
      const state = runtime?.state || "unknown state";
      host.textContent = name + " | " + zone + " | " + state;
    }

    function syncLabTabs() {
      document.querySelectorAll("[data-lab-tab-button]").forEach(button => {
        button.classList.toggle("active", button.dataset.labTabButton === activeLabTab);
      });
      document.querySelectorAll("[data-lab-tab]").forEach(panel => {
        panel.classList.toggle("active", panel.dataset.labTab === activeLabTab);
      });
    }

    function refreshLabTabOutput(tabId = activeLabTab) {
      const normalized = String(tabId || "").trim().toLowerCase();
      if (normalized === "demo") {
        renderDemoOutput();
      }
      if (normalized === "explain") {
        renderExplainOutput();
      }
    }

    function setLabTab(tabId) {
      const normalized = String(tabId || "").trim().toLowerCase();
      const nextWorkspace = studioWorkspaceForLabTab(normalized);
      if (nextWorkspace && nextWorkspace !== studioWorkspace) {
        studioWorkspace = nextWorkspace;
        saveStudioWorkspace(studioWorkspace);
        updateStudioWorkspacePath(studioWorkspace);
      }
      activeLabTab = isStudioTabVisible(normalized)
        ? (normalized || studioWorkspaceSpec().defaultTab)
        : studioWorkspaceSpec().defaultTab;
      studioWorkspaceTabs[studioWorkspace] = activeLabTab;
      renderStudioModeChrome();
      syncLabTabs();
      refreshLabTabOutput(activeLabTab);
    }

    function authoringTargetMeta(target) {
      const normalized = String(target || "").trim().toLowerCase();
      switch (normalized) {
        case "fpcs":
          return { target: "fpcs", sectionId: "authoring-section-fpcs", label: "FPC Definition" };
        case "fpc_templates":
          return { target: "fpc_templates", sectionId: "authoring-section-fpc-templates", label: "FPC Templates" };
        case "persona_profiles":
          return { target: "persona_profiles", sectionId: "authoring-section-personas", label: "Persona Profiles" };
        case "reply_banks":
          return { target: "reply_banks", sectionId: "authoring-section-reply-banks", label: "Reply Banks" };
        case "knowledge_cards":
          return { target: "knowledge_cards", sectionId: "authoring-section-knowledge-cards", label: "Knowledge Cards" };
        case "routing_rules":
          return { target: "routing_rules", sectionId: "authoring-section-routing-rules", label: "Routing Rules" };
        case "reply_settings":
          return { target: "reply_settings", sectionId: "authoring-section-reply-settings", label: "Reply Settings" };
        default:
          return null;
      }
    }

    async function openAuthoringTarget(target) {
      const meta = authoringTargetMeta(target);
      if (!meta) {
        setLabStatus("No Studio authoring lane is mapped for that source.");
        return;
      }
      setLabTab("authoring");
      try {
        if (meta.target === "fpcs") {
          await loadAuthoringEntry();
        } else if (meta.target === "fpc_templates") {
          await loadFpcTemplateAuthoringEntry();
        } else if (meta.target === "persona_profiles") {
          await loadPersonaAuthoringEntry();
        } else if (meta.target === "reply_banks") {
          const filter = document.getElementById("reply-bank-filter-fpc-id");
          if (filter && !String(filter.value || "").trim()) {
            filter.value = activeId || "";
          }
          await loadReplyBankAuthoringEntries();
        } else if (meta.target === "knowledge_cards") {
          const filter = document.getElementById("knowledge-card-filter-fpc-id");
          if (filter && !String(filter.value || "").trim()) {
            filter.value = activeId || "";
          }
          await loadKnowledgeCardAuthoringEntries();
        } else if (meta.target === "routing_rules") {
          await loadRoutingRuleAuthoringEntries();
          primeRoutingWizardFromProbe(latestProbeResult);
        } else if (meta.target === "reply_settings") {
          await loadReplySettingsAuthoringEntry();
        }
      } catch (error) {
        setLabStatus("Could not open authoring lane: " + error.message);
      }
      window.setTimeout(() => {
        const section = document.getElementById(meta.sectionId);
        if (section) {
          section.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      }, 90);
      setLabStatus("Opened authoring lane: " + meta.label);
    }

    function authoringTargetFromFilePath(filePath = "") {
      const normalized = String(filePath || "").trim().replace(/\\/g, "/").toLowerCase();
      if (normalized.endsWith("/dist/game/data/fake_players/fpcs.json")) {
        return "fpcs";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/fpc_templates.json")) {
        return "fpc_templates";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/persona_profiles.json")) {
        return "persona_profiles";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/reply_banks.json")) {
        return "reply_banks";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/knowledge_cards.json")) {
        return "knowledge_cards";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/routing_rules.json")) {
        return "routing_rules";
      }
      if (normalized.endsWith("/dist/game/data/fake_players/reply_settings.json")) {
        return "reply_settings";
      }
      return "";
    }

    function studioGuideBucketSpec(bucketId) {
      return STUDIO_GUIDE_BUCKET_SPECS[String(bucketId || "").trim().toLowerCase()] || null;
    }

    function studioGuideLaneSpec(laneId) {
      return STUDIO_GUIDE_LANE_SPECS[String(laneId || "").trim().toLowerCase()] || null;
    }

    function renderOwnershipStrip(laneId) {
      const spec = studioGuideLaneSpec(laneId);
      if (!spec) {
        return "";
      }
      const bucket = studioGuideBucketSpec(spec.bucket);
      return `
        <div class="guide-strip">
          ${bucket ? `<span class="source-chip">${esc(bucket.label)}</span>` : ""}
          ${spec.travelLabel ? `<span class="source-chip ${esc(spec.travelClass || "")}">${esc(spec.travelLabel)}</span>` : ""}
          ${spec.userLabel ? `<span class="source-chip ${esc(spec.userClass || "")}">${esc(spec.userLabel)}</span>` : ""}
          ${spec.impactLabel ? `<span class="source-chip ${esc(spec.impactClass || "")}">${esc(spec.impactLabel)}</span>` : ""}
        </div>
        <div class="guide-strip-copy">${esc(spec.summary || "")}</div>
      `;
    }

    function currentStudioGuideHostSpec() {
      const hostId = String(document.getElementById("creation-engine-host")?.value || latestPlatformManifest?.identity?.adapterId || "mobius_tier_a").trim().toLowerCase();
      return CREATION_ENGINE_GAME_SPECS[hostId] || CREATION_ENGINE_GAME_SPECS.mobius_tier_a;
    }

    function renderGuideLaneActionButton(laneId) {
      const spec = studioGuideLaneSpec(laneId);
      if (!spec) {
        return "";
      }
      return `<button class="btn mini" onclick="openStudioGuideTarget('${esc(spec.id)}')">Open ${esc(spec.label)}</button>`;
    }

    async function openStudioGuideTarget(target) {
      const normalized = String(target || "").trim().toLowerCase();
      if (!normalized) {
        return;
      }
      const guideSpec = studioGuideLaneSpec(normalized);
      const actionTab = guideSpec?.actionTab || "";
      const sectionId = guideSpec?.actionSectionId || "";
      if (actionTab === "create") {
        setLabTab("create");
        if (sectionId) {
          window.setTimeout(() => scrollToElementId(sectionId), 60);
        }
        setLabStatus("Opened Creation Engine.");
        return;
      }
      if (actionTab === "platform" || actionTab === "workflow" || actionTab === "traces") {
        setLabTab(actionTab);
        if (sectionId) {
          window.setTimeout(() => scrollToElementId(sectionId), 60);
        }
        setLabStatus("Opened " + guideSpec.label + ".");
        return;
      }
      await openAuthoringTarget(normalized);
    }

