    async function copyTextToClipboard(value, label = "text") {
      const text = String(value || "");
      if (!text) {
        setLabStatus("Nothing to copy.");
        return;
      }
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          await navigator.clipboard.writeText(text);
        } else {
          const temp = document.createElement("textarea");
          temp.value = text;
          document.body.appendChild(temp);
          temp.select();
          document.execCommand("copy");
          temp.remove();
        }
        setLabStatus("Copied " + label + " to clipboard.");
      } catch (error) {
        setLabStatus("Could not copy " + label + ": " + error.message);
      }
    }

    function downloadTextFile(filename, content, mimeType = "text/plain;charset=utf-8") {
      const blob = new Blob([String(content || "")], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    async function openPlatformLikelyFile(filePath) {
      const target = authoringTargetFromFilePath(filePath);
      if (target) {
        await openAuthoringTarget(target);
        setLabStatus("Opened owning Studio lane for " + filePath);
        return;
      }
      await copyTextToClipboard(filePath, "file path");
    }

    function applyRosterFilter() {
      renderRoster({ entries: latestRosterEntries });
    }

    function setAuthoringStatus(message) {
      const line = document.getElementById("authoring-status");
      if (line) {
        line.textContent = String(message ?? "");
      }
      setLabStatus(message);
    }

    function prettyJson(value) {
      if (!value || (typeof value === "object" && !Object.keys(value).length)) {
        return "{}";
      }
      return JSON.stringify(value, null, 2);
    }

    function setFieldValue(id, value) {
      const field = document.getElementById(id);
      if (!field) {
        return;
      }
      if (field.type === "checkbox") {
        field.checked = Boolean(value);
        return;
      }
      field.value = value == null ? "" : String(value);
    }

    function fieldValue(id, fallback = "") {
      return String(document.getElementById(id)?.value || fallback);
    }

    function fieldChecked(id) {
      return Boolean(document.getElementById(id)?.checked);
    }

    function jsSingleQuote(value) {
      return String(value ?? "").replace(/\\/g, "\\\\").replace(/'/g, "\\'");
    }

    function scrollToElementId(id) {
      const element = document.getElementById(id);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }

    function clearAuthoringFieldHighlights() {
      document.querySelectorAll(".field-focus").forEach(node => node.classList.remove("field-focus"));
    }

    function highlightAuthoringField(fieldId) {
      clearAuthoringFieldHighlights();
      const field = document.getElementById(fieldId);
      if (!field) {
        return false;
      }
      const wrapper = field.closest(".field") || field.closest(".subsection") || field;
      if (wrapper) {
        wrapper.classList.add("field-focus");
      }
      field.scrollIntoView({ behavior: "smooth", block: "center" });
      if (typeof field.focus === "function") {
        try {
          field.focus({ preventScroll: true });
        } catch (_error) {
          field.focus();
        }
      }
      return true;
    }

    async function openAuthoringField(target, fieldId) {
      await openAuthoringTarget(target);
      window.setTimeout(() => {
        const ok = highlightAuthoringField(fieldId);
        if (!ok) {
          setLabStatus("Opened authoring lane, but the exact field could not be highlighted.");
          return;
        }
        setLabStatus("Opened and highlighted authoring field: " + fieldId);
      }, 180);
    }

    function applyAuthoringEntry(entry, sourceId = "") {
      latestAuthoringEntry = entry || null;
      authoringSourceId = (sourceId || entry?.id || activeId || "").toLowerCase();
      const setValue = (id, value) => {
        const field = document.getElementById(id);
        if (field) {
          field.value = value == null ? "" : String(value);
        }
      };
      const spawn = (entry && typeof entry.spawnProfile === "object" && entry.spawnProfile) ? entry.spawnProfile : {};
      setValue("authoring-original-id", authoringSourceId);
      setValue("authoring-id", entry?.id || activeId || "");
      setValue("authoring-name", entry?.name || activeDefinition?.name || "");
      setValue("authoring-title", entry?.title || "");
      setValue("authoring-template", entry?.template || "");
      setValue("authoring-archetype", entry?.archetype || "");
      setValue("authoring-persona-template", entry?.personaTemplate || "");
      setValue("authoring-carrier-template", entry?.carrierTemplate || "");
      setValue("authoring-carrier-npc-id", entry?.carrierNpcId ?? 0);
      setValue("authoring-auto-spawn", entry?.autoSpawnOnBoot ? "true" : "false");
      setValue("authoring-availability-profile", entry?.availabilityProfile || "");
      setValue("authoring-fallback-profile", entry?.fallbackProfile || "");
      setValue("authoring-species-tag", entry?.speciesTag || "");
      setValue("authoring-family-tag", entry?.familyTag || "");
      setValue("authoring-spawn-mode", spawn.mode || "");
      setValue("authoring-spawn-zone", spawn.zone || "");
      setValue("authoring-spawn-x", spawn.x ?? 0);
      setValue("authoring-spawn-y", spawn.y ?? 0);
      setValue("authoring-spawn-z", spawn.z ?? 0);
      setValue("authoring-spawn-heading", spawn.heading ?? 0);
      setValue("authoring-channels", prettyJson(entry?.channels || {}));
      setValue("authoring-adventurer-profile", prettyJson(entry?.adventurerProfile || {}));
      const filePath = document.getElementById("authoring-file-path");
      if (filePath) {
        filePath.textContent = "Source file: dist/game/data/fake_players/fpcs.json";
      }
    }

    function collectAuthoringEntry() {
      const parseJsonField = (id, label) => {
        const raw = document.getElementById(id)?.value || "";
        if (!raw.trim()) {
          return null;
        }
        try {
          const parsed = JSON.parse(raw);
          if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
            throw new Error(label + " must be a JSON object.");
          }
          return parsed;
        } catch (error) {
          throw new Error(label + " is not valid JSON: " + error.message);
        }
      };
      const base = latestAuthoringEntry && typeof latestAuthoringEntry === "object" ? { ...latestAuthoringEntry } : {};
      const channels = parseJsonField("authoring-channels", "Channels");
      const adventurerProfile = parseJsonField("authoring-adventurer-profile", "Adventurer Profile");
      const entry = {
        ...base,
        id: (document.getElementById("authoring-id")?.value || "").trim().toLowerCase(),
        template: (document.getElementById("authoring-template")?.value || "").trim(),
        name: (document.getElementById("authoring-name")?.value || "").trim(),
        title: (document.getElementById("authoring-title")?.value || "").trim(),
        archetype: (document.getElementById("authoring-archetype")?.value || "").trim(),
        personaTemplate: (document.getElementById("authoring-persona-template")?.value || "").trim(),
        carrierTemplate: (document.getElementById("authoring-carrier-template")?.value || "").trim(),
        carrierNpcId: parseInt(document.getElementById("authoring-carrier-npc-id")?.value || "0", 10) || 0,
        autoSpawnOnBoot: (document.getElementById("authoring-auto-spawn")?.value || "false") === "true",
        spawnProfile: {
          mode: (document.getElementById("authoring-spawn-mode")?.value || "").trim(),
          zone: (document.getElementById("authoring-spawn-zone")?.value || "").trim(),
          x: parseInt(document.getElementById("authoring-spawn-x")?.value || "0", 10) || 0,
          y: parseInt(document.getElementById("authoring-spawn-y")?.value || "0", 10) || 0,
          z: parseInt(document.getElementById("authoring-spawn-z")?.value || "0", 10) || 0,
          heading: parseInt(document.getElementById("authoring-spawn-heading")?.value || "0", 10) || 0,
        },
        channels: channels ?? {},
        fallbackProfile: (document.getElementById("authoring-fallback-profile")?.value || "").trim(),
        availabilityProfile: (document.getElementById("authoring-availability-profile")?.value || "").trim(),
        presentationCarrierTemplate: base.presentationCarrierTemplate || "",
        presentationCarrierNpcId: Number(base.presentationCarrierNpcId || 0),
        speciesTag: (document.getElementById("authoring-species-tag")?.value || "").trim(),
        familyTag: (document.getElementById("authoring-family-tag")?.value || "").trim(),
      };
      if (adventurerProfile && Object.keys(adventurerProfile).length) {
        entry.adventurerProfile = adventurerProfile;
      } else if ("adventurerProfile" in entry) {
        delete entry.adventurerProfile;
      }
      return entry;
    }

    async function loadAuthoringEntry() {
      if (!activeId) {
        return;
      }
      setAuthoringStatus("Loading source entry...");
      try {
        const payload = await fetchJson("/studio/content/fpcs/" + encodeURIComponent(activeId));
        applyAuthoringEntry(payload.entry || {}, activeId);
        setAuthoringStatus("Loaded source entry: " + (payload.summary?.name || payload.entry?.name || activeId));
      } catch (error) {
        setAuthoringStatus("Could not load source entry: " + error.message);
      }
    }

    async function reloadFpcDefinitionsForStudio(targetId = "") {
      const commandFpcId = (targetId || activeId || authoringSourceId || "marc").toLowerCase();
      const queued = await postJson("/studio/commands", { action: "reload_fpc_definitions", fpcId: commandFpcId });
      const result = await pollCommandResult(queued.commandId);
      return result;
    }

    async function saveAuthoringEntry(mode = "replace", reloadAfterSave = false) {
      try {
        const entry = collectAuthoringEntry();
        const originalId = (document.getElementById("authoring-original-id")?.value || authoringSourceId || activeId || "").trim().toLowerCase();
        setAuthoringStatus((mode === "create" ? "Saving new entry..." : "Saving entry..."));
        const saved = await postJson("/studio/content/fpcs", {
          originalId,
          saveMode: mode,
          entry,
        });
        applyAuthoringEntry(saved.entry || entry, saved.entry?.id || originalId);
        let statusMessage = (mode === "create" ? "Created " : "Saved ") + (saved.entry?.id || entry.id) + ".";
        if (reloadAfterSave) {
          setAuthoringStatus(statusMessage + " Reloading definitions...");
          const reload = await reloadFpcDefinitionsForStudio(saved.entry?.id || entry.id);
          statusMessage += " " + (reload.message || "Reloaded definitions.");
          await new Promise(resolve => setTimeout(resolve, 800));
          await refreshStudio();
          if (saved.entry?.id) {
            await loadDetail(saved.entry.id.toLowerCase());
          }
        }
        setAuthoringStatus(statusMessage);
      } catch (error) {
        setAuthoringStatus("Authoring save failed: " + error.message);
      }
    }

