    function applyFpcTemplateAuthoringEntry(entry, sourceId = "") {
      latestFpcTemplateAuthoringEntry = entry || null;
      fpcTemplateAuthoringSourceId = (sourceId || entry?.templateId || activeDefinition?.template || "").toLowerCase();
      const setValue = (id, value) => {
        const field = document.getElementById(id);
        if (field) {
          field.value = value == null ? "" : String(value);
        }
      };
      setValue("fpc-template-authoring-original-id", fpcTemplateAuthoringSourceId);
      setValue("fpc-template-authoring-template-id", entry?.templateId || activeDefinition?.template || "");
      setValue("fpc-template-title", entry?.title || "");
      setValue("fpc-template-enabled", entry?.enabled === true ? "true" : (entry?.enabled === false ? "false" : ""));
      setValue("fpc-template-category", entry?.category || "");
      setValue("fpc-template-archetype", entry?.archetype || "");
      setValue("fpc-template-persona-template", entry?.personaTemplate || "");
      setValue("fpc-template-carrier-template", entry?.carrierTemplate || "");
      setValue("fpc-template-carrier-npc-id", entry?.carrierNpcId ?? "");
      setValue("fpc-template-auto-spawn", entry?.autoSpawnOnBoot === true ? "true" : (entry?.autoSpawnOnBoot === false ? "false" : ""));
      setValue("fpc-template-talkable", entry?.talkable === true ? "true" : (entry?.talkable === false ? "false" : ""));
      setValue("fpc-template-fallback-profile", entry?.fallbackProfile || "");
      setValue("fpc-template-availability-profile", entry?.availabilityProfile || "");
      setValue("fpc-template-fpc-tag", entry?.fpcTag || "");
      setValue("fpc-template-presentation-mode", entry?.presentationMode || "");
      setValue("fpc-template-carrier-policy", entry?.carrierPolicy || "");
      setValue("fpc-template-presentation-carrier-template", entry?.presentationCarrierTemplate || "");
      setValue("fpc-template-presentation-carrier-npc-id", entry?.presentationCarrierNpcId ?? "");
      setValue("fpc-template-species-tag", entry?.speciesTag || "");
      setValue("fpc-template-family-tag", entry?.familyTag || "");
      setValue("fpc-template-spawn-profile", prettyJson(entry?.spawnProfile || {}));
      setValue("fpc-template-channels", prettyJson(entry?.channels || {}));
      setValue("fpc-template-adventurer-profile", prettyJson(entry?.adventurerProfile || {}));
      const filePath = document.getElementById("fpc-template-file-path");
      if (filePath) {
        filePath.textContent = "Source file: dist/game/data/fake_players/fpc_templates.json";
      }
    }

    function collectFpcTemplateAuthoringEntry() {
      const parseJsonField = (id, label) => {
        const raw = document.getElementById(id)?.value || "";
        if (!raw.trim()) {
          return null;
        }
        try {
          const parsed = JSON.parse(raw);
          if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
            throw new Error(label + " must be a JSON object.");
          }
          return parsed;
        } catch (error) {
          throw new Error(label + " is not valid JSON: " + error.message);
        }
      };
      const addIfPresent = (target, key, value) => {
        if (value == null) {
          return;
        }
        if (typeof value === "string" && !value.trim()) {
          return;
        }
        target[key] = value;
      };
      const parseOptionalInt = (id) => {
        const raw = document.getElementById(id)?.value || "";
        if (!String(raw).trim()) {
          return null;
        }
        return parseInt(raw, 10) || 0;
      };
      const parseOptionalBool = (id) => {
        const raw = document.getElementById(id)?.value || "";
        if (!String(raw).trim()) {
          return null;
        }
        return raw === "true";
      };
      const base = latestFpcTemplateAuthoringEntry && typeof latestFpcTemplateAuthoringEntry === "object" ? { ...latestFpcTemplateAuthoringEntry } : {};
      const spawnProfile = parseJsonField("fpc-template-spawn-profile", "Spawn Profile");
      const channels = parseJsonField("fpc-template-channels", "Channels");
      const adventurerProfile = parseJsonField("fpc-template-adventurer-profile", "Adventurer Profile");
      const entry = {
        ...base,
        templateId: (document.getElementById("fpc-template-authoring-template-id")?.value || activeDefinition?.template || "").trim().toLowerCase(),
      };
      addIfPresent(entry, "title", document.getElementById("fpc-template-title")?.value || "");
      addIfPresent(entry, "enabled", parseOptionalBool("fpc-template-enabled"));
      addIfPresent(entry, "category", document.getElementById("fpc-template-category")?.value || "");
      addIfPresent(entry, "archetype", document.getElementById("fpc-template-archetype")?.value || "");
      addIfPresent(entry, "personaTemplate", document.getElementById("fpc-template-persona-template")?.value || "");
      addIfPresent(entry, "carrierTemplate", document.getElementById("fpc-template-carrier-template")?.value || "");
      addIfPresent(entry, "carrierNpcId", parseOptionalInt("fpc-template-carrier-npc-id"));
      addIfPresent(entry, "autoSpawnOnBoot", parseOptionalBool("fpc-template-auto-spawn"));
      addIfPresent(entry, "talkable", parseOptionalBool("fpc-template-talkable"));
      addIfPresent(entry, "fallbackProfile", document.getElementById("fpc-template-fallback-profile")?.value || "");
      addIfPresent(entry, "availabilityProfile", document.getElementById("fpc-template-availability-profile")?.value || "");
      addIfPresent(entry, "fpcTag", document.getElementById("fpc-template-fpc-tag")?.value || "");
      addIfPresent(entry, "presentationMode", document.getElementById("fpc-template-presentation-mode")?.value || "");
      addIfPresent(entry, "carrierPolicy", document.getElementById("fpc-template-carrier-policy")?.value || "");
      addIfPresent(entry, "presentationCarrierTemplate", document.getElementById("fpc-template-presentation-carrier-template")?.value || "");
      addIfPresent(entry, "presentationCarrierNpcId", parseOptionalInt("fpc-template-presentation-carrier-npc-id"));
      addIfPresent(entry, "speciesTag", document.getElementById("fpc-template-species-tag")?.value || "");
      addIfPresent(entry, "familyTag", document.getElementById("fpc-template-family-tag")?.value || "");
      if (spawnProfile && Object.keys(spawnProfile).length) {
        entry.spawnProfile = spawnProfile;
      } else {
        delete entry.spawnProfile;
      }
      if (channels && Object.keys(channels).length) {
        entry.channels = channels;
      } else {
        delete entry.channels;
      }
      if (adventurerProfile && Object.keys(adventurerProfile).length) {
        entry.adventurerProfile = adventurerProfile;
      } else {
        delete entry.adventurerProfile;
      }
      return entry;
    }

    async function loadFpcTemplateAuthoringEntry() {
      const targetId = currentTemplateTargetId();
      if (!targetId) {
        applyFpcTemplateAuthoringEntry({ templateId: "" }, "");
        setFpcTemplateAuthoringStatus("No source template is selected yet. Pick or type a template id to begin.");
        return;
      }
      setFpcTemplateAuthoringStatus("Loading FPC template...");
      try {
        const payload = await fetchJson("/studio/content/fpc-templates/" + encodeURIComponent(targetId));
        applyFpcTemplateAuthoringEntry(payload.entry || {}, targetId);
        setFpcTemplateAuthoringStatus("Loaded FPC template: " + (payload.entry?.templateId || targetId));
      } catch (error) {
        applyFpcTemplateAuthoringEntry({ templateId: targetId }, targetId);
        setFpcTemplateAuthoringStatus("No existing FPC template found for " + targetId + ". You can create one.");
      }
    }

