    function renderReplyBankEntryOptions(entries) {
      const select = document.getElementById("reply-bank-entry-select");
      if (!select) {
        return;
      }
      if (!Array.isArray(entries) || !entries.length) {
        select.innerHTML = `<option value="">No matching entries</option>`;
        return;
      }
      select.innerHTML = entries.map(item => {
        const summary = item.summary || {};
        const label = [
          "#" + String(item.index),
          summary.category || "unknown",
          summary.channel || "any",
          summary.audience || "any",
          summary.preview || ""
        ].filter(Boolean).join(" | ");
        return `<option value="${esc(String(item.index))}">${esc(label)}</option>`;
      }).join("");
    }

    function selectReplyBankAuthoringEntry() {
      const select = document.getElementById("reply-bank-entry-select");
      const selectedIndex = String(select?.value || "");
      const match = latestReplyBankAuthoringEntries.find(item => String(item.index) === selectedIndex);
      if (match) {
        applyReplyBankAuthoringEntry(match.entry || {}, match.index);
        setReplyBankAuthoringStatus("Loaded reply bank entry #" + String(match.index) + ".");
        return;
      }
      const filters = replyBankFilterValues();
      applyReplyBankAuthoringEntry({ fpcId: filters.fpcId || activeId || "", bankType: filters.bankType || "social", channel: filters.channel || "whisper", audience: filters.audience || "playerone" }, "");
      setReplyBankAuthoringStatus("No matching entry selected. You can create one.");
    }

    async function loadReplyBankAuthoringEntries(preferredIndex = "") {
      if (!activeId) {
        return;
      }
      const filters = replyBankFilterValues();
      if (!filters.fpcId) {
        filters.fpcId = activeId;
        const fpcField = document.getElementById("reply-bank-filter-fpc-id");
        if (fpcField) {
          fpcField.value = filters.fpcId;
        }
      }
      setReplyBankAuthoringStatus("Loading reply bank entries...");
      try {
        const query = new URLSearchParams();
        Object.entries(filters).forEach(([key, value]) => {
          if (String(value || "").trim()) {
            query.set(key, String(value).trim());
          }
        });
        const payload = await fetchJson("/studio/content/reply-banks?" + query.toString());
        latestReplyBankAuthoringEntries = Array.isArray(payload.entries) ? payload.entries : [];
        renderReplyBankEntryOptions(latestReplyBankAuthoringEntries);
        const select = document.getElementById("reply-bank-entry-select");
        const desiredIndex = preferredIndex !== "" && preferredIndex != null
          ? String(preferredIndex)
          : (replyBankAuthoringSourceIndex !== "" ? String(replyBankAuthoringSourceIndex) : (latestReplyBankAuthoringEntries[0] ? String(latestReplyBankAuthoringEntries[0].index) : ""));
        if (select) {
          select.value = desiredIndex;
        }
        if (desiredIndex) {
          selectReplyBankAuthoringEntry();
        } else {
          applyReplyBankAuthoringEntry({ fpcId: filters.fpcId || activeId || "", bankType: filters.bankType || "social", channel: filters.channel || "whisper", audience: filters.audience || "playerone" }, "");
          setReplyBankAuthoringStatus("No matching reply bank entries. You can create one.");
        }
      } catch (error) {
        latestReplyBankAuthoringEntries = [];
        renderReplyBankEntryOptions([]);
        applyReplyBankAuthoringEntry({ fpcId: activeId || "", bankType: "social", channel: "whisper", audience: "playerone" }, "");
        setReplyBankAuthoringStatus("Could not load reply bank entries: " + error.message);
      }
    }

