    function setKnowledgeCardAuthoringStatus(message) {
      const line = document.getElementById("knowledge-card-authoring-status");
      if (line) {
        line.textContent = String(message ?? "");
      }
      setLabStatus(message);
    }

    function knowledgeCardFilterValues() {
      return {
        fpcId: (document.getElementById("knowledge-card-filter-fpc-id")?.value || activeId || "").trim().toLowerCase(),
        domain: (document.getElementById("knowledge-card-filter-domain")?.value || "").trim(),
        questionType: (document.getElementById("knowledge-card-filter-question-type")?.value || "").trim(),
        channel: (document.getElementById("knowledge-card-filter-channel")?.value || "").trim(),
        audience: (document.getElementById("knowledge-card-filter-audience")?.value || "").trim(),
        topicId: (document.getElementById("knowledge-card-filter-topic-id")?.value || "").trim(),
        contains: (document.getElementById("knowledge-card-filter-contains")?.value || "").trim(),
      };
    }

    function applyKnowledgeCardAuthoringEntry(entry, sourceIndex = "") {
      latestKnowledgeCardAuthoringEntry = entry || null;
      knowledgeCardAuthoringSourceIndex = sourceIndex === "" || sourceIndex == null ? "" : String(sourceIndex);
      const setValue = (id, value) => {
        const field = document.getElementById(id);
        if (field) {
          field.value = value == null ? "" : String(value);
        }
      };
      setValue("knowledge-card-original-index", knowledgeCardAuthoringSourceIndex);
      setValue("knowledge-card-fpc-id", entry?.fpcId || activeId || "");
      setValue("knowledge-card-topic-id", entry?.topicId || "");
      setValue("knowledge-card-domain", entry?.domain || "");
      setValue("knowledge-card-question-type", entry?.questionType || "");
      setValue("knowledge-card-channel", entry?.channel || "any");
      setValue("knowledge-card-audience", entry?.audience || "any");
      setValue("knowledge-card-triggers", entry?.triggers || "");
      setValue("knowledge-card-priority", entry?.priority ?? 0);
      setValue("knowledge-card-summary", entry?.summary || "");
      setValue("knowledge-card-facts", entry?.facts || "");
      setValue("knowledge-card-general-answer", entry?.generalAnswer || "");
      setValue("knowledge-card-whisper-answer", entry?.whisperAnswer || "");
      setValue("knowledge-card-short-advice", entry?.shortAdvice || "");
      setValue("knowledge-card-confidence-hint", entry?.confidenceHint || "");
      const filePath = document.getElementById("knowledge-card-file-path");
      if (filePath) {
        filePath.textContent = "Source file: dist/game/data/fake_players/knowledge_cards.json";
      }
    }

    function collectKnowledgeCardAuthoringEntry() {
      const base = latestKnowledgeCardAuthoringEntry && typeof latestKnowledgeCardAuthoringEntry === "object" ? { ...latestKnowledgeCardAuthoringEntry } : {};
      return {
        ...base,
        fpcId: (document.getElementById("knowledge-card-fpc-id")?.value || activeId || "").trim().toLowerCase(),
        topicId: (document.getElementById("knowledge-card-topic-id")?.value || "").trim().toLowerCase(),
        domain: (document.getElementById("knowledge-card-domain")?.value || "").trim(),
        questionType: (document.getElementById("knowledge-card-question-type")?.value || "").trim(),
        channel: (document.getElementById("knowledge-card-channel")?.value || "").trim(),
        audience: (document.getElementById("knowledge-card-audience")?.value || "").trim(),
        triggers: (document.getElementById("knowledge-card-triggers")?.value || "").trim(),
        priority: parseInt(document.getElementById("knowledge-card-priority")?.value || "0", 10) || 0,
        summary: (document.getElementById("knowledge-card-summary")?.value || "").trim(),
        facts: (document.getElementById("knowledge-card-facts")?.value || "").trim(),
        generalAnswer: (document.getElementById("knowledge-card-general-answer")?.value || "").trim(),
        whisperAnswer: (document.getElementById("knowledge-card-whisper-answer")?.value || "").trim(),
        shortAdvice: (document.getElementById("knowledge-card-short-advice")?.value || "").trim(),
        confidenceHint: (document.getElementById("knowledge-card-confidence-hint")?.value || "").trim(),
      };
    }

    function renderKnowledgeCardEntryOptions(entries) {
      const select = document.getElementById("knowledge-card-entry-select");
      if (!select) {
        return;
      }
      if (!Array.isArray(entries) || !entries.length) {
        select.innerHTML = `<option value="">No matching entries</option>`;
        return;
      }
      select.innerHTML = entries.map(item => {
        const summary = item.summary || {};
        const label = [
          "#" + String(item.index),
          summary.topicId || "unknown",
          summary.questionType || "unknown",
          summary.domain || "general",
          summary.preview || ""
        ].filter(Boolean).join(" | ");
        return `<option value="${esc(String(item.index))}">${esc(label)}</option>`;
      }).join("");
    }

    function selectKnowledgeCardAuthoringEntry() {
      const select = document.getElementById("knowledge-card-entry-select");
      const selectedIndex = String(select?.value || "");
      const match = latestKnowledgeCardAuthoringEntries.find(item => String(item.index) === selectedIndex);
      if (match) {
        applyKnowledgeCardAuthoringEntry(match.entry || {}, match.index);
        setKnowledgeCardAuthoringStatus("Loaded knowledge card #" + String(match.index) + ".");
        return;
      }
      const filters = knowledgeCardFilterValues();
      applyKnowledgeCardAuthoringEntry({ fpcId: filters.fpcId || activeId || "", domain: filters.domain || "general", questionType: filters.questionType || "unknown", channel: filters.channel || "any", audience: filters.audience || "any" }, "");
      setKnowledgeCardAuthoringStatus("No matching knowledge card selected. You can create one.");
    }

    async function loadKnowledgeCardAuthoringEntries(preferredIndex = "") {
      if (!activeId) {
        return;
      }
      const filters = knowledgeCardFilterValues();
      if (!filters.fpcId) {
        filters.fpcId = activeId;
        const fpcField = document.getElementById("knowledge-card-filter-fpc-id");
        if (fpcField) {
          fpcField.value = filters.fpcId;
        }
      }
      setKnowledgeCardAuthoringStatus("Loading knowledge cards...");
      try {
        const query = new URLSearchParams();
        Object.entries(filters).forEach(([key, value]) => {
          if (String(value || "").trim()) {
            query.set(key, String(value).trim());
          }
        });
        const payload = await fetchJson("/studio/content/knowledge-cards?" + query.toString());
        latestKnowledgeCardAuthoringEntries = Array.isArray(payload.entries) ? payload.entries : [];
        renderKnowledgeCardEntryOptions(latestKnowledgeCardAuthoringEntries);
        const select = document.getElementById("knowledge-card-entry-select");
        const desiredIndex = preferredIndex !== "" && preferredIndex != null
          ? String(preferredIndex)
          : (knowledgeCardAuthoringSourceIndex !== "" ? String(knowledgeCardAuthoringSourceIndex) : (latestKnowledgeCardAuthoringEntries[0] ? String(latestKnowledgeCardAuthoringEntries[0].index) : ""));
        if (select) {
          select.value = desiredIndex;
        }
        if (desiredIndex) {
          selectKnowledgeCardAuthoringEntry();
        } else {
          applyKnowledgeCardAuthoringEntry({ fpcId: filters.fpcId || activeId || "", domain: filters.domain || "general", questionType: filters.questionType || "unknown", channel: filters.channel || "any", audience: filters.audience || "any" }, "");
          setKnowledgeCardAuthoringStatus("No matching knowledge cards. You can create one.");
        }
      } catch (error) {
        latestKnowledgeCardAuthoringEntries = [];
        renderKnowledgeCardEntryOptions([]);
        applyKnowledgeCardAuthoringEntry({ fpcId: activeId || "", domain: "general", questionType: "unknown", channel: "any", audience: "any" }, "");
        setKnowledgeCardAuthoringStatus("Could not load knowledge cards: " + error.message);
      }
    }

    async function reloadKnowledgeCardsForStudio(targetId = "") {
      const commandFpcId = (targetId || activeId || "marc").toLowerCase();
      const queued = await postJson("/studio/commands", { action: "reload_knowledge_cards", fpcId: commandFpcId });
      return pollCommandResult(queued.commandId);
    }

