    function renderCreationEngineRefinementSurface() {
      const summary = document.getElementById("creation-engine-refinement-summary");
      const wargSummary = document.getElementById("creation-engine-warg-summary");
      const wargFollowthroughSummary = document.getElementById("creation-engine-warg-scene-summary");
      const wargContinuitySummary = document.getElementById("creation-engine-warg-continuity-summary");
      const clearButton = document.getElementById("creation-engine-refinement-clear");
      const wargClearButton = document.getElementById("creation-engine-warg-clear");
      const wargFollowthroughClearButton = document.getElementById("creation-engine-warg-scene-clear");
      const wargContinuityClearButton = document.getElementById("creation-engine-warg-continuity-clear");
      if (!summary) {
        return;
      }
      const rows = creationEngineRefinementRows();
      const wargRows = creationEngineWargBehaviorRows();
      const wargFollowthroughRows = creationEngineWargFollowthroughRows();
      const wargContinuityRows = creationEngineWargContinuityRows();
      if (!rows.length) {
        summary.innerHTML = `No post-generation tuning is active yet. These fields will persist inside saved creation projects and Studio blueprint exports once you apply them.`;
      } else {
        summary.innerHTML = renderSimpleList(rows);
      }
      if (wargSummary) {
        if (!wargRows.length) {
          wargSummary.innerHTML = `No Warg-specific server-life tuning is active yet. Use this when you want the draft to sound more like a real Warg player or social regular instead of a generic helper.`;
        } else {
          wargSummary.innerHTML = renderSimpleList(wargRows);
        }
      }
      if (wargFollowthroughSummary) {
        if (!wargFollowthroughRows.length) {
          wargFollowthroughSummary.innerHTML = `No Warg scene or continuity follow-through tuning is active yet. Use this when you want second encounters, party judgment, and scene pressure to feel more server-native instead of generic.`;
        } else {
          wargFollowthroughSummary.innerHTML = renderSimpleList(wargFollowthroughRows);
        }
      }
      if (wargContinuitySummary) {
        if (!wargContinuityRows.length) {
          wargContinuitySummary.innerHTML = `No Warg return-memory anchors are active yet. Use these when you want helped-before, ditching, flame, and shared-death replies to stay human instead of resetting to polite filler.`;
        } else {
          wargContinuitySummary.innerHTML = renderSimpleList(wargContinuityRows);
        }
      }
      if (clearButton) {
        clearButton.disabled = !(rows.length || wargRows.length || wargFollowthroughRows.length || wargContinuityRows.length);
      }
      if (wargClearButton) {
        wargClearButton.disabled = !wargRows.length;
      }
      if (wargFollowthroughClearButton) {
        wargFollowthroughClearButton.disabled = !wargFollowthroughRows.length;
      }
      if (wargContinuityClearButton) {
        wargContinuityClearButton.disabled = !wargContinuityRows.length;
      }
    }

    function applyCreationEngineRefinements() {
      previewCreationEngineBlueprint(false);
      renderCreationEngineRefinementSurface();
      setCreationStatus(hasCreationEngineRefinements()
        ? "Applied the current creator tuning to the Studio blueprint. Re-run exact bundle preview when you want the downstream bundle refresh."
        : "Refreshed the Studio blueprint with the current default world DNA.");
      scrollToElementId("creation-engine-preview");
    }

