      const engineState = snapshot.engineState && typeof snapshot.engineState === "object"
        ? snapshot.engineState
        : {};
      activeCreationEngineRoleIndex = Math.max(parseInt(snapshot.activeRoleIndex ?? activeCreationEngineRoleIndex ?? 0, 10) || 0, 0);
      setFieldValue("creation-project-name", snapshot.projectName || engineState.worldName || "");
      setFieldValue("creation-engine-host", engineState.hostId || "mobius_tier_a");
      setFieldValue("creation-engine-world-name", engineState.worldName || "");
