    function inferCreationWorldNameFromBrief(briefText, toneId, programId) {
      const text = String(briefText || "").trim().toLowerCase();
      if (!text) {
        return "";
      }
      const seededText = studioSlug(`${toneId || "tone"}_${programId || "program"}_${text}`, "studio_world");
      let hash = 0;
      for (let i = 0; i < seededText.length; i++) {
        hash = ((hash * 31) + seededText.charCodeAt(i)) >>> 0;
      }
      let prefixes = ["Stone", "Willow", "Lantern", "Silver", "Quiet", "River"];
      if (toneId === "guarded_tragic") {
        prefixes = ["Nightfall", "Ashen", "Gloam", "Veil", "Raven", "Dusk"];
      } else if (toneId === "severe_hardworld") {
        prefixes = ["Iron", "Black", "Stone", "Grim", "Dust", "Hard"];
      } else if (toneId === "playful_bright") {
        prefixes = ["Bright", "Lark", "Honey", "Sun", "Merry", "Willow"];
      } else if (toneId === "mythic_formal") {
        prefixes = ["Aurel", "Moon", "Crown", "Star", "Elder", "Silver"];
      }
      let suffixes = ["Harbor", "Crossing", "Gate", "Reach", "Market", "Ward"];
      if (programId === "companion_adventurer" || programId === "companion_party") {
        suffixes = ["Watch", "March", "Road", "Company", "Keep", "Trail"];
      } else if (programId === "guides_mentors") {
        suffixes = ["Lantern", "Archive", "Hall", "Way", "Haven", "Crossing"];
      } else if (programId === "ambient_locals") {
        suffixes = ["Quarter", "Lane", "Ward", "Square", "Harbor", "Row"];
      } else if (programId === "rivals_faction") {
        suffixes = ["Bastion", "Ward", "Reach", "Line", "March", "Court"];
      }
      const prefix = prefixes[hash % prefixes.length];
      const suffix = suffixes[Math.floor(hash / Math.max(prefixes.length, 1)) % suffixes.length];
      return `${prefix} ${suffix}`;
    }

