        personaTemplate: keepIdentity ? (fieldValue("creation-persona-template") || tutorialSeed.personaTemplate || "origin_guide") : (tutorialSeed.personaTemplate || "origin_guide"),
        familyTag: keepIdentity ? (fieldValue("creation-family-tag") || "studio_mobius_warg_town_socials_drafts") : "studio_mobius_warg_town_socials_drafts",
