    async function runWargFirstTutorialNext(expectedActionId = "") {
      const tutorial = currentWargFirstTutorialState();
      const nextAction = wargFirstTutorialNextAction(tutorial);
      const actionId = String(expectedActionId || nextAction?.id || "").trim().toLowerCase();
      switch (actionId) {
        case "load_starter":
          loadWargFirstTutorialStarter(false);
          return;
        case "generate":
          await generateCreationFromBrief(false);
          latestWargFirstTutorialProgress.generated = Boolean(currentCreationJourneyState()?.hasBlueprint);
          latestWargFirstTutorialProgress.previewed = false;
          rerenderCreationProofAwareSurfaces();
          return;
        case "preview":
          await applyCreationEngineBlueprint(true);
          latestWargFirstTutorialProgress.generated = Boolean(currentCreationJourneyState()?.hasBlueprint);
          latestWargFirstTutorialProgress.previewed = Boolean(currentCreationJourneyState()?.hasExactPreview);
          rerenderCreationProofAwareSurfaces();
          return;
        case "save_project":
          await saveCreationProject();
          return;
        case "create":
          await createMyWorldNow();
          return;
        case "probe":
          await runWargFirstTutorialProofStep();
          return;
        case "bundle_publish":
          await runCreationJourneyBundle("publish");
          return;
        case "bundle_dev_review":
          await runCreationJourneyBundle("dev_review");
          return;
        case "save_publish":
          await saveCreationPublish();
          return;
        case "open_library":
          openWargFirstTutorialLibrary();
          return;
        default:
          setCreationStatus("Studio could not find the next tutorial step yet.");
          return;
      }
    }

