    async function loadCreationLibraryPackageFocus(packageKey, publishId = "") {
      const groups = buildCreationPublishRegistryGroups(latestCreationPublishes);
      const group = groups.find(entry => String(entry?.packageKey || "").trim().toLowerCase() === String(packageKey || "").trim().toLowerCase());
      if (!group) {
        activeCreationLibraryPackageKey = "";
        latestCreationLibraryFocus = null;
        renderCreationLibraryFocus();
        return;
      }
      activeCreationLibraryPackageKey = group.packageKey;
      if (String(activeCreationLibraryComparePackageKey || "").trim().toLowerCase() === String(group.packageKey || "").trim().toLowerCase()) {
        activeCreationLibraryComparePackageKey = "";
      }
      latestCreationLibraryFocus = {
        loading: true,
        packageKey: group.packageKey,
        group,
      };
      renderCreationLibraryFocus();
      try {
        const targetId = publishId || group.activeEntry?.id || group.entries?.[0]?.id || "";
        const publish = targetId ? await fetchJson("/studio/creation-publishes/" + encodeURIComponent(targetId)) : null;
        latestCreationLibraryFocus = {
          loading: false,
          packageKey: group.packageKey,
          group,
          publish,
          passport: buildCreationLibraryPassport(group, publish),
        };
      } catch (error) {
        latestCreationLibraryFocus = {
          loading: false,
          error: error.message,
          packageKey: group.packageKey,
          group,
        };
      }
      renderCreationLibraryFocus();
    }

    function renderCreationLibraryEntrySummary(options = {}) {
      const groups = Array.isArray(options?.groups) ? options.groups : [];
      const filteredGroups = Array.isArray(options?.filteredGroups) ? options.filteredGroups : groups;
      const visibleFamilyContexts = Array.isArray(options?.visibleFamilyContexts) ? options.visibleFamilyContexts : [];
      const hostCount = Number(options?.hostCount || 0);
      const familyCount = Number(options?.familyCount || 0);
      const keptCount = Number(options?.keptCount || 0);
      const handoffCount = Number(options?.handoffCount || 0);
      const derivedCount = Number(options?.derivedCount || 0);
      const proofCounts = options?.proofCounts || {};
      const workflowCounts = options?.workflowCounts || {};
      const topRow = studioPrimaryWorkflowRow(workflowCounts, {
        includePublishRecord: false,
        includeRefineLocal: true,
        includeArchived: true,
      });
      const familyAction = topRow ? studioLibraryRoomGuideFollowthrough(topRow, visibleFamilyContexts) : null;
      const firstContext = visibleFamilyContexts[0] || null;
      const firstFamilyKey = String(firstContext?.familyKey || "").trim();
      const canOpenCompare = Boolean(firstFamilyKey) && Boolean(creationLibraryFamilyCompareTargetGroup(firstContext));
      const laneCounts = creationLibraryFamilyBoardLaneCounts(visibleFamilyContexts);
      const summaryActions = studioEntrySummaryRoomDeckActions({
        scopeId: "library",
        visibleFamilyCount: visibleFamilyContexts.length,
        laneCounts,
      });
      return renderStudioEntrySummaryCard({
        id: "creation-library-entry-summary",
        title: "Library Entry Summary",
        body: "World Library now opens with the same room, proof, workflow, and family language that Saved Projects and Publish Records use.",
        lines: [
          `Visible world packages: ${filteredGroups.length} of ${groups.length}`,
          `Visible world families: ${visibleFamilyContexts.length} of ${familyCount}`,
          `Hosts covered: ${hostCount} | Kept baselines: ${keptCount} | Dev-side queue: ${handoffCount} | Derived worlds: ${derivedCount}`,
          `Proof snapshot: ${creationProofCountsCompactSummary(proofCounts)}`,
          `Workflow snapshot: ${creationWorkflowCountsSummary(workflowCounts) || "No next-move counts are active yet."}`,
          `Family room deck: ${studioRoomDeckSummary(laneCounts)}`,
          studioEntrySummaryFamilyFollowthroughLine(familyAction, firstFamilyKey ? "Family follow-through: open a visible family room or root from this shelf." : "Family follow-through: no visible World Library family is available yet."),
        ],
        actionsTitle: summaryActions.length ? "Family room deck:" : "Quick family entry:",
        actions: summaryActions.length ? summaryActions : creationLibraryQuickFamilyEntryActions({
          familyAction,
          firstFamilyKey,
          canOpenCompare,
          unavailableTitle: "No visible World Library family is available yet.",
          openTitle: firstFamilyKey ? "Open the first visible World Library family room." : "No visible World Library family is available yet.",
          rootTitle: firstFamilyKey ? "Load the root world for the first visible family." : "No visible World Library family is available yet.",
          compareTitle: canOpenCompare ? "Open Family Compare for the first visible family." : "The first visible family does not have a compare target yet.",
          queueTitle: firstFamilyKey ? "Open queue review for the first visible family." : "No visible World Library family is available yet.",
          followthroughTitle: "Use the current World Library family room follow-through from this shelf.",
        }),
      });
    }
    function renderCreationLibrarySurface() {
      const dashboard = document.getElementById("creation-library-dashboard");
      const filtersHost = document.getElementById("creation-library-filters");
      const gridHost = document.getElementById("creation-library-grid");
      const draftHost = document.getElementById("creation-library-drafts");
      const focusHost = document.getElementById("creation-library-focus");
      if (!dashboard || !filtersHost || !gridHost || !focusHost) {
        return;
      }
      const groups = buildCreationPublishRegistryGroups(latestCreationPublishes);
      const filters = currentCreationLibraryFilters();
      const hostIds = Array.from(new Set(groups.map(group => String(group?.hostId || "").trim().toLowerCase()).filter(Boolean))).sort();
      const programIds = Array.from(new Set(groups.map(group => String(group?.programId || "").trim().toLowerCase()).filter(Boolean))).sort();
      const familyLabels = creationLibraryFamilyLabels(groups);
      const familyIds = Object.keys(familyLabels).sort((left, right) => String(familyLabels[left] || left).localeCompare(String(familyLabels[right] || right), undefined, { sensitivity: "base" }));
      const toneIds = Array.from(new Set(groups.map(group => String(group?.activeEntry?.toneId || "").trim().toLowerCase()).filter(Boolean))).sort();
      const lifecycleIds = Array.from(new Set(groups.map(group => String(group?.activeEntry?.lifecycleState || "").trim().toLowerCase()).filter(Boolean))).sort();
      const filteredGroups = filteredCreationLibraryGroups(filters);
      const familyContext = currentCreationLibraryShelfFamilyContext(groups, filteredGroups, familyLabels);
      const visibleFamilyContexts = creationLibraryVisibleFamilyContexts(groups, filteredGroups, familyLabels, filters);
      const visiblePendingGroups = creationLibraryGroupsByProofFilter("pending", filteredGroups);
      const visibleCreatedGroups = creationLibraryGroupsByProofFilter("created", filteredGroups);
      const visiblePartialGroups = creationLibraryGroupsByProofFilter("partial", filteredGroups);
      const visibleProvedGroups = creationLibraryGroupsByProofFilter("proved", filteredGroups);
      const visibleCreateOutputGroups = creationLibraryGroupsByWorkflowRecommendation("create_output", filteredGroups);
      const visibleFinishProofGroups = creationLibraryGroupsByWorkflowRecommendation("finish_proof", filteredGroups);
      const visibleQueueWorkflowGroups = creationLibraryGroupsByWorkflowRecommendation("queue_dev_review", filteredGroups);
      const visibleReviewQueueGroups = creationLibraryGroupsByWorkflowRecommendation("review_dev_queue", filteredGroups);
      const visibleKeepBaselineGroups = creationLibraryGroupsByWorkflowRecommendation("keep_baseline", filteredGroups);
      const visibleResumeJourneyGroups = creationLibraryGroupsByWorkflowRecommendation("resume_journey", filteredGroups);
      const proofCounts = creationLibraryProofCounts(groups);
      const workflowCounts = creationLibraryWorkflowCounts(groups);
      const workflowTopRow = studioPrimaryWorkflowRow(workflowCounts, {
        includePublishRecord: false,
        includeRefineLocal: true,
        includeArchived: true,
      });
      const workflowFollowthroughAction = workflowTopRow ? studioLibraryRoomGuideFollowthrough(workflowTopRow, visibleFamilyContexts) : null;
      const workflowFollowthroughLine = studioEntrySummaryFamilyFollowthroughLine(
        workflowFollowthroughAction,
        visibleFamilyContexts.length
          ? "Family follow-through: open a visible World Library family room or root from this dashboard."
          : "Family follow-through: no visible World Library family is available yet."
      );
      const workflowFollowthroughActions = (() => {
        const roomDeckActions = studioEntrySummaryRoomDeckActions({
          scopeId: "library",
          visibleFamilyCount: visibleFamilyContexts.length,
          laneCounts: creationLibraryFamilyBoardLaneCounts(visibleFamilyContexts),
        });
        if (roomDeckActions.length) {
          return roomDeckActions;
        }
        const firstFamilyKey = String(visibleFamilyContexts[0]?.familyKey || "").trim();
        return [
          studioEntrySummaryPrimaryAction(workflowFollowthroughAction, {
            label: "Open Family",
            call: firstFamilyKey ? creationLibraryFamilyActionCall("openCreationLibraryFamilyRoom", firstFamilyKey) : "",
            disabled: !firstFamilyKey,
            title: firstFamilyKey ? "Open the first visible World Library family room from the workflow dashboard." : "No visible World Library family is available yet.",
            followthroughTitle: "Use the current World Library family room follow-through from this dashboard.",
          }),
        ];
      })();
      const proofPendingCount = Number(proofCounts?.pending || 0);
      const proofCreatedCount = Number(proofCounts?.created || 0);
      const proofPartialCount = Number(proofCounts?.partial || 0);
      const proofProvedCount = Number(proofCounts?.proved || 0);
      const keptCount = groups.filter(group => String(group?.activeEntry?.lifecycleState || "").trim().toLowerCase() === "kept").length;
      const handoffCount = groups.filter(group => (group?.handoffEntries?.length || 0) > 0).length;
      const familyCount = Array.from(new Set(groups.map(group => String(group?.familyKey || group?.packageKey || "").trim().toLowerCase()).filter(Boolean))).length;
      const derivedCount = groups.filter(group => String(group?.derivationMode || "").trim().toLowerCase() !== "root").length;
      const proofPendingCardClass = `report-card report-card-button${proofPendingCount > 0 ? " report-card-active report-card-proof-pending" : ""}${filters.proofState === "pending" && proofPendingCount > 0 ? " report-card-filter-selected" : ""}`;
      const proofCreatedCardClass = `report-card report-card-button${proofCreatedCount > 0 ? " report-card-active report-card-proof-created" : ""}${filters.proofState === "created" && proofCreatedCount > 0 ? " report-card-filter-selected" : ""}`;
      const proofPartialCardClass = `report-card report-card-button${proofPartialCount > 0 ? " report-card-active report-card-proof-partial" : ""}${filters.proofState === "partial" && proofPartialCount > 0 ? " report-card-filter-selected" : ""}`;
      const proofProvedCardClass = `report-card report-card-button${proofProvedCount > 0 ? " report-card-active report-card-proof-proved" : ""}${filters.proofState === "proved" && proofProvedCount > 0 ? " report-card-filter-selected" : ""}`;
      const proofPendingTitle = proofPendingCount > 0
        ? (filters.proofState === "pending" ? "Show all world packages" : "Show only Not Created Yet world packages")
        : "No world packages are currently not created yet";
      const proofCreatedTitle = proofCreatedCount > 0
        ? (filters.proofState === "created" ? "Show all world packages" : "Show only Created Only world packages")
        : "No world packages are currently created without proof";
      const proofPartialTitle = proofPartialCount > 0
        ? (filters.proofState === "partial" ? "Show all world packages" : "Show only Proof In Progress world packages")
        : "No world packages are currently mid-proof";
      const proofProvedTitle = proofProvedCount > 0
        ? (filters.proofState === "proved" ? "Show all world packages" : "Show only Proof Captured world packages")
        : "No world packages currently carry captured proof";
      dashboard.innerHTML = `
        ${renderStudioRoomGuideDeck({
          activeScopeId: "library",
          title: "Studio Room Guide",
          body: "World Library now shares the same room guide as Runtime, Journey, and Saved Projects, so library entry stays aligned with the same creator next moves.",
          marginTop: 0,
        })}
        ${renderStudioRoomSummaryDashboard({
          activeScopeId: "library",
          helperText: "Library now leads with the same room and family follow-through cards before you drop into proof, workflow, and family filters.",
        })}
        ${renderCreationLibraryEntrySummary({
          groups,
          filteredGroups,
          visibleFamilyContexts,
          hostCount: hostIds.length,
          familyCount,
          keptCount,
          handoffCount,
          derivedCount,
          proofCounts,
          workflowCounts,
        })}
        <div class="report-dashboard" style="margin-top:12px;">
          <button type="button" class="${proofPendingCardClass}" onclick="toggleCreationLibraryProofFilter('pending')" title="${esc(proofPendingTitle)}" ${proofPendingCount < 1 ? "disabled" : ""}><div class="label">Not Created Yet</div><div class="value">${esc(proofPendingCount)}</div><div class="meta">${esc(proofPendingCount ? "packages still waiting on first created output" : "every package has created output")}</div></button>
          <button type="button" class="${proofCreatedCardClass}" onclick="toggleCreationLibraryProofFilter('created')" title="${esc(proofCreatedTitle)}" ${proofCreatedCount < 1 ? "disabled" : ""}><div class="label">Created Only</div><div class="value">${esc(proofCreatedCount)}</div><div class="meta">${esc(proofCreatedCount ? "packages created but not fully live-proved yet" : "no package is stuck at created-only")}</div></button>
          <button type="button" class="${proofPartialCardClass}" onclick="toggleCreationLibraryProofFilter('partial')" title="${esc(proofPartialTitle)}" ${proofPartialCount < 1 ? "disabled" : ""}><div class="label">Proof In Progress</div><div class="value">${esc(proofPartialCount)}</div><div class="meta">${esc(proofPartialCount ? "packages with some proof already captured" : "no package is mid-proof right now")}</div></button>
          <button type="button" class="${proofProvedCardClass}" onclick="toggleCreationLibraryProofFilter('proved')" title="${esc(proofProvedTitle)}" ${proofProvedCount < 1 ? "disabled" : ""}><div class="label">Proof Captured</div><div class="value">${esc(proofProvedCount)}</div><div class="meta">${esc(proofProvedCount ? "packages already carrying the current proof set" : "no package is fully proved yet")}</div></button>
        </div>
        ${renderCreationWorkflowDashboard(workflowCounts, {
          activeFilter: filters.workflowState,
          toggleCall: "toggleCreationLibraryWorkflowFilter",
          itemLabel: "world packages",
          includePublishRecord: false,
          followthroughTitle: visibleFamilyContexts.length > 1 ? "Family room deck:" : "Workflow follow-through:",
          followthroughActions: workflowFollowthroughActions,
          helperText: [workflowFollowthroughLine, creationLibraryWorkflowSummaryGuide(workflowCounts)].filter(Boolean).join(" "),
        })}
        ${renderCreationLibraryFamilyDashboard(visibleFamilyContexts, filters)}
        ${renderCreationLibraryFamilyEntryRoom(familyContext, filters)}
      `;
      filtersHost.innerHTML = `
        <div class="creation-library-filter-grid">
          <div class="field">
            <label>Search Worlds</label>
            <input type="text" value="${esc(creationLibraryUiState.text || "")}" placeholder="search by world, host, tone, summary" oninput="setCreationLibraryFilter('text', this.value)" />
          </div>
          <div class="field">
            <label>Host</label>
            <select onchange="setCreationLibraryFilter('hostId', this.value)">
              <option value="all"${filters.hostId === "all" ? " selected" : ""}>All Hosts</option>
              ${hostIds.map(hostId => `<option value="${esc(hostId)}"${filters.hostId === hostId ? " selected" : ""}>${esc(creationLibraryLabelForHost(hostId))}</option>`).join("")}
            </select>
          </div>
          <div class="field">
            <label>Program</label>
            <select onchange="setCreationLibraryFilter('programId', this.value)">
              <option value="all"${filters.programId === "all" ? " selected" : ""}>All Programs</option>
              ${programIds.map(programId => `<option value="${esc(programId)}"${filters.programId === programId ? " selected" : ""}>${esc(creationLibraryLabelForProgram(programId))}</option>`).join("")}
            </select>
          </div>
          <div class="field">
            <label>Family</label>
            <select onchange="setCreationLibraryFilter('familyKey', this.value)">
              ${creationProjectFacetOptions(familyIds, filters.familyKey, "All Families", familyLabels)}
            </select>
          </div>
          <div class="field">
            <label>Tone</label>
            <select onchange="setCreationLibraryFilter('toneId', this.value)">
              <option value="all"${filters.toneId === "all" ? " selected" : ""}>All Tones</option>
              ${toneIds.map(toneId => `<option value="${esc(toneId)}"${filters.toneId === toneId ? " selected" : ""}>${esc(creationLibraryLabelForTone(toneId))}</option>`).join("")}
            </select>
          </div>
          <div class="field">
            <label>Proof</label>
            <select onchange="setCreationLibraryFilter('proofState', this.value)">
              <option value="all"${filters.proofState === "all" ? " selected" : ""}>All Proof States</option>
              <option value="pending"${filters.proofState === "pending" ? " selected" : ""}>Not Created Yet</option>
              <option value="created"${filters.proofState === "created" ? " selected" : ""}>Created Only</option>
              <option value="partial"${filters.proofState === "partial" ? " selected" : ""}>Proof In Progress</option>
              <option value="proved"${filters.proofState === "proved" ? " selected" : ""}>Proof Captured</option>
            </select>
          </div>
          <div class="field">
            <label>Workflow</label>
            <select onchange="setCreationLibraryFilter('workflowState', this.value)">
              <option value="all"${filters.workflowState === "all" ? " selected" : ""}>All Next Moves</option>
              <option value="resume_journey"${filters.workflowState === "resume_journey" ? " selected" : ""}>Resume Journey</option>
              <option value="create_output"${filters.workflowState === "create_output" ? " selected" : ""}>Create First Output</option>
              <option value="finish_proof"${filters.workflowState === "finish_proof" ? " selected" : ""}>Finish Live Proof</option>
              <option value="queue_dev_review"${filters.workflowState === "queue_dev_review" ? " selected" : ""}>Queue For Dev</option>
              <option value="review_dev_queue"${filters.workflowState === "review_dev_queue" ? " selected" : ""}>Review Queue</option>
              <option value="keep_baseline"${filters.workflowState === "keep_baseline" ? " selected" : ""}>Keep Baseline</option>
              <option value="refine_local"${filters.workflowState === "refine_local" ? " selected" : ""}>Continue Refining</option>
              <option value="archived"${filters.workflowState === "archived" ? " selected" : ""}>Archived</option>
            </select>
          </div>
          <div class="field">
            <label>Lifecycle</label>
            <select onchange="setCreationLibraryFilter('lifecycleState', this.value)">
              <option value="all"${filters.lifecycleState === "all" ? " selected" : ""}>All Lifecycle States</option>
              ${lifecycleIds.map(lifecycleId => {
                const spec = creationPublishLifecycleSpec(lifecycleId);
                return `<option value="${esc(lifecycleId)}"${filters.lifecycleState === lifecycleId ? " selected" : ""}>${esc(spec.label)}</option>`;
              }).join("")}
            </select>
          </div>
        </div>
        <div class="creation-project-bulk-actions creation-project-bulk-actions-secondary">
          <div class="creation-project-filter-copy">Proof next steps:</div>
          <button class="btn mini" onclick="focusCreationLibraryGroupByProof('pending')" ${visiblePendingGroups.length < 1 ? "disabled" : ""}>Inspect First Pending (${esc(visiblePendingGroups.length)})</button>
          <button class="btn mini" onclick="openCreationLibraryProofGroupInCreate('created')" ${visibleCreatedGroups.length < 1 ? "disabled" : ""}>Open First Created (${esc(visibleCreatedGroups.length)})</button>
          <button class="btn mini" onclick="focusCreationLibraryGroupByProof('partial', 'next')" ${visiblePartialGroups.length < 1 ? "disabled" : ""}>Inspect Next Partial (${esc(visiblePartialGroups.length)})</button>
          <button class="btn mini" onclick="openCreationLibraryProofGroupInCreate('proved')" ${visibleProvedGroups.length < 1 ? "disabled" : ""}>Open First Proved (${esc(visibleProvedGroups.length)})</button>
        </div>
        <div class="creation-project-bulk-actions creation-project-bulk-actions-secondary">
          <div class="creation-project-filter-copy">Workflow next moves:</div>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('create_output')" ${visibleCreateOutputGroups.length < 1 ? "disabled" : ""}>Create First Output (${esc(visibleCreateOutputGroups.length)})</button>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('finish_proof')" ${visibleFinishProofGroups.length < 1 ? "disabled" : ""}>Finish Live Proof (${esc(visibleFinishProofGroups.length)})</button>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('queue_dev_review')" ${visibleQueueWorkflowGroups.length < 1 ? "disabled" : ""}>Queue For Dev (${esc(visibleQueueWorkflowGroups.length)})</button>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('review_dev_queue')" ${visibleReviewQueueGroups.length < 1 ? "disabled" : ""}>Review Queue (${esc(visibleReviewQueueGroups.length)})</button>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('keep_baseline')" ${visibleKeepBaselineGroups.length < 1 ? "disabled" : ""}>Keep Baseline (${esc(visibleKeepBaselineGroups.length)})</button>
          <button class="btn mini" onclick="runFirstCreationLibraryWorkflowAction('resume_journey')" ${visibleResumeJourneyGroups.length < 1 ? "disabled" : ""}>Resume Journey (${esc(visibleResumeJourneyGroups.length)})</button>
        </div>
        ${
          familyContext?.packet
            ? `
              <div class="creation-project-bulk-actions creation-project-bulk-actions-secondary">
                <div class="creation-project-filter-copy">Family entry:</div>
                <button class="btn mini" onclick="${creationLibraryFamilyActionCall("openCreationLibraryFamilyRoom", familyContext.familyKey)}">Open Family Room</button>
                <button class="btn mini" onclick="${creationLibraryFamilyActionCall("loadCreationLibraryFamilyRootByKey", familyContext.familyKey)}">Load Family Root</button>
                <button class="btn mini" onclick="${creationLibraryFamilyActionCall("openCreationLibraryFamilyCompareByKey", familyContext.familyKey)}" ${creationLibraryFamilyCompareTargetGroup(familyContext) ? "" : "disabled"}>Open Compare</button>
                <button class="btn mini" onclick="${creationLibraryFamilyActionCall("openCreationLibraryFamilyQueueReviewByKey", familyContext.familyKey)}">Open Queue</button>
              </div>
            `
            : ""
        }
      `;
      if (!filteredGroups.length) {
        gridHost.innerHTML = `<div class="creation-library-empty">No world packages match the current filters yet. Broaden the search or publish a world pack from Create first.</div>`;
        activeCreationLibraryPackageKey = "";
        latestCreationLibraryFocus = null;
        renderCreationLibraryFocus();
      } else {
        const focusedGroup = filteredGroups.find(group => String(group?.packageKey || "").trim().toLowerCase() === String(activeCreationLibraryPackageKey || "").trim().toLowerCase()) || null;
        const nextFocus = focusedGroup || filteredGroups[0];
        if (nextFocus && String(nextFocus.packageKey || "").trim().toLowerCase() !== String(activeCreationLibraryPackageKey || "").trim().toLowerCase()) {
          activeCreationLibraryPackageKey = nextFocus.packageKey;
          latestCreationLibraryFocus = {
            loading: true,
            packageKey: nextFocus.packageKey,
            group: nextFocus,
          };
          setTimeout(() => {
            loadCreationLibraryPackageFocus(nextFocus.packageKey, nextFocus.activeEntry?.id || "");
          }, 0);
        } else if (nextFocus && latestCreationLibraryFocus && String(latestCreationLibraryFocus.packageKey || "").trim().toLowerCase() === String(nextFocus.packageKey || "").trim().toLowerCase()) {
          latestCreationLibraryFocus = {
            ...latestCreationLibraryFocus,
            group: nextFocus,
            passport: latestCreationLibraryFocus.loading || latestCreationLibraryFocus.error
              ? latestCreationLibraryFocus.passport
              : buildCreationLibraryPassport(nextFocus, latestCreationLibraryFocus.publish),
          };
        }
        gridHost.innerHTML = filteredGroups.map(group => {
          const active = group.activeEntry || {};
          const lifecycle = creationPublishLifecycleSpec(active.lifecycleState);
          const decision = creationPublishDecisionSpec(active.decision);
          const handoff = creationPublishHandoffSpec(active.handoffState);
          const lineage = creationLineageModeSpec(group.derivationMode);
          const family = buildCreationLibraryFamilyContext(groups, group);
          const familyLabel = familyLabels[creationLibraryGroupFamilyKey(group)] || (family.rootGroup?.worldName || group.worldName || "World family");
          const compareTarget = creationLibraryFamilyCompareTargetGroup({
            focusGroup: group,
            family,
          });
          const isActive = String(group.packageKey || "").trim().toLowerCase() === String(activeCreationLibraryPackageKey || "").trim().toLowerCase();
          const toneLabel = creationLibraryLabelForTone(active.toneId);
          return `
            <div class="creation-library-card ${isActive ? "active" : ""}">
              ${renderCreationPublishedFamilyCardHeader({
                title: group.worldName || "Untitled world",
                meta: `${creationLibraryLabelForProgram(group.programId)} | ${creationLibraryLabelForHost(group.hostId)}`,
                tags: [
                  active.versionLabel || "v1",
                  lifecycle.shortLabel,
                  lineage.shortLabel,
                  handoff.id !== "none" ? handoff.shortLabel : "",
                ],
              })}
              <div class="platform-band-copy">${esc(active.summary || "Studio saved this world package as a reusable baseline.")}</div>
              ${renderCreationPublishedFamilyCardMetaBlock(active, {
                toneLabel,
                includeDecision: true,
                familyLabel,
                lineageLabel: lineage.label,
                familySize: family.familyGroups.length,
                versionCount: group.entries.length,
                archivedCount: group.archivedCount,
                marginTop: 10,
              })}
              ${renderCreationPublishWorkflowBlock(active, { packageKey: group.packageKey })}
              ${renderCreationLibraryPublishedFamilyDetailCard({
                title: `${group.worldName || active.worldName || "World package"} Package Room`,
                body: "World Library now keeps the active published package inside one family room before you inspect, load, branch, compare, or queue anything.",
                entry: active,
                familyKey: creationLibraryGroupFamilyKey(group),
                worldName: group.worldName || active.worldName || "World package",
                compareEnabled: Boolean(compareTarget),
                compareLabel: "Compare Family",
                queueLabel: "Queue Review",
                versionCount: group.entries.length,
                lines: creationPublishedFamilyRoomLines({
                  familyLabel,
                  lineageLabel: lineage.label,
                  familySize: family.familyGroups.length,
                  archivedCount: group.archivedCount,
                }),
                extraActions: [
                  {
                    label: "Inspect Passport",
                    call: `loadCreationLibraryPackageFocus(${JSON.stringify(String(group.packageKey || ""))}, ${JSON.stringify(String(active.id || ""))})`,
                    title: "Inspect the current world passport.",
                  },
                  {
                    label: "Load Active",
                    call: `loadCreationPublish(${JSON.stringify(String(active.id || ""))})`,
                    disabled: !active?.id,
                    title: active?.id ? "Load the active publish record." : "No active publish record is available yet.",
                  },
                  {
                    label: "Open In Create",
                    call: `openCreationPublishInCreate(${JSON.stringify(String(active.id || ""))})`,
                    disabled: !active?.id,
                    title: active?.id ? "Open the active world package in Create." : "No active publish record is available yet.",
                  },
                  {
                    label: "Use As Template",
                    call: `useCreationPublishAsTemplate(${JSON.stringify(String(active.id || ""))})`,
                    primary: true,
                    disabled: !active?.id,
                    title: active?.id ? "Reuse this publish as the next template baseline." : "No active publish record is available yet.",
                  },
                  {
                    label: "Variant",
                    call: `useCreationPublishAsTemplate(${JSON.stringify(String(active.id || ""))}, 'variant')`,
                    disabled: !active?.id,
                    title: active?.id ? "Branch this publish into a variant." : "No active publish record is available yet.",
                  },
                  {
                    label: "Sequel",
                    call: `useCreationPublishAsTemplate(${JSON.stringify(String(active.id || ""))}, 'sequel')`,
                    disabled: !active?.id,
                    title: active?.id ? "Branch this publish into a sequel." : "No active publish record is available yet.",
                  },
                ],
                marginTop: 10,
              })}
              ${renderCreationPublishVersionHistoryCard({
                title: "Recent Versions",
                body: "World Library now keeps nearby version history inside the same Dream Studio room language before you load, clone, compare, or queue anything.",
                lines: buildCreationPublishLowerDetailLines(active, {
                  versionLabel: "Active version",
                  includeVersionCount: true,
                  versionCount: group.entries.length,
                  extraLines: creationPublishedFamilyVersionExtraLines({
                    archivedCount: group.archivedCount,
                  }),
                }),
                actions: creationLibraryFamilyRoomActions({
                  familyKey: creationLibraryGroupFamilyKey(group),
                  compareEnabled: Boolean(compareTarget),
                  compareLabel: "Compare Family",
                  queueLabel: "Queue Review",
                }),
                activeId: activeCreationPublishId,
                entries: group.entries,
                limit: 3,
                renderTitle: (entry, entryLifecycle) => `${entry.versionLabel || "v1"} | ${entryLifecycle.label}`,
                renderMeta: entry => new Date(entry.updatedAtMs || entry.createdAtMs || Date.now()).toLocaleString(),
                renderActions: entry => renderCreationActionButtons([
                  {
                    label: "Load",
                    call: `loadCreationPublish(${JSON.stringify(String(entry.id || ""))})`,
                    disabled: !entry?.id,
                    title: entry?.id ? "Load this publish record." : "This publish record is unavailable right now.",
                  },
                  {
                    label: "Clone",
                    call: `useCreationPublishAsTemplate(${JSON.stringify(String(entry.id || ""))})`,
                    disabled: !entry?.id,
                    title: entry?.id ? "Reuse this publish as the next template baseline." : "This publish record is unavailable right now.",
                  },
                  ...creationPublishHandoffActionSpecs(entry),
                ], { mini: true }),
              })}
            </div>
          `;
        }).join("");
        renderCreationLibraryFocus();
      }
      renderCreationLibraryHandoffBoard(groups);
      if (draftHost) {
        const publishedKeys = new Set(groups.map(group => String(group?.packageKey || "").trim().toLowerCase()).filter(Boolean));
        const draftProjects = latestCreationProjects.filter(entry => {
          const packageKey = buildCreationLibraryPackageKey(entry?.worldName || entry?.name || "", entry?.hostId || "", entry?.programId || "");
          return !publishedKeys.has(packageKey);
        });
        const draftSummary = renderCreationDraftWorkspaceEntrySummary(draftProjects);
        if (!draftProjects.length) {
          draftHost.innerHTML = `
            ${draftSummary}
            <div class="muted">Every current creation project already has a publish record, or no separate draft workspaces exist yet.</div>
          `;
        } else {
          draftHost.innerHTML = `
            ${draftSummary}
            <div class="guide-card-grid">
              ${draftProjects.slice(0, 6).map(entry => `
                <div class="guide-card">
                  <div class="creation-project-head">
                    <div>
                      <div class="platform-host-title">${esc(entry.name || entry.worldName || "Creation Project")}</div>
                      <div class="creation-project-meta">${esc(creationLibraryLabelForProgram(entry.programId))} | ${esc(creationLibraryLabelForHost(entry.hostId))}</div>
                    </div>
                    <div class="tag">draft</div>
                  </div>
                  <div class="platform-band-copy">${esc(entry.summary || "Saved world-building workspace.")}</div>
                  ${renderCreationProjectWorkflowBlock(entry)}
                  ${renderCreationProjectFamilyRoomActionRow({
                    entry,
                    title: "",
                    className: "creation-library-export-row",
                    openLabel: "Open Family",
                    rootLabel: "Load Root",
                    compareLabel: "Open Compare",
                    queueLabel: "Open Queue",
                    marginTop: 10,
                  })}
                  <div class="creation-library-actions">
                    <button class="btn" onclick="loadCreationProject('${esc(entry.id)}'); setLabTab('create');">Open In Create</button>
                  </div>
                </div>
              `).join("")}
            </div>
          `;
        }
      }
    }

    function currentActiveCreationPublishEntry() {
      if (activeCreationPublishId) {
        const active = latestCreationPublishes.find(entry => String(entry?.id || "") === activeCreationPublishId);
        if (active) {
          return active;
        }
      }
      return currentCreationPublishVersionEntries()[0] || null;
    }

    function currentCreationPublishRecommendation() {
      const blueprint = latestCreationEngineBlueprint;
      if (!blueprint) {
        return null;
      }
      const outcome = currentCreationOutcome();
      const currentSingleProbe = currentCreationLiveProofResult();
      const needsPack = blueprint.scale?.id !== "single_pilot";
      const voiceSmokeEntries = Array.isArray(latestCreationProgramPackPreview?.voiceSmoke?.entries)
        ? latestCreationProgramPackPreview.voiceSmoke.entries
        : [];
      const sceneSmokeEntries = Array.isArray(latestCreationProgramPackPreview?.sceneSmoke?.entries)
        ? latestCreationProgramPackPreview.sceneSmoke.entries
        : [];
      const voiceSmokeStatus = creationSmokeProofStatus(voiceSmokeEntries);
      const sceneSmokeStatus = creationSmokeProofStatus(sceneSmokeEntries);
      const gapRows = Array.isArray(blueprint.gapWatch?.rows) ? blueprint.gapWatch.rows : [];
      const missingGapCount = gapRows.filter(item => String(item?.state || "").trim().toLowerCase() === "missing").length;
      const watchGapCount = gapRows.filter(item => String(item?.state || "").trim().toLowerCase() === "watch").length;
      const liveHost = Boolean(blueprint.game?.safeRuntime);
      const summaryLines = [];
      const proofLines = [];
      let decision = "keep_draft";

      if (!outcome) {
        summaryLines.push("Nothing permanent has been created yet, so this should stay a draft.");
      } else {
        summaryLines.push(outcome.kind === "starter_pack"
          ? `Studio already created ${outcome.createdCount} role bundle(s) for this world pack.`
          : "Studio already created the first draft bundle for this world.");
      }

      if (!liveHost) {
        decision = "needs_dev_side";
        summaryLines.push("The selected host is still source-first, so a kept pack still needs our adapter/runtime side.");
      } else if (!outcome) {
        decision = "keep_draft";
      } else if (needsPack && voiceSmokeStatus.state !== "complete") {
        decision = "keep_draft";
        summaryLines.push(voiceSmokeStatus.state === "not_run"
          ? "Run Cast Voice Smoke first so the created roles prove distinct live answers."
          : "Cast Voice Smoke ran, but some roles still need captured live lines before this pack is trustworthy.");
      } else if (needsPack && sceneSmokeStatus.state !== "complete") {
        decision = "keep_draft";
        summaryLines.push(sceneSmokeStatus.state === "not_run"
          ? "Run Scene Smoke next so the world proves its first encounters, not only its isolated voices."
          : "Scene Smoke ran, but some first-encounter lanes still came back empty and need another live pass.");
      } else if (!needsPack && !currentSingleProbe) {
        decision = "keep_draft";
        summaryLines.push("Run the first live conversation test before this counts as a kept single-NPC lane.");
      } else if (missingGapCount > 0) {
        decision = "keep_draft";
        summaryLines.push(`${missingGapCount} player-facing gap(s) are still marked missing, so the world should stay a draft for now.`);
      } else {
        decision = "ready_to_keep";
        summaryLines.push("Studio sees enough creation proof to treat this as a kept world-pack baseline.");
      }

      proofLines.push(outcome
        ? `Created output: ${outcome.kind === "starter_pack" ? `${outcome.createdCount} role bundle(s)` : "1 draft bundle"}`
        : "Created output: not created yet");
      proofLines.push(`Host path: ${liveHost ? "live runtime-capable" : "source-first / adapter still needed"}`);
      if (needsPack) {
        proofLines.push(creationSmokeProofLine("Cast voice smoke", voiceSmokeEntries, "role answer(s)"));
        proofLines.push(creationSmokeProofLine("Scene smoke", sceneSmokeEntries, "scene reply/ies"));
      } else {
        proofLines.push(`First live conversation test: ${currentSingleProbe ? "complete" : "not run yet"}`);
      }
      proofLines.push(missingGapCount
        ? `Missing gap rows: ${missingGapCount}`
        : watchGapCount
          ? `Watch rows still worth refining: ${watchGapCount}`
          : "Gap watch is currently calm");

      const spec = creationPublishDecisionSpec(decision);
      return {
        decision,
        spec,
        title: spec.label,
        helper: spec.helper,
        summaryLines,
        proofLines,
        worldName: blueprint.inputs?.worldName || currentCreationProjectName(),
        hostId: blueprint.game?.id || creationEngineHostValue(),
        programId: blueprint.program?.id || creationEngineProgramValue(),
        scaleId: blueprint.scale?.id || creationEngineScaleValue(),
        depthId: blueprint.depth?.id || creationEngineDepthValue(),
        lifecycleState: decision === "ready_to_keep" ? "kept" : (decision === "needs_dev_side" ? "handoff_ready" : "draft"),
      };
    }

    function currentCreationPublishPayload(decisionOverride = "") {
      const recommendation = currentCreationPublishRecommendation();
      const outcome = currentCreationOutcome();
      const decision = String(decisionOverride || recommendation?.decision || "keep_draft").trim().toLowerCase();
      const spec = creationPublishDecisionSpec(decision);
      const lifecycleState = decision === "ready_to_keep" ? "kept" : (decision === "needs_dev_side" ? "handoff_ready" : "draft");
      const handoffState = lifecycleState === "handoff_ready" ? "ready" : "none";
      const projectPayload = buildCreationProjectPayload();
      const projectBlueprint = projectPayload?.blueprint && typeof projectPayload.blueprint === "object" ? projectPayload.blueprint : null;
      const packPreview = latestCreationProgramPackPreview && typeof latestCreationProgramPackPreview === "object"
        ? latestCreationProgramPackPreview
        : null;
      const worldName = projectBlueprint?.worldName || creationEngineWorldNameValue() || currentCreationProjectName();
      const hostId = projectBlueprint?.host?.id || creationEngineHostValue();
      const programId = projectBlueprint?.program?.id || creationEngineProgramValue();
      const toneId = projectBlueprint?.tone?.id || creationEngineToneValue();
      const scaleId = projectBlueprint?.scale?.id || creationEngineScaleValue();
      const depthId = projectBlueprint?.depth?.id || creationEngineDepthValue();
      const lineage = currentCreationLineageState();
      return {
        worldName,
        hostId,
        programId,
        toneId,
        scaleId,
        depthId,
        lifecycleState,
        handoffState,
        packageKey: currentCreationPublishPackageKey(),
        familyKey: lineage.familyKey,
        parentPackageKey: lineage.parentPackageKey,
        parentPublishId: lineage.parentPublishId,
        derivationMode: lineage.derivationMode,
        lineage,
        summary: `${worldName || "Untitled world"} :: ${spec.label}`,
        recommendation: recommendation ? {
          decision: recommendation.decision,
          summaryLines: recommendation.summaryLines,
          proofLines: recommendation.proofLines,
        } : null,
        projectPayload,
        createdOutput: outcome ? {
          kind: outcome.kind,
          createdCount: outcome.createdCount,
          currentId: outcome.currentId,
          currentLabel: outcome.currentLabel,
          projectSaved: outcome.projectSaved,
          liveNow: outcome.liveNow,
        } : null,
        packProof: packPreview ? {
          created: Boolean(packPreview.created),
          roleCount: Array.isArray(packPreview.entries) ? packPreview.entries.length : 0,
          voiceSmoke: packPreview.voiceSmoke || null,
          sceneSmoke: packPreview.sceneSmoke || null,
        } : null,
        latestProbeResult: currentCreationLiveProofResult(),
      };
    }

    function findCreationRoleIndexByIds(roleSeeds, preferredRoleIds) {
      const roles = Array.isArray(roleSeeds) ? roleSeeds : [];
      const preferred = Array.isArray(preferredRoleIds) ? preferredRoleIds : [];
      for (const wanted of preferred) {
        const index = roles.findIndex(role => String(role?.id || "").trim().toLowerCase() === String(wanted || "").trim().toLowerCase());
        if (index >= 0) {
          return index;
        }
      }
      return roles.length ? 0 : -1;
    }

    async function applyCreationSuggestedAddition(index) {
      const blueprint = latestCreationEngineBlueprint || buildCreationEngineBlueprint();
      const suggestions = Array.isArray(blueprint?.suggestedAdditions) ? blueprint.suggestedAdditions : [];
      const suggestion = suggestions[index];
      if (!suggestion) {
        setCreationStatus("That suggested addition is no longer available.");
        return;
      }
      if (String(suggestion.actionKind || "").trim().toLowerCase() === "open_lane") {
        await openStudioGuideTarget(suggestion.laneId || "");
        setCreationStatus("Opened the suggested refinement lane.");
        return;
      }
      const nextScaleId = String(suggestion.targetScaleId || creationEngineScaleValue()).trim() || creationEngineScaleValue();
      setFieldValue("creation-engine-scale", nextScaleId);
      activeCreationEngineRoleIndex = 0;
      previewCreationEngineBlueprint(false);
      const refreshed = latestCreationEngineBlueprint || buildCreationEngineBlueprint();
      const roleIndex = findCreationRoleIndexByIds(refreshed.roleSeeds, suggestion.preferredRoleIds);
      if (roleIndex >= 0) {
        activeCreationEngineRoleIndex = roleIndex;
      }
      previewCreationEngineBlueprint(false);
      await applyCreationEngineBlueprint(false);
      if (creationEngineScaleValue() !== "single_pilot") {
        await previewCreationProgramPack();
      } else {
        await previewCreationBundle();
      }
      scrollToElementId("creation-engine-preview");
      setCreationStatus(`Studio expanded the world toward ${suggestion.title.toLowerCase()}.`);
    }

    async function expandMyWorld() {
      const blueprint = latestCreationEngineBlueprint || buildCreationEngineBlueprint();
      const suggestions = Array.isArray(blueprint?.suggestedAdditions) ? blueprint.suggestedAdditions : [];
      if (!suggestions.length) {
        setCreationStatus("Studio does not have a next expansion suggestion yet.");
        return;
      }
      const expandableIndex = suggestions.findIndex(item => String(item?.actionKind || "").trim().toLowerCase() === "expand_role");
      await applyCreationSuggestedAddition(expandableIndex >= 0 ? expandableIndex : 0);
    }

    async function openCreatedBundleInProbe() {
      const currentId = currentCreationOutcome()?.currentId || latestCreatedBundle?.fpc?.id || "";
      if (!currentId) {
        setCreationStatus("Create a bundle or starter pack first.");
        return;
      }
      await loadDetail(currentId.toLowerCase());
      setLabTab("probe");
      setCreationStatus("Opened the created draft in Probe.");
    }

    function creationSmokePrompt() {
      const programId = String(latestCreationEngineBlueprint?.program?.id || creationEngineProgramValue()).trim().toLowerCase();
      switch (programId) {
        case "guides_mentors":
          return "what should i do first?";
        case "ambient_locals":
          return "what is this place like?";
        case "rivals_faction":
          return "what do you really want here?";
        case "companion_adventurer":
        case "companion_party":
          return "what should we do first?";
        default:
          return "hello";
      }
    }

    function captureCreationSmokeUiState() {
      return {
        activeId: String(activeId || "").trim().toLowerCase(),
        activeDefinition: activeDefinition && typeof activeDefinition === "object" ? { ...activeDefinition } : null,
        selectedMeta: document.getElementById("selected-meta")?.textContent || "",
        detailHtml: document.getElementById("detail")?.innerHTML || "",
      };
    }

    function restoreCreationSmokeUiState(snapshot) {
      if (!snapshot || typeof snapshot !== "object") {
        return;
      }
      activeId = String(snapshot.activeId || "").trim().toLowerCase();
      activeDefinition = snapshot.activeDefinition && typeof snapshot.activeDefinition === "object"
        ? snapshot.activeDefinition
        : activeDefinition;
      const selectedMeta = document.getElementById("selected-meta");
      if (selectedMeta) {
        selectedMeta.textContent = snapshot.selectedMeta || "No active selection";
      }
      const detail = document.getElementById("detail");
      if (detail) {
        detail.innerHTML = snapshot.detailHtml || `<div class="muted">No active selection.</div>`;
      }
    }

    async function loadCreationSmokeSpeaker(fpcId = "") {
      const normalizedId = String(fpcId || "").trim().toLowerCase();
      if (!normalizedId) {
        throw new Error("Missing created speaker id.");
      }
      activeId = normalizedId;
      const sourceData = await fetchJsonMaybe("/studio/content/fpcs/" + encodeURIComponent(normalizedId));
      if (sourceData?.entry) {
        activeDefinition = sourceData.entry;
        renderSelectionMeta(sourceData.entry, null);
        applyPreset(sourceData.entry);
        const detail = document.getElementById("detail");
        if (detail) {
          detail.innerHTML = `<div class="muted">Studio is using the saved source definition for ${esc(normalizedId)} while keeping the current Create workspace intact for proof.</div>`;
        }
        return;
      }
      const detailData = await fetchJsonMaybe("/studio/fpc/" + encodeURIComponent(normalizedId));
      if (!detailData?.definition) {
        throw new Error(`/studio/content/fpcs/${normalizedId} -> 404`);
      }
      activeDefinition = detailData.definition || activeDefinition;
      renderSelectionMeta(detailData.definition || null, detailData.runtime || null);
      applyPreset(detailData.definition || activeDefinition);
      const detail = document.getElementById("detail");
      if (detail) {
        detail.innerHTML = `<div class="muted">Studio is using live runtime detail for ${esc(normalizedId)} while keeping the current Create workspace intact for proof.</div>`;
      }
    }

    async function runCreationSmokeProbe() {
      const currentId = currentCreationOutcome()?.currentId || latestCreatedBundle?.fpc?.id || "";
      if (!currentId) {
        setCreationStatus("Create a bundle or starter pack first.");
        return;
      }
      await loadCreationSmokeSpeaker(currentId.toLowerCase());
      setLabTab("probe");
      const player = document.getElementById("probe-player");
      const channel = document.getElementById("probe-channel");
      const text = document.getElementById("probe-text");
      if (player) {
        player.value = "PlayerOne";
      }
      if (channel) {
        channel.value = "whisper";
      }
      if (text) {
        text.value = creationSmokePrompt();
      }
      await runProbeRequest("PlayerOne", "whisper", creationSmokePrompt());
      setCreationStatus("Ran the first conversation test for the created draft.");
    }

    function rerenderCreationProofAwareSurfaces() {
      renderCreationJourney();
      renderCreationEnginePreview();
      renderCreationPreview();
    }

    async function runWargFirstTutorialProofStep() {
      const currentId = currentCreationOutcome()?.currentId || latestCreatedBundle?.fpc?.id || "";
      if (!currentId) {
        setCreationStatus("Create the first live draft before running the tutorial proof step.");
        return null;
      }
      try {
        await loadCreationSmokeSpeaker(currentId.toLowerCase());
        const player = document.getElementById("probe-player");
        const channel = document.getElementById("probe-channel");
        const text = document.getElementById("probe-text");
        if (player) {
          player.value = "PlayerOne";
        }
        if (channel) {
          channel.value = "whisper";
        }
        if (text) {
          text.value = creationSmokePrompt();
        }
        setLabTab("create");
        const result = await runProbeRequest("PlayerOne", "whisper", creationSmokePrompt(), {
          updateOutput: true,
          updateStatus: false,
          refreshTrace: true,
        });
        rerenderCreationProofAwareSurfaces();
        setCreationStatus("Ran the first conversation test for the tutorial guide.");
        return result;
      } catch (error) {
        rerenderCreationProofAwareSurfaces();
        setCreationStatus("First conversation test failed: " + error.message);
        return null;
      }
    }

    function creationRoleVoicePrompt(role, blueprint) {
      const roleId = String(role?.id || "").trim().toLowerCase();
      const programId = String(blueprint?.program?.id || creationEngineProgramValue()).trim().toLowerCase();
      const worldLabel = String(blueprint?.inputs?.worldName || "this place").trim();
      if (programId === "companion_adventurer" || programId === "companion_party") {
        if (roleId === "support") {
          return "where are we weakest right now?";
        }
        if (roleId === "scout") {
          return "what should we watch first?";
        }
        if (roleId === "vanguard") {
          return "what stands in our way?";
        }
        return "what should we do first?";
      }
      if (roleId === "guide") {
        return "what should i do first?";
      }
      if (roleId === "local" || roleId === "gentle_foil") {
        return `what is ${worldLabel || "this place"} like?`;
      }
      if (roleId === "rival" || roleId === "countervoice") {
        return "what do you really want here?";
      }
      return programId === "ambient_locals" ? `what is ${worldLabel || "this place"} like?` : "hello";
    }

    function creationPackVoiceCards(pack) {
      const entries = Array.isArray(pack?.entries) ? pack.entries : [];
      return entries.map(item => {
        const preview = item?.preview || {};
        const banks = Array.isArray(preview.replyBanks) ? preview.replyBanks : [];
        const greeting = banks.find(entry => String(entry.category || "").trim().toLowerCase() === "greeting")?.line || "";
        const help = banks.find(entry => String(entry.category || "").trim().toLowerCase() === "help")?.line || "";
        const status = banks.find(entry => String(entry.category || "").trim().toLowerCase() === "status")?.line || "";
        return {
          role: item?.role || {},
          preview,
          greeting,
          help,
          status,
          prompt: creationRoleVoicePrompt(item?.role || {}, pack?.blueprint || {}),
        };
      });
    }

    function renderCreationPackVoiceLine(label, value) {
      const text = String(value || "").trim();
      if (!text) {
        return "";
      }
      return `<div class="creation-voice-line"><strong>${esc(label)}:</strong> ${esc(text)}</div>`;
    }

    function buildCreationVoiceSmokeReview(pack) {
      const entries = Array.isArray(pack?.voiceSmoke?.entries) ? pack.voiceSmoke.entries : [];
      if (!entries.length) {
        return null;
      }
      const normalizedCounts = new Map();
      for (const entry of entries) {
        const key = String(entry?.replyLine || "").trim().toLowerCase().replace(/\s+/g, " ");
        if (!key) {
          continue;
        }
        normalizedCounts.set(key, (normalizedCounts.get(key) || 0) + 1);
      }
      const rows = entries.map(entry => {
        const reply = String(entry?.replyLine || "").trim();
        const category = String(entry?.category || "").trim().toLowerCase();
        const normalized = reply.toLowerCase().replace(/\s+/g, " ");
        let state = "healthy";
        let note = "Distinct first voice is visible.";
        if (!reply) {
          state = "missing";
          note = "No reply was captured for this role yet.";
        } else if ((normalizedCounts.get(normalized) || 0) > 1) {
          state = "duplicate";
          note = "This role is currently echoing the same answer as another role.";
        } else if (category === "smalltalk" || category === "none") {
          state = "shallow";
          note = "The live route still looks shallow for this prompt.";
        }
        return {
          roleLabel: entry?.roleLabel || entry?.fpcId || "Role",
          state,
          note,
        };
      });
      const duplicateCount = rows.filter(row => row.state === "duplicate").length;
      const shallowCount = rows.filter(row => row.state === "shallow").length;
      const missingCount = rows.filter(row => row.state === "missing").length;
      return {
        rows,
        summary: [
          duplicateCount ? `${duplicateCount} role(s) are still echoing another role.` : "No duplicate live answers were detected.",
          shallowCount ? `${shallowCount} role(s) still look shallow or under-routed.` : "The first live routes look varied enough for a first pass.",
          missingCount ? `${missingCount} role(s) still need a captured reply.` : "Every created role returned a first live answer.",
        ],
      };
    }

    function creationSmokeAnsweredEntryCount(entries = []) {
      const list = Array.isArray(entries) ? entries : [];
      return list.filter(entry => String(entry?.replyLine || "").trim()).length;
    }

    function creationSmokeFailedEntryCount(entries = []) {
      const list = Array.isArray(entries) ? entries : [];
      return list.filter(entry => String(entry?.probeStatus || "").trim().toLowerCase() && String(entry?.probeStatus || "").trim().toLowerCase() !== "ok").length;
    }

    function creationSmokeFirstFailureMessage(entries = []) {
      const list = Array.isArray(entries) ? entries : [];
      const failure = list.find(entry => String(entry?.probeStatus || "").trim().toLowerCase() && String(entry?.probeStatus || "").trim().toLowerCase() !== "ok");
      return String(failure?.probeMessage || failure?.probeError || "").trim();
    }

    function creationSmokeProofStatus(entries = []) {
      const list = Array.isArray(entries) ? entries : [];
      const totalCount = list.length;
      const answeredCount = creationSmokeAnsweredEntryCount(list);
      const failedCount = creationSmokeFailedEntryCount(list);
      if (!totalCount) {
        return {
          state: "not_run",
          label: "not run yet",
          totalCount,
          answeredCount,
          failedCount,
        };
      }
      if (!answeredCount) {
        return {
          state: "empty",
          label: "captured but empty",
          totalCount,
          answeredCount,
          failedCount,
        };
      }
      if (answeredCount < totalCount) {
        return {
          state: "partial",
          label: `partial (${answeredCount}/${totalCount})`,
          totalCount,
          answeredCount,
          failedCount,
        };
      }
      return {
        state: "complete",
        label: "complete",
        totalCount,
        answeredCount,
        failedCount,
      };
    }

    function creationSmokeProofLine(label, entries = [], unitLabel = "answer(s)") {
      const status = creationSmokeProofStatus(entries);
      const issueSuffix = status.failedCount ? `; ${status.failedCount} probe issue(s)` : "";
      if (status.state === "not_run") {
        return `${label}: not run yet`;
      }
      if (status.state === "empty") {
        return `${label}: captured but empty (0/${status.totalCount} ${unitLabel}${issueSuffix})`;
      }
      if (status.state === "partial") {
        return `${label}: partial (${status.answeredCount}/${status.totalCount} ${unitLabel}${issueSuffix})`;
      }
      return `${label}: complete (${status.answeredCount} ${unitLabel}${issueSuffix})`;
    }

    function creationJourneySmokeStatusLabel(info = null) {
      switch (String(info?.state || "").trim().toLowerCase()) {
        case "complete":
          return "done";
        case "partial":
          return `${info.answeredCount}/${info.totalCount}`;
        case "empty":
          return "empty";
        default:
          return "pending";
      }
    }

    function creationCoverageProofLabel(item, voiceSmokeEntries, sceneSmokeEntries) {
      const sceneTitle = String(item?.sceneTitle || "").trim().toLowerCase();
      const ownerLabel = String(item?.ownerLabel || "").trim().toLowerCase();
      const sceneEntries = (Array.isArray(sceneSmokeEntries) ? sceneSmokeEntries : []).filter(entry => String(entry?.sceneTitle || "").trim().toLowerCase() === sceneTitle);
      const voiceEntries = (Array.isArray(voiceSmokeEntries) ? voiceSmokeEntries : []).filter(entry => String(entry?.roleLabel || "").trim().toLowerCase() === ownerLabel);
      if (sceneTitle && sceneEntries.length) {
        const answeredCount = creationSmokeAnsweredEntryCount(sceneEntries);
        const failedCount = creationSmokeFailedEntryCount(sceneEntries);
        if (answeredCount) {
          return failedCount
            ? `Live scene smoke captured replies for this lane, but ${failedCount} probe turn(s) still failed.`
            : "Live scene smoke captured replies for this lane.";
        }
        if (failedCount) {
          const failureCue = creationSmokeFirstFailureMessage(sceneEntries);
          return failureCue
            ? `Live scene smoke hit probe issues here before it captured a reply: ${failureCue}`
            : "Live scene smoke hit probe issues here before it captured a reply.";
        }
        return "Live scene smoke ran here, but this lane still needs captured reply lines.";
      }
      if (ownerLabel && voiceEntries.length) {
        const answeredCount = creationSmokeAnsweredEntryCount(voiceEntries);
        const failedCount = creationSmokeFailedEntryCount(voiceEntries);
        if (answeredCount) {
          return failedCount
            ? `This lane has first voice smoke from the owning role, but ${failedCount} probe turn(s) still failed.`
            : "This lane has at least first voice smoke from the owning role.";
        }
        if (failedCount) {
          const failureCue = creationSmokeFirstFailureMessage(voiceEntries);
          return failureCue
            ? `Cast voice smoke hit probe issues for the owning role before it captured a live line: ${failureCue}`
            : "Cast voice smoke hit probe issues for the owning role before it captured a live line.";
        }
        return "Cast voice smoke ran for the owning role, but it still needs a captured live line.";
      }
      if (sceneTitle) {
        return "Starter scene planned, but still waiting for live scene proof.";
      }
      if (item?.weaveTitle) {
        return "Seeded through the relationship weave, but not live-proved yet.";
      }
      if (item?.ownerRoleId) {
        return "Owned in the blueprint, but still waiting for live proof.";
      }
      return "Still missing a clear owner and live proof.";
    }

    async function runCreationPackVoiceSmoke() {
      const pack = latestCreationProgramPackPreview;
      if (!pack?.created || !Array.isArray(pack.entries) || !pack.entries.length) {
        setCreationStatus("Create the starter pack first.");
        return;
      }
      if (!latestCreationEngineBlueprint?.game?.safeRuntime) {
        setCreationStatus("Cast voice smoke needs a live runtime host. This host is still source-first.");
        return;
      }
      const originalUiState = captureCreationSmokeUiState();
      const results = [];
      try {
        setCreationStatus("Running cast voice smoke...");
        for (const item of pack.entries) {
          const fpcId = String(item?.preview?.fpc?.id || "").trim().toLowerCase();
          if (!fpcId) {
            continue;
          }
          await loadCreationSmokeSpeaker(fpcId);
          const prompt = creationRoleVoicePrompt(item?.role || {}, pack.blueprint || {});
          let probe = null;
          let probeError = "";
          try {
            probe = await runProbeRequest("PlayerOne", "whisper", prompt, {
              updateOutput: false,
              updateStatus: true,
              refreshTrace: false,
            });
          } catch (error) {
            probe = error?.studioResult || latestProbeResult || null;
            probeError = String(error?.message || "").trim();
          }
          results.push({
            fpcId,
            roleLabel: item?.role?.label || "",
            prompt,
            replyLine: probe?.reply?.line || "",
            source: probe?.reply?.source || "",
            category: probe?.classification?.messageCategory || "",
            probeStatus: probe?._studioStatus || (probeError ? "error" : "unknown"),
            probeMessage: String(probe?._studioMessage || probeError || "").trim(),
            probeCommandId: probe?._studioCommandId || "",
            probeError,
          });
        }
        pack.voiceSmoke = {
          ranAtMs: Date.now(),
          entries: results,
        };
        latestCreationProgramPackPreview = {
          ...pack,
          voiceSmoke: pack.voiceSmoke,
        };
        restoreCreationSmokeUiState(originalUiState);
        renderCreationEnginePreview();
        const answeredCount = creationSmokeAnsweredEntryCount(results);
        const failedCount = creationSmokeFailedEntryCount(results);
        const syncedProject = await syncActiveCreationProjectProofState("cast voice smoke");
        setCreationStatus(`Ran the first cast voice smoke for the created pack (${answeredCount}/${results.length} role answer(s)${failedCount ? `, ${failedCount} probe issue(s)` : ""}).` + (syncedProject ? " Saved the updated proof into the current project." : ""));
      } catch (error) {
        restoreCreationSmokeUiState(originalUiState);
        setCreationStatus("Cast voice smoke failed: " + error.message);
      }
    }

    async function runCreationSceneSmoke() {
      const pack = latestCreationProgramPackPreview;
      const starterScenes = Array.isArray(latestCreationEngineBlueprint?.starterScenes) ? latestCreationEngineBlueprint.starterScenes : [];
      const continuityScenes = Array.isArray(latestCreationEngineBlueprint?.wargBehavior?.continuityScenes)
        ? latestCreationEngineBlueprint.wargBehavior.continuityScenes
        : [];
      const scenes = [...starterScenes, ...continuityScenes];
      if (!pack?.created || !Array.isArray(pack.entries) || !pack.entries.length) {
        setCreationStatus("Create the starter pack first.");
        return;
      }
      if (!scenes.length) {
        setCreationStatus("Generate a world package first.");
        return;
      }
      if (!latestCreationEngineBlueprint?.game?.safeRuntime) {
        setCreationStatus("Scene smoke needs a live runtime host. This host is still source-first.");
        return;
      }
      const originalUiState = captureCreationSmokeUiState();
      const results = [];
      try {
        setCreationStatus(continuityScenes.length ? "Running starter and return scene smoke..." : "Running starter scene smoke...");
        for (const scene of scenes) {
          const ownerRoleId = String(scene?.ownerRoleId || "").trim().toLowerCase();
          const owner = pack.entries.find(item => String(item?.role?.id || "").trim().toLowerCase() === ownerRoleId) || pack.entries[0];
          const fpcId = String(owner?.preview?.fpc?.id || "").trim().toLowerCase();
          if (!fpcId) {
            continue;
          }
          await loadCreationSmokeSpeaker(fpcId);
          for (const probeSpec of creationSceneProbePrompts(scene)) {
            const prompt = String(probeSpec?.prompt || "").trim();
            if (!prompt) {
              continue;
            }
            let probe = null;
            let probeError = "";
            try {
              probe = await runProbeRequest("PlayerOne", "whisper", prompt, {
                updateOutput: false,
                updateStatus: true,
                refreshTrace: false,
              });
            } catch (error) {
              probe = error?.studioResult || latestProbeResult || null;
              probeError = String(error?.message || "").trim();
            }
            results.push({
              sceneTitle: scene?.title || "",
              ownerLabel: scene?.ownerLabel || owner?.role?.label || "",
              probeLabel: String(probeSpec?.label || "Starter prompt").trim() || "Starter prompt",
              fpcId,
              prompt,
              playerMoment: scene?.playerMoment || "",
              followthrough: scene?.followthrough || "",
              proofKind: scene?.proofKind || "starter",
              continuityKey: scene?.continuityKey || "",
              replyLine: probe?.reply?.line || "",
              source: probe?.reply?.source || "",
              category: probe?.classification?.messageCategory || "",
              probeStatus: probe?._studioStatus || (probeError ? "error" : "unknown"),
              probeMessage: String(probe?._studioMessage || probeError || "").trim(),
              probeCommandId: probe?._studioCommandId || "",
              probeError,
            });
          }
        }
        pack.sceneSmoke = {
          ranAtMs: Date.now(),
          sceneCount: scenes.length,
          probeCount: results.length,
          entries: results,
        };
        latestCreationProgramPackPreview = {
          ...pack,
          sceneSmoke: pack.sceneSmoke,
        };
        restoreCreationSmokeUiState(originalUiState);
        renderCreationEnginePreview();
        const answeredCount = creationSmokeAnsweredEntryCount(results);
        const failedCount = creationSmokeFailedEntryCount(results);
        const syncedProject = await syncActiveCreationProjectProofState("scene smoke");
        setCreationStatus((continuityScenes.length
          ? `Ran the starter and return scene smoke for the created pack (${answeredCount}/${results.length} captured${failedCount ? `, ${failedCount} probe issue(s)` : ""}).`
          : `Ran the starter scene smoke for the created pack (${answeredCount}/${results.length} captured${failedCount ? `, ${failedCount} probe issue(s)` : ""}).`) + (syncedProject ? " Saved the updated proof into the current project." : ""));
      } catch (error) {
        restoreCreationSmokeUiState(originalUiState);
        setCreationStatus((continuityScenes.length ? "Starter and return scene smoke failed: " : "Starter scene smoke failed: ") + error.message);
      }
    }
