    function creationProjectVisibleFamiliesFilterSummary(filters = creationProjectUiState, familyLabels = creationProjectFamilyLabels()) {
      const summaryParts = [];
      if (String(filters?.searchText || "").trim()) {
        summaryParts.push(`Search "${String(filters.searchText || "").trim()}".`);
      }
      if (normalizeCreationProjectFacetFilterId(filters?.hostId) !== "all") {
        summaryParts.push(`Host: ${creationProjectFacetFilterLabel(filters.hostId)}.`);
      }
      if (normalizeCreationProjectFacetFilterId(filters?.programId) !== "all") {
        summaryParts.push(`Program: ${creationProjectFacetFilterLabel(filters.programId)}.`);
      }
      if (normalizeCreationProjectFacetFilterId(filters?.familyKey) !== "all") {
        summaryParts.push(`Family: ${familyLabels?.[filters.familyKey] || creationProjectFacetFilterLabel(filters.familyKey)}.`);
      }
      if (normalizeCreationProjectRoleTuningFilterId(filters?.roleTuning) !== "all") {
        summaryParts.push(`Role tuning: ${creationRoleTuningFilterLabel(filters.roleTuning)}.`);
      }
      if (normalizeCreationProofFilterId(filters?.proofState) !== "all") {
        summaryParts.push(`Proof: ${creationProofFilterLabel(filters.proofState)}.`);
      }
      if (normalizeCreationWorkflowFilterId(filters?.workflowState) !== "all") {
        summaryParts.push(`Workflow: ${creationWorkflowFilterLabel(filters.workflowState)}.`);
      }
      if (normalizeCreationProjectPublishStateFilterId(filters?.publishState) !== "all") {
        summaryParts.push(`Publish state: ${creationProjectPublishStateFilterLabel(filters.publishState)}.`);
      }
      if (normalizeCreationProjectPublishLifecycleFilterId(filters?.publishLifecycle) !== "all") {
        summaryParts.push(`Publish lane: ${creationProjectPublishLifecycleFilterLabel(filters.publishLifecycle)}.`);
      }
      if (normalizeCreationProjectFacetFilterId(filters?.lineageMode) !== "all") {
        summaryParts.push(`Lineage: ${creationProjectLineageFilterLabel(filters.lineageMode)}.`);
      }
      return summaryParts.join(" ") || "All visible saved-project families on the current shelf.";
    }

    function creationProjectVisibleFamilyLaneSummary(laneCounts = {}) {
      return [
        `Needs Proof ${Number(laneCounts?.needs_proof || 0)}`,
        `Ready For Queue ${Number(laneCounts?.ready_queue || 0)}`,
        `Review Queue ${Number(laneCounts?.review_queue || 0)}`,
        `Ready To Keep ${Number(laneCounts?.ready_keep || 0)}`,
        `Continue Refining ${Number(laneCounts?.refine_local || 0)}`,
      ].join(" | ");
    }

    function buildCreationProjectVisibleFamiliesPortfolioPayload(contexts = visibleCreationProjectFamilyContexts(), filters = creationProjectUiState, familyLabels = creationProjectFamilyLabels()) {
      const visibleContexts = Array.isArray(contexts) ? contexts.filter(Boolean) : [];
      const visibleEntries = visibleContexts.flatMap(context => context.visibleFamilyEntries || []);
      const laneCounts = creationProjectFamilyBoardLaneCounts(visibleContexts);
      const proofCounts = creationProofCountsFromEntries(visibleEntries, entry => creationProjectProofSummary(entry));
      const workflowCounts = creationWorkflowRecommendationCountsFromEntries(visibleEntries, entry => creationProjectWorkflowRecommendation(entry));
      return {
        generatedAtIso: new Date().toISOString(),
        filterSummary: creationProjectVisibleFamiliesFilterSummary(filters, familyLabels),
        familyCount: visibleContexts.length,
        visibleProjectCount: visibleEntries.length,
        totalFamilyProjectCount: visibleContexts.reduce((sum, context) => sum + Number(context?.familyEntries?.length || 0), 0),
        hiddenProjectCount: visibleContexts.reduce((sum, context) => sum + Math.max(Number(context?.familyEntries?.length || 0) - Number(context?.visibleFamilyEntries?.length || 0), 0), 0),
        laneCounts,
        proofCounts,
        workflowCounts,
        families: visibleContexts.map(context => {
          const laneId = creationProjectFamilyBoardLaneId(context);
          const laneSpec = creationProjectFamilyBoardLaneSpec(laneId);
          return {
            familyKey: String(context.familyKey || "").trim(),
            familyLabel: String(context.label || "").trim(),
            lane: {
              id: laneSpec.id,
              label: laneSpec.label,
              helper: laneSpec.helper,
            },
            visibleCount: Number(context?.visibleFamilyEntries?.length || 0),
            totalCount: Number(context?.familyEntries?.length || 0),
            hiddenCount: Math.max(Number(context?.familyEntries?.length || 0) - Number(context?.visibleFamilyEntries?.length || 0), 0),
            rootWorldName: String(context?.rootEntry?.worldName || context?.rootEntry?.name || "").trim(),
            packet: buildCreationJourneyFamilyPacket(context),
            visibleProjects: (Array.isArray(context.visibleFamilyEntries) ? context.visibleFamilyEntries : []).map(entry => {
              const proof = creationProjectProofSummary(entry);
              const workflow = creationProjectWorkflowRecommendation(entry);
              return {
                id: String(entry?.id || "").trim(),
                name: String(entry?.name || entry?.worldName || "").trim(),
                worldName: String(entry?.worldName || entry?.name || "").trim(),
                proof: {
                  state: proof.state,
                  label: proof.label,
                  summary: proof.summary,
                },
                workflow: {
                  id: workflow.id,
                  label: workflow?.spec?.label || creationWorkflowRecommendationSpec(workflow.id).label,
                  summary: workflow.summary,
                },
                publishState: creationProjectPublishStateMeta(entry),
                publishLifecycle: creationProjectPublishLifecycleMeta(entry),
                lineage: creationProjectLineageMeta(entry, familyLabels),
              };
            }),
          };
        }),
      };
    }

    function creationProjectVisibleFamiliesArtifactSafeName(payload = null, mode = "report") {
      const normalizedMode = String(mode || "report").trim().toLowerCase() === "handoff" ? "handoff" : "report";
      const familyCount = Number(payload?.familyCount || 0);
      return `saved_project_visible_families_${familyCount || 0}_${normalizedMode}`
        .replace(/[^a-z0-9_-]+/gi, "_")
        .replace(/^_+|_+$/g, "")
        .toLowerCase();
    }

    function buildCreationProjectVisibleFamiliesArtifactMarkdown(mode = "report", contexts = visibleCreationProjectFamilyContexts(), filters = creationProjectUiState, familyLabels = creationProjectFamilyLabels()) {
      const normalizedMode = String(mode || "report").trim().toLowerCase() === "handoff" ? "handoff" : "report";
      const payload = buildCreationProjectVisibleFamiliesPortfolioPayload(contexts, filters, familyLabels);
      const lines = [
        normalizedMode === "handoff" ? "# Saved Project Visible Family Handoff" : "# Saved Project Visible Family Report",
        "",
        `Generated: ${payload.generatedAtIso}`,
        `Filters: ${payload.filterSummary}`,
        `Visible families: ${payload.familyCount}`,
        `Visible saved projects: ${payload.visibleProjectCount} of ${payload.totalFamilyProjectCount}`,
        `Hidden by current filters: ${payload.hiddenProjectCount}`,
        `Lane board: ${creationProjectVisibleFamilyLaneSummary(payload.laneCounts)}`,
        `Proof snapshot: ${creationLibraryProofSummaryGuide(payload.proofCounts)}`,
        creationWorkflowCountsSummary(payload.workflowCounts) ? `Workflow snapshot: ${creationWorkflowCountsSummary(payload.workflowCounts, { includePublishRecord: true, includeRefineLocal: true, includeArchived: true })}` : "Workflow snapshot: no next-move counts yet.",
      ];
      payload.families.forEach(family => {
        lines.push(
          "",
          `## ${family.familyLabel || family.rootWorldName || family.familyKey || "Saved Project Family"}`,
          `- Family key: ${family.familyKey}`,
          `- Lane: ${family.lane.label}`,
          `- Root world: ${family.rootWorldName || "unknown"}`,
          `- Visible saved projects: ${family.visibleCount} of ${family.totalCount}`,
          `- Hidden projects: ${family.hiddenCount}`,
          ...creationFamilyOperationsPacketLineItems(family.packet, {
            guideLabel: "Workflow guide",
            appendLines: family.packet?.workflowGuide ? [] : [family.lane.helper ? `Workflow guide: ${family.lane.helper}` : ""],
          }).map(line => `- ${line}`),
          "",
          "### Workflow Counts",
          creationWorkflowCountRows(family.packet?.workflowCounts || {}, {
            includePublishRecord: true,
            includeRefineLocal: true,
            includeArchived: true,
          }).filter(row => Number(row?.count || 0) > 0).map(row => `- ${row.label}: ${row.count}`).join("\n") || "- none",
          "",
          normalizedMode === "handoff" ? "### Visible Saved Projects For Handoff" : "### Visible Saved Projects",
          family.visibleProjects.map(project => `- ${project.worldName || project.name || project.id} (${project.lineage} | ${project.publishLifecycle} | ${project.proof.label} | ${project.workflow.label})`).join("\n") || "- none",
        );
      });
      return lines.join("\n");
    }

    async function copyCreationProjectVisibleFamiliesArtifact(mode = "report") {
      const markdown = buildCreationProjectVisibleFamiliesArtifactMarkdown(mode);
      const payload = buildCreationProjectVisibleFamiliesPortfolioPayload();
      if (payload.familyCount < 1) {
        setCreationStatus("No visible saved-project families are on this shelf.");
        return;
      }
      await copyTextToClipboard(markdown);
      setCreationStatus(`${String(mode || "report").trim().toLowerCase() === "handoff" ? "Copied the visible family handoff." : "Copied the visible family report."} ${payload.familyCount} visible saved-project famil${payload.familyCount === 1 ? "y" : "ies"} are currently on the shelf.`);
    }

    function exportCreationProjectVisibleFamiliesArtifact(format = "md", mode = "report") {
      const normalizedFormat = String(format || "md").trim().toLowerCase() === "json" ? "json" : "md";
      const normalizedMode = String(mode || "report").trim().toLowerCase() === "handoff" ? "handoff" : "report";
      const payload = buildCreationProjectVisibleFamiliesPortfolioPayload();
      if (payload.familyCount < 1) {
        setCreationStatus("No visible saved-project families are on this shelf.");
        return;
      }
      const safeName = creationProjectVisibleFamiliesArtifactSafeName(payload, normalizedMode);
      if (normalizedFormat === "json") {
        downloadTextFile(`${safeName}.json`, JSON.stringify(payload, null, 2), "application/json;charset=utf-8");
      } else {
        downloadTextFile(`${safeName}.md`, buildCreationProjectVisibleFamiliesArtifactMarkdown(normalizedMode), "text/markdown;charset=utf-8");
      }
      setCreationStatus(`Exported the visible saved-project family ${normalizedMode} as ${normalizedFormat.toUpperCase()}.`);
    }

    function creationProjectFamilyFocusAfterAction(familyKey = "", actionId = "", updatedCount = 0) {
      const normalizedFamilyKey = normalizeCreationProjectFacetFilterId(familyKey);
      if (normalizedFamilyKey === "all" || Number(updatedCount || 0) < 1) {
        return;
      }
      creationProjectShelfAdvanceAfterLaneAction(actionId, updatedCount);
      const normalizedAction = String(actionId || "").trim().toLowerCase();
      let nextLifecycle = creationProjectUiState.publishLifecycle;
      if (normalizedAction === "publish_draft" || normalizedAction === "keep_local") {
        nextLifecycle = "draft";
      } else if (normalizedAction === "publish_ready" || normalizedAction === "mark_ready") {
        nextLifecycle = "handoff_ready";
      } else if (normalizedAction === "publish_sent" || normalizedAction === "send" || normalizedAction === "return_to_sent") {
        nextLifecycle = "sent";
      } else if (normalizedAction === "claim") {
        nextLifecycle = "claimed";
      } else if (normalizedAction === "promote_kept") {
        nextLifecycle = "kept_local";
      } else if (normalizedAction === "archive") {
        nextLifecycle = "archived";
      }
      creationProjectUiState = {
        ...creationProjectUiState,
        publishState: "all",
        publishLifecycle: nextLifecycle,
        familyKey: normalizedFamilyKey,
        lineageMode: "all",
      };
      saveCreationProjectUiState();
    }

    function creationProjectFamilyFocusAfterBranch(familyKey = "", createdCount = 0) {
      const normalizedFamilyKey = normalizeCreationProjectFacetFilterId(familyKey);
      if (normalizedFamilyKey === "all" || Number(createdCount || 0) < 1) {
        return;
      }
      creationProjectUiState = {
        ...creationProjectUiState,
        publishState: "published",
        publishLifecycle: "draft",
        familyKey: normalizedFamilyKey,
        lineageMode: "all",
      };
      saveCreationProjectUiState();
    }

    function latestCreationProjectEntryById(projectId = "", entries = latestCreationProjects) {
      const normalizedProjectId = String(projectId || "").trim();
      if (!normalizedProjectId) {
        return null;
      }
      return (Array.isArray(entries) ? entries : []).find(entry => String(entry?.id || "").trim() === normalizedProjectId) || null;
    }

    function creationProjectWorkflowEntryLabel(entry = {}) {
      return String(entry?.worldName || entry?.name || entry?.id || "Saved Project").trim() || "Saved Project";
    }

    function creationProjectFamilyWorkflowModeSpec(mode = "publish") {
      const normalized = String(mode || "publish").trim().toLowerCase();
      if (normalized === "queue") {
        return {
          id: "queue",
          label: "Family Workflow -> Queue",
          buttonLabel: "Create + Prove + Queue Family",
          pending: "Running the family workflow and dev-side queue pass for",
          success: "Ran the family workflow and dev-side queue pass for",
        };
      }
      if (normalized === "keep") {
        return {
          id: "keep",
          label: "Family Workflow -> Keep",
          buttonLabel: "Create + Prove + Keep Family",
          pending: "Running the family workflow and kept-baseline pass for",
          success: "Ran the family workflow and kept-baseline pass for",
        };
      }
      return {
        id: "publish",
        label: "Family Workflow Room",
        buttonLabel: "Create + Prove + Publish Family",
        pending: "Running the family workflow pass for",
        success: "Ran the family workflow pass for",
      };
    }

    function creationProjectFamilyWorkflowTargetEntries(context, mode = "publish") {
      const normalizedMode = String(mode || "publish").trim().toLowerCase();
      const familyEntries = sortCreationProjects(Array.isArray(context?.familyEntries) ? context.familyEntries : [], "lineage");
      return familyEntries.filter(entry => {
        const workflowId = normalizeCreationWorkflowRecommendationId(creationProjectWorkflowRecommendation(entry).id);
        const publishState = normalizeCreationProjectPublishStateFilterId(entry?.publishState?.state);
        if (workflowId === "archived" || workflowId === "review_dev_queue" || workflowId === "resume_journey" || workflowId === "refine_local") {
          return false;
        }
        if (normalizedMode === "queue") {
          return workflowId === "create_output"
            || workflowId === "finish_proof"
            || workflowId === "publish_record"
            || workflowId === "queue_dev_review"
            || workflowId === "keep_baseline";
        }
        if (normalizedMode === "keep") {
          return workflowId === "create_output"
            || workflowId === "finish_proof"
            || workflowId === "publish_record"
            || workflowId === "keep_baseline"
            || (workflowId === "queue_dev_review" && publishState === "draft_only");
        }
        return workflowId === "create_output"
          || workflowId === "finish_proof"
          || workflowId === "publish_record"
          || (workflowId === "queue_dev_review" && publishState === "draft_only");
      });
    }

    function creationProjectFamilyWorkflowActionCount(context, mode = "publish") {
      return creationProjectFamilyWorkflowTargetEntries(context, mode).length;
    }

    function creationProjectFamilyPacketWorkflowActionSpec(workflowId = "") {
      const normalizedWorkflowId = normalizeCreationWorkflowRecommendationId(workflowId);
      switch (normalizedWorkflowId) {
        case "create_output":
        case "finish_proof":
        case "publish_record":
          return {
            onclick: "runCreationProjectFamilyWorkflow('publish')",
            title: "Run the family publish pass",
            meta: "Create missing outputs, finish proof where possible, and save the first publish record for this family.",
          };
        case "queue_dev_review":
          return {
            onclick: "runCreationProjectFamilyWorkflow('queue')",
            title: "Run the family queue pass",
            meta: "Create, prove, publish, and stage the family for dev-side review from this saved-project shelf.",
          };
        case "review_dev_queue":
          return {
            onclick: "setLabTab('create'); renderCreationLibrarySurface(); scrollToElementId('creation-library-handoff-board')",
            title: "Open the family queue review lane",
            meta: "This family is already moving through dev-side review, so the queue is the clearest next surface.",
          };
        case "keep_baseline":
          return {
            onclick: "runCreationProjectFamilyWorkflow('keep')",
            title: "Run the family keep pass",
            meta: "Promote fully proved family drafts as kept local baselines where possible.",
          };
        case "resume_journey":
          return {
            onclick: "setLabTab('create'); scrollToElementId('creation-journey')",
            title: "Resume the latest Journey room",
            meta: "The latest Journey bundle already points at this family.",
          };
        case "archived":
          return {
            onclick: "focusCreationProjectFamily()",
            title: "Focus the saved-project family shelf",
            meta: "This family is archived locally, so the shelf is the clearest place to review it.",
          };
        default:
          return {
            onclick: "focusCreationProjectFamily()",
            title: "Focus the saved-project family shelf",
            meta: "The best next move is local refinement inside the family workspace.",
          };
      }
    }

    async function runCreationProjectFamilyWorkflow(mode = "publish", options = {}) {
      const context = options?.context && typeof options.context === "object"
        ? options.context
        : currentCreationProjectFamilyContext();
      if (!context) {
        setCreationStatus("No saved-project family is active on this shelf.");
        return null;
      }
      const modeSpec = creationProjectFamilyWorkflowModeSpec(mode);
      const targetEntries = creationProjectFamilyWorkflowTargetEntries(context, modeSpec.id);
      if (!targetEntries.length) {
        setCreationStatus(`No saved-project family members currently need ${modeSpec.label.toLowerCase()} inside ${context.label}.`);
        return null;
      }
      const suppressStatus = options?.suppressStatus === true;
      if (!suppressStatus) {
        setCreationStatus(`${modeSpec.pending} ${context.label}...`);
      }
      const performedLines = [];
      const skippedLines = [];
      const failedIds = [];
      let updatedCount = 0;
      let lastProjectId = "";
      let lastPublishId = "";
      let lastPackageKey = "";
      for (const targetEntry of targetEntries) {
        const projectId = String(targetEntry?.id || "").trim();
        const worldLabel = creationProjectWorkflowEntryLabel(targetEntry);
        if (!projectId) {
          continue;
        }
        try {
          await loadCreationProject(projectId, { preserveJourneyReport: true });
          lastProjectId = projectId;
          let entry = latestCreationProjectEntryById(projectId) || targetEntry;
          let publishId = String(entry?.publishState?.latestPublishId || "").trim();
          let proof = creationProjectProofSummary(entry);
          if (proof.state === "pending") {
            await runCurrentCreationWorkflowCreateOutput(publishId);
            performedLines.push(`Created the first world output for ${worldLabel}.`);
            updatedCount += 1;
            await refreshCreationProjects();
            await refreshCreationPublishes();
            entry = latestCreationProjectEntryById(projectId) || entry;
            publishId = String(entry?.publishState?.latestPublishId || "").trim();
            proof = creationProjectProofSummary(entry);
          }
          if (proof.state === "created" || proof.state === "partial") {
            const proofResult = await runCurrentCreationWorkflowFinishProof(publishId);
            if (proofResult?.blocked) {
              skippedLines.push(`${worldLabel}: ${proofResult.runtimeState?.summary || "Live proof is not available on this runtime right now."}`);
            } else {
              performedLines.push(`Finished live proof for ${worldLabel}.`);
              updatedCount += 1;
              await refreshCreationProjects();
              await refreshCreationPublishes();
              entry = latestCreationProjectEntryById(projectId) || entry;
              publishId = String(entry?.publishState?.latestPublishId || "").trim();
            }
            proof = creationProjectProofSummary(entry);
          }
          const needsDraftPublish = !publishId && (modeSpec.id === "publish" || modeSpec.id === "keep" || proof.state === "proved");
          if (needsDraftPublish) {
            const savedPublish = await saveCreationProjectFirstPublish(projectId, "draft");
            activeCreationPublishId = String(savedPublish?.id || activeCreationPublishId || "").trim();
            performedLines.push(`Saved the first publish record for ${worldLabel}.`);
            updatedCount += 1;
            await refreshCreationProjects();
            await refreshCreationPublishes();
            entry = latestCreationProjectEntryById(projectId) || entry;
            publishId = String(entry?.publishState?.latestPublishId || savedPublish?.id || "").trim();
          }
          if (modeSpec.id === "queue") {
            entry = latestCreationProjectEntryById(projectId) || entry;
            publishId = String(entry?.publishState?.latestPublishId || publishId).trim();
            if (!publishId) {
              const savedPublish = await saveCreationProjectFirstPublish(projectId, "sent");
              activeCreationPublishId = String(savedPublish?.id || activeCreationPublishId || "").trim();
              performedLines.push(`Created and sent the first publish record for ${worldLabel}.`);
              updatedCount += 1;
              await refreshCreationProjects();
              await refreshCreationPublishes();
              entry = latestCreationProjectEntryById(projectId) || entry;
              publishId = String(entry?.publishState?.latestPublishId || savedPublish?.id || "").trim();
            }
            let laneState = creationWorkflowPublishLaneState(entry);
            if (publishId && laneState === "draft") {
              const savedPublish = await updateCreationProjectPublishLane(publishId, "mark_ready");
              activeCreationPublishId = String(savedPublish?.id || publishId).trim();
              performedLines.push(`Marked ${worldLabel} ready for dev side.`);
              updatedCount += 1;
              await refreshCreationProjects();
              await refreshCreationPublishes();
              entry = latestCreationProjectEntryById(projectId) || entry;
              publishId = String(entry?.publishState?.latestPublishId || savedPublish?.id || publishId).trim();
              laneState = creationWorkflowPublishLaneState(entry);
            }
            if (publishId && laneState === "handoff_ready") {
              const savedPublish = await updateCreationProjectPublishLane(publishId, "send");
              activeCreationPublishId = String(savedPublish?.id || publishId).trim();
              performedLines.push(`Sent ${worldLabel} to the dev-side queue.`);
              updatedCount += 1;
              await refreshCreationProjects();
              await refreshCreationPublishes();
              entry = latestCreationProjectEntryById(projectId) || entry;
              publishId = String(entry?.publishState?.latestPublishId || savedPublish?.id || publishId).trim();
            }
          } else if (modeSpec.id === "keep") {
            entry = latestCreationProjectEntryById(projectId) || entry;
            publishId = String(entry?.publishState?.latestPublishId || publishId).trim();
            const latestProof = creationProjectProofSummary(entry);
            if (publishId && creationWorkflowPublishLaneState(entry) === "draft" && latestProof.state === "proved") {
              const savedPublish = await promoteStoredCreationPublishRecord(publishId);
              activeCreationPublishId = String(savedPublish?.id || publishId).trim();
              performedLines.push(`Promoted ${worldLabel} as the kept local baseline.`);
              updatedCount += 1;
              await refreshCreationProjects();
              await refreshCreationPublishes();
              entry = latestCreationProjectEntryById(projectId) || entry;
              publishId = String(entry?.publishState?.latestPublishId || savedPublish?.id || publishId).trim();
            } else if (publishId && latestProof.state !== "proved") {
              skippedLines.push(`${worldLabel}: Keep Local Baseline still needs finished proof before Studio can promote it.`);
            }
          }
          lastPublishId = String(activeCreationPublishId || publishId || lastPublishId).trim();
          lastPackageKey = String(currentActiveCreationPublishEntry()?.packageKey || lastPackageKey).trim();
        } catch (error) {
          failedIds.push(`${worldLabel}: ${error.message}`);
        }
      }
      const focusActionId = modeSpec.id === "queue" ? "send" : (modeSpec.id === "keep" ? "promote_kept" : "publish_draft");
      creationProjectFamilyFocusAfterAction(context.familyKey, focusActionId, updatedCount);
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      const finalContext = currentCreationProjectFamilyContext() || context;
      const workflowLine = creationProjectFamilyWorkflowSummary(finalContext, { includePublishRecord: true }) || "No family workflow cues yet.";
      const reportLine = creationProjectFamilyReportSummary(finalContext) || "No family report cues yet.";
      const handoffLine = creationProjectFamilyHandoffSummary(finalContext) || "No queued family handoff activity yet.";
      const focusPublish = currentActiveCreationPublishEntry();
      const statusLine = `${modeSpec.success} ${finalContext.label}. Updated ${updatedCount}${failedIds.length ? `; ${failedIds.length} failed` : ""}.`;
      if (!suppressStatus) {
        setCreationStatus(statusLine + (skippedLines.length ? " Some proof steps were skipped where runtime was unavailable." : ""));
      }
      return {
        mode: modeSpec.id,
        familyKey: String(finalContext?.familyKey || context.familyKey || "").trim(),
        familyLabel: String(finalContext?.label || context.label || "").trim(),
        familySummary: creationProjectFamilySummary(finalContext),
        workflowLine,
        reportLine,
        handoffLine,
        followupLine: modeSpec.id === "queue"
          ? `Family workflow: ran create/prove/publish/queue across ${finalContext.familyEntries.length} family world(s).`
          : (modeSpec.id === "keep"
              ? `Family workflow: ran create/prove/publish/keep across ${finalContext.familyEntries.length} family world(s).`
              : `Family workflow: ran create/prove/publish across ${finalContext.familyEntries.length} family world(s).`),
        performedLines,
        skippedLines,
        failedIds,
        updatedCount,
        projectId: lastProjectId,
        projectName: lastProjectId ? currentCreationProjectName() : "",
        focusPublishId: String(focusPublish?.id || lastPublishId || "").trim(),
        focusPackageKey: String(focusPublish?.packageKey || lastPackageKey || "").trim(),
        rootProjectId: String(finalContext?.rootEntry?.id || "").trim(),
        rootProjectName: String(finalContext?.rootEntry?.name || "").trim(),
        familyHasHandoff: Boolean(handoffLine),
        familyHasQueued: Number(finalContext?.publishLifecycleCounts?.handoff_ready || 0) + Number(finalContext?.publishLifecycleCounts?.sent || 0) + Number(finalContext?.publishLifecycleCounts?.claimed || 0) > 0,
      };
    }

    async function runCreationProjectFamilyWorkflowByKey(familyKey = "", mode = "publish", options = {}) {
      const visibleEntries = filteredCreationProjects(latestCreationProjects, creationProjectUiState);
      const context = creationProjectFamilyContextByKey(familyKey, visibleEntries, creationProjectFamilyLabels());
      if (!context) {
        setCreationStatus("No visible saved-project family is available on this shelf.");
        return null;
      }
      return runCreationProjectFamilyWorkflow(mode, {
        ...options,
        context,
      });
    }

    async function openCreationProjectFirstVisibleFamilyBoardLane(laneId = "needs_proof", targetOverride = "") {
      const spec = creationProjectFamilyBoardLaneSpec(laneId);
      const contexts = creationProjectFamilyBoardLaneContexts(spec.id);
      const context = contexts[0] || null;
      if (!context?.familyKey) {
        setCreationStatus(spec.emptyLine);
        return;
      }
      const target = String(targetOverride || spec.openTarget || "family").trim().toLowerCase();
      if (target === "queue") {
        await openCreationProjectFamilyQueueReviewByKey(context.familyKey);
        return;
      }
      focusCreationProjectFamilyByKey(context.familyKey, {
        render: true,
        setStatusMessage: `Focused the saved-project shelf on family ${context.label}.`,
      });
    }

    async function runVisibleCreationProjectFamiliesWorkflow(mode = "publish", options = {}) {
      const originalUiState = {
        ...creationProjectUiState,
      };
      const visibleEntries = Array.isArray(options?.visibleEntries)
        ? options.visibleEntries.filter(Boolean)
        : filteredCreationProjects(latestCreationProjects, creationProjectUiState);
      const familyLabels = options?.familyLabels && typeof options.familyLabels === "object"
        ? options.familyLabels
        : creationProjectFamilyLabels();
      const contexts = Array.isArray(options?.contexts)
        ? options.contexts.filter(Boolean)
        : visibleCreationProjectFamilyContexts(visibleEntries, familyLabels);
      if (!contexts.length) {
        setCreationStatus(String(options?.emptyMessage || "No visible saved-project families are available for this workflow yet."));
        return null;
      }
      const modeSpec = creationProjectFamilyWorkflowModeSpec(mode);
      const scopeLabel = String(options?.scopeLabel || `${contexts.length} visible saved-project famil${contexts.length === 1 ? "y" : "ies"}`).trim();
      setCreationStatus(`${modeSpec.pending} ${scopeLabel}...`);
      const performedFamilies = [];
      const skippedFamilies = [];
      const failedFamilies = [];
      let updatedCount = 0;
      let lastResult = null;
      for (const context of contexts) {
        try {
          const result = await runCreationProjectFamilyWorkflow(modeSpec.id, {
            context,
            suppressStatus: true,
          });
          if (!result) {
            continue;
          }
          lastResult = result;
          updatedCount += Number(result.updatedCount || 0);
          if (Array.isArray(result.performedLines) && result.performedLines.length) {
            performedFamilies.push(context.label);
          }
          if (Array.isArray(result.skippedLines) && result.skippedLines.length) {
            skippedFamilies.push(`${context.label}: ${result.skippedLines[0]}`);
          }
          if (Array.isArray(result.failedIds) && result.failedIds.length) {
            failedFamilies.push(`${context.label}: ${result.failedIds[0]}`);
          }
        } catch (error) {
          failedFamilies.push(`${context.label}: ${error.message}`);
        }
      }
      creationProjectUiState = {
        ...originalUiState,
      };
      saveCreationProjectUiState();
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      const summary = `${modeSpec.success} ${scopeLabel}. Updated ${updatedCount}${failedFamilies.length ? `; ${failedFamilies.length} failed` : ""}.`;
      setCreationStatus(summary + (skippedFamilies.length ? " Some proof steps were skipped where runtime was unavailable." : ""));
      return {
        mode: modeSpec.id,
        familyCount: contexts.length,
        updatedCount,
        performedFamilies,
        skippedFamilies,
        failedFamilies,
        lastResult,
      };
    }

    async function runVisibleCreationProjectFamilyBoardLane(laneId = "needs_proof") {
      const spec = creationProjectFamilyBoardLaneSpec(laneId);
      if (!spec.mode) {
        return openCreationProjectFirstVisibleFamilyBoardLane(spec.id, spec.openTarget);
      }
      const contexts = creationProjectFamilyBoardLaneContexts(spec.id);
      return runVisibleCreationProjectFamiliesWorkflow(spec.mode, {
        contexts,
        scopeLabel: `${contexts.length} visible saved-project famil${contexts.length === 1 ? "y" : "ies"} in ${spec.label}`,
        emptyMessage: spec.emptyLine,
      });
    }

    function creationProjectFamilyRoomDeckContexts(roomId = "workflow", contexts = visibleCreationProjectFamilyContexts()) {
      const spec = creationFamilyRoomDeckSpec(roomId);
      return (Array.isArray(spec?.laneIds) ? spec.laneIds : [])
        .flatMap(laneId => creationProjectFamilyBoardLaneContexts(laneId, contexts))
        .filter(Boolean);
    }

    async function openCreationProjectFamilyRoomDeck(roomId = "workflow") {
      const spec = creationFamilyRoomDeckSpec(roomId);
      const openLaneIds = Array.isArray(spec.openLaneIds) ? spec.openLaneIds : [];
      for (const laneId of openLaneIds) {
        const laneContexts = creationProjectFamilyBoardLaneContexts(laneId);
        if (laneContexts.length) {
          return openCreationProjectFirstVisibleFamilyBoardLane(laneId, creationProjectFamilyBoardLaneSpec(laneId).openTarget);
        }
      }
      setCreationStatus(spec.emptyLine);
      return null;
    }

    async function runCreationProjectFamilyRoomDeck(roomId = "workflow") {
      const spec = creationFamilyRoomDeckSpec(roomId);
      const runLaneId = String(spec?.runLaneId || "").trim().toLowerCase();
      if (!runLaneId) {
        return openCreationProjectFamilyRoomDeck(spec.id);
      }
      const laneContexts = creationProjectFamilyBoardLaneContexts(runLaneId);
      if (!laneContexts.length) {
        setCreationStatus(spec.emptyLine);
        return null;
      }
      return runVisibleCreationProjectFamilyBoardLane(runLaneId);
    }

    function renderCreationProjectFamilyRoomDeckCard(roomId = "workflow", contexts = visibleCreationProjectFamilyContexts()) {
      const spec = creationFamilyRoomDeckSpec(roomId);
      const laneCounts = creationProjectFamilyBoardLaneCounts(contexts);
      const roomContexts = creationProjectFamilyRoomDeckContexts(spec.id, contexts);
      const roomCount = creationFamilyRoomDeckCount(laneCounts, spec.laneIds);
      const runCount = Number(laneCounts?.[spec.runLaneId] || 0);
      const familyLabels = creationFamilyRoomDeckLabels(roomContexts, "label");
      const firstContext = roomContexts[0] || null;
      const roomSummary = creationFamilyRoomDeckLaneSummary(spec, laneCounts, creationProjectFamilyBoardLaneSpec);
      const visibleLine = familyLabels.length
        ? `Visible now: ${familyLabels.join(" | ")}${roomCount > familyLabels.length ? " ..." : ""}`
        : spec.emptyLine;
      return `
        <div class="field-hint-card">
          <div class="field-hint-title">${esc(spec.label)}</div>
          <div class="field-hint-body">${esc(spec.helper)}</div>
          <div class="field-hint-meta" style="margin-top:8px;">${renderSimpleList([
            `Visible families: ${roomCount}`,
            `Room board: ${roomSummary}`,
            visibleLine,
            firstContext?.workflowCounts ? `First family snapshot: ${creationProjectFamilyReportSummary(firstContext) || "No visible family is in this room yet."}` : "First family snapshot: no visible family is in this room yet.",
          ])}</div>
          <div class="creation-project-bulk-actions creation-project-bulk-actions-secondary" style="margin-top:10px;">
            <button class="btn mini" onclick="openCreationProjectFamilyRoomDeck('${esc(spec.id)}')" ${roomCount > 0 ? "" : "disabled"}>${esc(spec.label)}</button>
            <button class="btn mini" onclick="runCreationProjectFamilyRoomDeck('${esc(spec.id)}')" ${runCount > 0 ? "" : "disabled"}>${esc(spec.runActionLabel || "Run Room")} (${esc(runCount)})</button>
          </div>
        </div>
      `;
    }

    async function publishCreationProjectFamilyDrafts(mode = "draft") {
      const context = currentCreationProjectFamilyContext();
      if (!context) {
        setCreationStatus("No saved-project family is active on this shelf.");
        return;
      }
      const spec = creationProjectFirstPublishSpec(mode);
      const targetEntries = creationProjectEntriesByPublishStateFilter("draft_only", context.familyEntries);
      if (!targetEntries.length) {
        setCreationStatus(`No Draft Only projects are waiting inside family ${context.label}.`);
        return;
      }
      setCreationStatus(`${spec.pending} Family ${context.label}.`);
      let createdCount = 0;
      const failedIds = [];
      for (const entry of targetEntries) {
        try {
          await saveCreationProjectFirstPublish(entry.id, spec.id);
          createdCount += 1;
        } catch (_) {
          failedIds.push(entry?.id || "");
        }
      }
      creationProjectFamilyFocusAfterAction(context.familyKey, `publish_${spec.id}`, createdCount);
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      if (failedIds.length) {
        setCreationStatus(`${spec.success} Family ${context.label}: created ${createdCount}; ${failedIds.length} failed.`);
        return;
      }
      setCreationStatus(`${spec.success} Family ${context.label}: created ${createdCount}.`);
    }

    async function branchCreationProjectFamily(mode = "new_version") {
      const context = currentCreationProjectFamilyContext();
      if (!context) {
        setCreationStatus("No saved-project family is active on this shelf.");
        return;
      }
      const normalizedMode = String(mode || "new_version").trim().toLowerCase();
      const actionMeta = {
        new_version: {
          targets: context.branchableEntries,
          pending: `Creating new draft versions across family ${context.label}...`,
          success: `Created new draft versions across family ${context.label}.`,
          label: "published family members",
        },
        variant: {
          targets: context.rootBranchEntry ? [context.rootBranchEntry] : [],
          pending: `Creating a new variant branch from family root ${context.label}...`,
          success: `Created a new variant branch from family root ${context.label}.`,
          label: "published family root",
        },
        sequel: {
          targets: context.rootBranchEntry ? [context.rootBranchEntry] : [],
          pending: `Creating a new sequel branch from family root ${context.label}...`,
          success: `Created a new sequel branch from family root ${context.label}.`,
          label: "published family root",
        },
      }[normalizedMode] || {
        targets: context.branchableEntries,
        pending: `Creating new draft versions across family ${context.label}...`,
        success: `Created new draft versions across family ${context.label}.`,
        label: "published family members",
      };
      const targetEntries = Array.isArray(actionMeta.targets) ? actionMeta.targets : [];
      if (!targetEntries.length) {
        setCreationStatus(`No ${actionMeta.label} are ready on this family shelf.`);
        return;
      }
      setCreationStatus(actionMeta.pending);
      let createdCount = 0;
      const failedIds = [];
      for (const entry of targetEntries) {
        try {
          if (normalizedMode === "new_version") {
            await saveCreationProjectFirstPublish(entry.id, "draft");
          } else {
            const publishId = String(entry?.publishState?.latestPublishId || "").trim();
            if (!publishId) {
              throw new Error("Missing latest publish.");
            }
            const publish = await fetchJson("/studio/creation-publishes/" + encodeURIComponent(publishId));
            const derived = buildDerivedCreationProjectFromPublish(publish, normalizedMode);
            const savedProject = await saveStoredCreationProjectRecord(derived.derivedWorldName, derived.payload);
            await saveCreationProjectFirstPublish(savedProject.id || "", "draft");
          }
          createdCount += 1;
        } catch (_) {
          failedIds.push(entry?.id || "");
        }
      }
      creationProjectFamilyFocusAfterBranch(context.familyKey, createdCount);
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      if (failedIds.length) {
        setCreationStatus(`${actionMeta.success} Created ${createdCount}; ${failedIds.length} failed.`);
        return;
      }
      setCreationStatus(`${actionMeta.success} Created ${createdCount}.`);
    }

    function creationProjectFirstPublishSpec(mode = "draft") {
      const normalized = String(mode || "").trim().toLowerCase();
      if (normalized === "ready") {
        return {
          id: "ready",
          label: "ready-for-dev first publish",
          summaryLabel: "Ready For Dev",
          nameSuffix: "Ready For Dev",
          decision: "needs_dev_side",
          lifecycleState: "handoff_ready",
          handoffState: "ready",
          nextLifecycle: "handoff_ready",
          pending: "Creating ready-for-dev first publishes from the visible draft-only shelf...",
          success: "Created ready-for-dev first publishes from the visible draft-only shelf.",
        };
      }
      if (normalized === "sent") {
        return {
          id: "sent",
          label: "sent-to-dev first publish",
          summaryLabel: "Sent To Dev",
          nameSuffix: "Sent To Dev",
          decision: "needs_dev_side",
          lifecycleState: "handoff_ready",
          handoffState: "sent",
          nextLifecycle: "sent",
          pending: "Creating sent-to-dev first publishes from the visible draft-only shelf...",
          success: "Created sent-to-dev first publishes from the visible draft-only shelf.",
        };
      }
      return {
        id: "draft",
        label: "local-draft first publish",
        summaryLabel: "Draft Lane",
        nameSuffix: "Keep As Draft",
        decision: "keep_draft",
        lifecycleState: "draft",
        handoffState: "none",
        nextLifecycle: "draft",
        pending: "Creating first publish drafts from the visible draft-only shelf...",
        success: "Created first publish drafts from the visible draft-only shelf.",
      };
    }

    function creationProjectShelfAdvanceAfterLaneAction(actionId = "", updatedCount = 0) {
      if (Number(updatedCount || 0) < 1) {
        return;
      }
      const normalizedAction = String(actionId || "").trim().toLowerCase();
      if (normalizedAction === "new_version" || normalizedAction === "branch_variant" || normalizedAction === "branch_sequel") {
        creationProjectUiState = {
          ...creationProjectUiState,
          publishState: "published",
          publishLifecycle: "draft",
          lineageMode: normalizedAction === "branch_variant"
            ? "variant"
            : (normalizedAction === "branch_sequel" ? "sequel" : creationProjectUiState.lineageMode),
        };
        saveCreationProjectUiState();
        return;
      }
      let nextLifecycle = "";
      if (normalizedAction === "publish_draft") {
        nextLifecycle = "draft";
      } else if (normalizedAction === "publish_ready" || normalizedAction === "mark_ready") {
        nextLifecycle = "handoff_ready";
      } else if (normalizedAction === "publish_sent" || normalizedAction === "send") {
        nextLifecycle = "sent";
      } else if (normalizedAction === "claim") {
        nextLifecycle = "claimed";
      } else if (normalizedAction === "return_to_sent") {
        nextLifecycle = "sent";
      } else if (normalizedAction === "keep_local") {
        nextLifecycle = "draft";
      } else if (normalizedAction === "promote_kept") {
        nextLifecycle = "kept_local";
      } else if (normalizedAction === "archive") {
        nextLifecycle = "archived";
      }
      if (!nextLifecycle) {
        return;
      }
      const shouldShiftFromDraftState = (normalizedAction === "publish_draft" || normalizedAction === "publish_ready" || normalizedAction === "publish_sent")
        && creationProjectUiState.publishState === "draft_only";
      const shouldShiftFromDraftLifecycle = (normalizedAction === "publish_draft" || normalizedAction === "publish_ready" || normalizedAction === "publish_sent")
        && creationProjectUiState.publishLifecycle === "draft";
      const shouldShiftFromLifecycle = (
        (normalizedAction === "mark_ready" && creationProjectUiState.publishLifecycle === "draft")
        || (normalizedAction === "send" && creationProjectUiState.publishLifecycle === "handoff_ready")
        || (normalizedAction === "claim" && creationProjectUiState.publishLifecycle === "sent")
        || (normalizedAction === "return_to_sent" && creationProjectUiState.publishLifecycle === "claimed")
        || (normalizedAction === "keep_local" && (creationProjectUiState.publishLifecycle === "handoff_ready" || creationProjectUiState.publishLifecycle === "sent" || creationProjectUiState.publishLifecycle === "claimed"))
        || (normalizedAction === "promote_kept" && (creationProjectUiState.publishLifecycle === "draft" || creationProjectUiState.publishLifecycle === "handoff_ready" || creationProjectUiState.publishLifecycle === "sent" || creationProjectUiState.publishLifecycle === "claimed"))
        || (normalizedAction === "archive" && creationProjectUiState.publishLifecycle !== "all" && creationProjectUiState.publishLifecycle !== "archived")
      );
      if (!shouldShiftFromDraftState && !shouldShiftFromDraftLifecycle && !shouldShiftFromLifecycle) {
        return;
      }
      creationProjectUiState = {
        ...creationProjectUiState,
        publishState: "all",
        publishLifecycle: nextLifecycle,
      };
      saveCreationProjectUiState();
    }

    function buildCreationProjectFirstPublishPayload(project, spec = creationProjectFirstPublishSpec("draft")) {
      const projectPayload = project?.payload && typeof project.payload === "object" ? project.payload : {};
      const engineState = projectPayload?.engineState && typeof projectPayload.engineState === "object" ? projectPayload.engineState : {};
      const starterPackPreview = projectPayload?.starterPackPreview && typeof projectPayload.starterPackPreview === "object"
        ? projectPayload.starterPackPreview
        : null;
      const createdBundle = projectPayload?.createdBundle && typeof projectPayload.createdBundle === "object"
        ? projectPayload.createdBundle
        : null;
      const latestProbe = projectPayload?.latestProbeResult && typeof projectPayload.latestProbeResult === "object"
        ? projectPayload.latestProbeResult
        : null;
      const worldName = String(project?.worldName || engineState?.worldName || project?.name || "Untitled World").trim() || "Untitled World";
      const hostId = String(project?.hostId || engineState?.hostId || "unknown").trim() || "unknown";
      const programId = String(project?.programId || engineState?.programId || "unknown").trim() || "unknown";
      const toneId = String(project?.toneId || engineState?.toneId || "grounded_supportive").trim() || "grounded_supportive";
      const scaleId = String(project?.scaleId || engineState?.scaleId || "single_pilot").trim() || "single_pilot";
      const depthId = String(project?.depthId || engineState?.depthId || "useful_social").trim() || "useful_social";
      const roleCoverage = normalizeCreationRoleRefinementCoverage(project?.roleTuning || projectPayload?.blueprint?.roleRefinementCoverage, false);
      const coverageSummary = roleCoverage?.summary || "Tuned coverage: No role seeds yet.";
      const packEntries = Array.isArray(starterPackPreview?.entries) ? starterPackPreview.entries : [];
      const voiceSmokeEntries = Array.isArray(starterPackPreview?.voiceSmoke?.entries) ? starterPackPreview.voiceSmoke.entries : [];
      const sceneSmokeEntries = Array.isArray(starterPackPreview?.sceneSmoke?.entries) ? starterPackPreview.sceneSmoke.entries : [];
      const proofPayload = {};
      if (createdBundle?.fpc?.id) {
        proofPayload.createdOutput = {
          kind: "draft_bundle",
          createdCount: 1,
        };
      }
      if (starterPackPreview?.created || packEntries.length) {
        proofPayload.createdOutput = {
          kind: "starter_pack",
          createdCount: Math.max(packEntries.length, 1),
        };
        proofPayload.packProof = {
          roleCount: Math.max(packEntries.length, 1),
        };
        if (voiceSmokeEntries.length) {
          proofPayload.packProof.voiceSmoke = {
            entries: voiceSmokeEntries,
          };
        }
        if (sceneSmokeEntries.length) {
          proofPayload.packProof.sceneSmoke = {
            entries: sceneSmokeEntries,
          };
        }
      }
      if (latestProbe) {
        proofPayload.latestProbeResult = latestProbe;
      }
      return {
        worldName,
        hostId,
        programId,
        toneId,
        scaleId,
        depthId,
        ...proofPayload,
        recommendation: {
          decision: spec.decision,
          summaryLines: [
            `${worldName} was first published from the saved-project shelf as ${spec.summaryLabel}.`,
            coverageSummary,
          ],
          proofLines: [
            `Saved-project source: ${project?.name || project?.id || worldName}`,
            `Publish lane target: ${spec.summaryLabel}`,
          ],
        },
        projectPayload,
      };
    }

    async function saveCreationProjectFirstPublish(projectId, mode = "draft") {
      const spec = creationProjectFirstPublishSpec(mode);
      const project = await fetchJson("/studio/creation-projects/" + encodeURIComponent(projectId));
      const worldName = String(project?.worldName || project?.payload?.engineState?.worldName || project?.name || "World").trim() || "World";
      return postJson("/studio/creation-publishes", {
        projectId: project.id || projectId,
        name: `${worldName} :: ${spec.nameSuffix}`,
        decision: spec.decision,
        lifecycleState: spec.lifecycleState,
        handoffState: spec.handoffState,
        payload: buildCreationProjectFirstPublishPayload(project, spec),
      });
    }

    async function focusCreationWorkflowPublishContext(publishId = "", packageKey = "", options = {}) {
      const normalizedPublishId = String(publishId || "").trim();
      let publish = null;
      if (normalizedPublishId) {
        publish = latestCreationPublishes.find(entry => String(entry?.id || "").trim() === normalizedPublishId) || null;
        if (!publish) {
          publish = await fetchJson("/studio/creation-publishes/" + encodeURIComponent(normalizedPublishId));
        }
      }
      const resolvedPublishId = String(normalizedPublishId || publish?.id || "").trim();
      const resolvedPackageKey = String(packageKey || publish?.packageKey || "").trim();
      if (options.openCreate && resolvedPublishId) {
        await openCreationPublishInCreate(resolvedPublishId);
        if (options.statusMessage) {
          setCreationStatus(options.statusMessage);
        }
        return publish;
      }
      if (resolvedPackageKey) {
        await loadCreationLibraryPackageFocus(resolvedPackageKey, resolvedPublishId);
        setLabTab("create");
        if (options.openQueue) {
          scrollToElementId("creation-library-handoff-board");
        } else {
          scrollToElementId("creation-library-focus");
        }
        if (options.statusMessage) {
          setCreationStatus(options.statusMessage);
        }
      }
      return publish;
    }

    async function refreshCreationWorkflowSurfaces(options = {}) {
      await refreshCreationPublishes();
      await refreshCreationProjects();
      if (options.publishId || options.packageKey) {
        await focusCreationWorkflowPublishContext(options.publishId, options.packageKey, {
          openCreate: options.openCreate,
          openQueue: options.openQueue,
          statusMessage: options.statusMessage,
        });
      } else if (options.statusMessage) {
        setCreationStatus(options.statusMessage);
      }
      renderCreationJourney();
      renderCreationEnginePreview();
    }

    async function runCurrentCreationWorkflowCreateOutput(syncPublishId = "") {
      let state = currentCreationJourneyState();
      if (!state.hasCreated) {
        await createMyWorldNow();
        state = currentCreationJourneyState();
      }
      if (!state.hasCreated) {
        throw new Error(state.needsPack
          ? "Studio still has not created the starter pack for this workspace."
          : "Studio still has not created the first draft bundle for this workspace.");
      }
      await saveCreationProject();
      if (syncPublishId) {
        activeCreationPublishId = syncPublishId;
        const currentPublish = currentActiveCreationPublishEntry();
        if (currentPublish?.id) {
          await saveCreationPublish(currentPublish.decision || "keep_draft");
        }
      }
      return currentCreationJourneyState();
    }

    async function runCurrentCreationWorkflowFinishProof(syncPublishId = "") {
      await ensureCreationWorkflowStatus(true);
      const runtimeState = currentCreationJourneyRuntimeState();
      if (!runtimeState.canRunLiveProof) {
        setCreationStatus(runtimeState.summary);
        return {
          blocked: true,
          runtimeState,
        };
      }
      let state = currentCreationJourneyState();
      if (!state.hasCreated) {
        state = await runCurrentCreationWorkflowCreateOutput(syncPublishId);
      }
      if (state.needsPack) {
        if (!state.hasPackVoiceSmoke) {
          await runCreationPackVoiceSmoke();
        }
        state = currentCreationJourneyState();
        if (!state.hasPackSceneSmoke) {
          await runCreationSceneSmoke();
        }
      } else if (!currentCreationLiveProofResult()) {
        await runCreationSmokeProbe();
      }
      await saveCreationProject();
      if (syncPublishId) {
        activeCreationPublishId = syncPublishId;
        const currentPublish = currentActiveCreationPublishEntry();
        if (currentPublish?.id) {
          await saveCreationPublish(currentPublish.decision || "keep_draft");
        }
      }
      return {
        blocked: false,
        runtimeState,
        state: currentCreationJourneyState(),
      };
    }

    async function runCreationProjectWorkflowAction(projectId, actionId = "") {
      const normalizedProjectId = String(projectId || "").trim();
      if (!normalizedProjectId) {
        setCreationStatus("That saved project is no longer available.");
        return;
      }
      const normalizedAction = String(actionId || "").trim().toLowerCase();
      const entry = latestCreationProjects.find(item => String(item?.id || "").trim() === normalizedProjectId) || null;
      const publishId = String(entry?.publishState?.latestPublishId || "").trim();
      try {
        if (normalizedAction === "resume_journey") {
          const report = latestCreationJourneyReportForProject(normalizedProjectId);
          if (!report) {
            setCreationStatus("No active Journey bundle report is attached to that saved project.");
            return;
          }
          await runCreationJourneyBundleReportAction("open_workspace");
          setLabTab("create");
          scrollToElementId("creation-journey");
          setCreationStatus("Opened the latest Journey bundle report for this workspace.");
          return;
        }
        if (normalizedAction === "open_create" || normalizedAction === "refine_local" || normalizedAction === "archived") {
          await loadCreationProject(normalizedProjectId, { preserveJourneyReport: true });
          setLabTab("create");
          scrollToElementId("creation-engine-preview");
          setCreationStatus("Opened the saved project in Create.");
          return;
        }
        if (normalizedAction === "create_output") {
          await loadCreationProject(normalizedProjectId, { preserveJourneyReport: true });
          setLabTab("create");
          scrollToElementId("creation-engine-preview");
          await runCurrentCreationWorkflowCreateOutput(publishId);
          await refreshCreationWorkflowSurfaces({
            publishId,
            statusMessage: "Created the first world output for this saved project.",
          });
          return;
        }
        if (normalizedAction === "finish_proof") {
          await loadCreationProject(normalizedProjectId, { preserveJourneyReport: true });
          setLabTab("create");
          scrollToElementId("creation-engine-preview");
          const proofResult = await runCurrentCreationWorkflowFinishProof(publishId);
          if (!proofResult?.blocked) {
            await refreshCreationWorkflowSurfaces({
              publishId,
              statusMessage: "Finished the current live-proof pass for this saved project.",
            });
          }
          return;
        }
        if (normalizedAction === "publish_record") {
          const saved = await saveCreationProjectFirstPublish(normalizedProjectId, "draft");
          activeCreationPublishId = String(saved?.id || "").trim();
          await refreshCreationWorkflowSurfaces({
            publishId: activeCreationPublishId,
            packageKey: saved?.packageKey || "",
            statusMessage: "Saved the first publish record and opened its passport.",
          });
          return;
        }
        if (normalizedAction === "queue_dev_review") {
          let focusPublishId = publishId;
          let focusPackageKey = "";
          if (focusPublishId) {
            const saved = await updateCreationProjectPublishLane(focusPublishId, "send");
            focusPublishId = String(saved?.id || focusPublishId).trim();
            focusPackageKey = String(saved?.packageKey || "").trim();
          } else {
            const saved = await saveCreationProjectFirstPublish(normalizedProjectId, "sent");
            focusPublishId = String(saved?.id || "").trim();
            focusPackageKey = String(saved?.packageKey || "").trim();
          }
          await refreshCreationWorkflowSurfaces({
            publishId: focusPublishId,
            packageKey: focusPackageKey,
            openQueue: true,
            statusMessage: "Moved this saved project into the dev-side queue.",
          });
          return;
        }
        if (normalizedAction === "review_dev_queue") {
          if (!publishId) {
            setCreationStatus("This saved project does not have a publish record to review yet.");
            return;
          }
          await focusCreationWorkflowPublishContext(publishId, "", {
            openQueue: true,
            statusMessage: "Opened queue review for this saved project.",
          });
          return;
        }
        if (normalizedAction === "keep_baseline") {
          if (!publishId) {
            setCreationStatus("Create or publish this world first before promoting a kept baseline.");
            return;
          }
          const saved = await promoteStoredCreationPublishRecord(publishId);
          activeCreationPublishId = String(saved?.id || publishId).trim();
          await refreshCreationWorkflowSurfaces({
            publishId: activeCreationPublishId,
            packageKey: saved?.packageKey || "",
            statusMessage: "Promoted this world as the kept local baseline.",
          });
          return;
        }
        await loadCreationProject(normalizedProjectId, { preserveJourneyReport: true });
        setLabTab("create");
        scrollToElementId("creation-engine-preview");
        setCreationStatus("Opened the saved project in Create.");
      } catch (error) {
        setCreationStatus("Studio next move failed: " + error.message);
      }
    }

    async function runCreationPublishWorkflowAction(publishId, actionId = "", packageKey = "") {
      const normalizedPublishId = String(publishId || "").trim();
      if (!normalizedPublishId) {
        setCreationStatus("That publish record is no longer available.");
        return;
      }
      const normalizedAction = String(actionId || "").trim().toLowerCase();
      const focusPackageKey = String(packageKey || "").trim();
      try {
        if (normalizedAction === "resume_journey") {
          const publish = latestCreationPublishes.find(entry => String(entry?.id || "").trim() === normalizedPublishId) || await fetchJson("/studio/creation-publishes/" + encodeURIComponent(normalizedPublishId));
          const report = latestCreationJourneyReportForPublish({
            ...publish,
            packageKey: focusPackageKey || publish?.packageKey || "",
          });
          if (!report) {
            setCreationStatus("No active Journey bundle report is attached to that world package.");
            return;
          }
          if (String(report.projectId || "").trim()) {
            await runCreationJourneyBundleReportAction("open_workspace");
          }
          setLabTab("create");
          scrollToElementId("creation-journey");
          setCreationStatus("Opened the latest Journey bundle report for this world package.");
          return;
        }
        if (normalizedAction === "open_passport") {
          await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
            statusMessage: "Opened the package passport.",
          });
          return;
        }
        if (normalizedAction === "open_create" || normalizedAction === "refine_local" || normalizedAction === "archived") {
          await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
            openCreate: true,
            statusMessage: "Opened the world package in Create.",
          });
          return;
        }
        if (normalizedAction === "create_output") {
          await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
            openCreate: true,
          });
          await runCurrentCreationWorkflowCreateOutput(normalizedPublishId);
          await refreshCreationWorkflowSurfaces({
            publishId: normalizedPublishId,
            packageKey: focusPackageKey,
            statusMessage: "Created the first world output for this package.",
          });
          return;
        }
        if (normalizedAction === "finish_proof") {
          await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
            openCreate: true,
          });
          const proofResult = await runCurrentCreationWorkflowFinishProof(normalizedPublishId);
          if (!proofResult?.blocked) {
            await refreshCreationWorkflowSurfaces({
              publishId: normalizedPublishId,
              packageKey: focusPackageKey,
              statusMessage: "Finished the current live-proof pass for this package.",
            });
          }
          return;
        }
        if (normalizedAction === "queue_dev_review") {
          await sendCreationPublishRecordToDevSide(normalizedPublishId);
          await refreshCreationWorkflowSurfaces({
            publishId: normalizedPublishId,
            packageKey: focusPackageKey,
            openQueue: true,
            statusMessage: "Moved this world package into the dev-side queue.",
          });
          return;
        }
        if (normalizedAction === "review_dev_queue") {
          await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
            openQueue: true,
            statusMessage: "Opened queue review for this world package.",
          });
          return;
        }
        if (normalizedAction === "keep_baseline") {
          await promoteCreationPublishRecord(normalizedPublishId);
          await refreshCreationWorkflowSurfaces({
            publishId: normalizedPublishId,
            packageKey: focusPackageKey,
            statusMessage: "Promoted this world package as the kept local baseline.",
          });
          return;
        }
        await focusCreationWorkflowPublishContext(normalizedPublishId, focusPackageKey, {
          openCreate: true,
          statusMessage: "Opened the world package in Create.",
        });
      } catch (error) {
        setCreationStatus("Studio next move failed: " + error.message);
      }
    }

    async function runFirstCreationProjectWorkflowAction(moveId = "") {
      const targetEntries = creationProjectEntriesByWorkflowRecommendation(moveId, filteredCreationProjects(latestCreationProjects, creationProjectUiState));
      if (!targetEntries.length) {
        setCreationStatus(`No visible saved projects currently match ${creationWorkflowRecommendationSpec(moveId).label}.`);
        return;
      }
      const target = targetEntries[0];
      const recommendation = creationProjectWorkflowRecommendation(target);
      await runCreationProjectWorkflowAction(target.id, recommendation.primaryActionId);
    }

    async function runFirstCreationLibraryWorkflowAction(moveId = "") {
      const targetGroups = creationLibraryGroupsByWorkflowRecommendation(moveId, filteredCreationLibraryGroups(currentCreationLibraryFilters()));
      if (!targetGroups.length) {
        setCreationStatus(`No visible world packages currently match ${creationWorkflowRecommendationSpec(moveId).label}.`);
        return;
      }
      const targetGroup = targetGroups[0];
      const active = targetGroup?.activeEntry || {};
      const recommendation = creationPublishWorkflowRecommendation(active, { packageKey: targetGroup?.packageKey || "" });
      await runCreationPublishWorkflowAction(active.id || "", recommendation.primaryActionId, targetGroup?.packageKey || "");
    }

    async function openCreationLibraryFamilyWorkflowTarget(workflowId = "", mode = "first") {
      const context = currentCreationLibraryFamilyPacketContext();
      if (!context?.focusGroup) {
        setCreationStatus("No World Library family is active yet.");
        return;
      }
      const targetGroups = creationLibraryFamilyGroupsByWorkflowRecommendation(workflowId, context);
      if (!targetGroups.length) {
        setCreationStatus(`No family package currently matches ${creationWorkflowRecommendationSpec(workflowId).label}.`);
        return;
      }
      const normalizedMode = String(mode || "first").trim().toLowerCase();
      let targetGroup = targetGroups[0];
      if (normalizedMode === "next") {
        const activeIndex = targetGroups.findIndex(group => String(group?.packageKey || "").trim().toLowerCase() === String(activeCreationLibraryPackageKey || "").trim().toLowerCase());
        if (activeIndex >= 0) {
          targetGroup = targetGroups[(activeIndex + 1) % targetGroups.length];
        }
      }
      const publishId = String(targetGroup?.activeEntry?.id || "").trim();
      const packageKey = String(targetGroup?.packageKey || "").trim();
      if (!publishId || !packageKey) {
        setCreationStatus("That family package no longer has an active publish record.");
        return;
      }
      const normalizedWorkflowId = normalizeCreationWorkflowRecommendationId(workflowId);
      if (normalizedWorkflowId === "review_dev_queue") {
        await focusCreationWorkflowPublishContext(publishId, packageKey, {
          openQueue: true,
          statusMessage: `Opened queue review for ${targetGroup?.worldName || targetGroup?.packageKey || "this family package"}.`,
        });
        return;
      }
      if (normalizedWorkflowId === "resume_journey") {
        await runCreationPublishWorkflowAction(publishId, "resume_journey", packageKey);
        return;
      }
      await focusCreationWorkflowPublishContext(publishId, packageKey, {
        openCreate: true,
        statusMessage: `Opened ${targetGroup?.worldName || targetGroup?.packageKey || "this family package"} in Create.`,
      });
    }

    function creationLibraryFamilyPacketWorkflowActionSpec(workflowId = "", options = {}) {
      const normalizedWorkflowId = normalizeCreationWorkflowRecommendationId(workflowId);
      const familyKey = normalizeCreationProjectFacetFilterId(options?.familyKey);
      const useFamilyKeyAction = options?.useFamilyKeyAction === true && familyKey !== "all";
      const publishCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("runCreationLibraryFamilyWorkflowForKey", familyKey, ["publish"]) : "runCreationLibraryFamilyWorkflow('publish')";
      const queueCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("runCreationLibraryFamilyWorkflowForKey", familyKey, ["queue"]) : "runCreationLibraryFamilyWorkflow('queue')";
      const keepCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("runCreationLibraryFamilyWorkflowForKey", familyKey, ["keep"]) : "runCreationLibraryFamilyWorkflow('keep')";
      const queueReviewCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("openCreationLibraryFamilyQueueReviewByKey", familyKey) : "openCreationLibraryFamilyQueueReview()";
      const openFamilyCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("openCreationLibraryFamilyRoom", familyKey) : "openCreationLibraryFamilyWorkflowTarget('refine_local')";
      const loadRootCall = useFamilyKeyAction ? creationLibraryFamilyActionCall("loadCreationLibraryFamilyRootByKey", familyKey) : "loadCreationLibraryFamilyRoot()";
      switch (normalizedWorkflowId) {
        case "create_output":
        case "finish_proof":
          return {
            onclick: publishCall,
            title: "Run the family publish/proof pass from World Library",
            meta: "Create missing outputs and finish proof across the active family without leaving the passport.",
          };
        case "queue_dev_review":
          return {
            onclick: queueCall,
            title: "Run the family queue pass from World Library",
            meta: "Batch move the active family toward the dev-side queue from this passport.",
          };
        case "review_dev_queue":
          return {
            onclick: queueReviewCall,
            title: "Open the family queue review lane",
            meta: "This family is already moving through dev-side review, so the queue is the clearest next surface.",
          };
        case "keep_baseline":
          return {
            onclick: keepCall,
            title: "Run the family keep-baseline pass",
            meta: "Promote fully proved family drafts as kept local baselines from this passport.",
          };
        case "resume_journey":
          return {
            onclick: "openCreationLibraryFamilyWorkflowTarget('resume_journey')",
            title: "Resume the latest Journey room",
            meta: "A recent Journey bundle still points at this family.",
          };
        case "archived":
          return {
            onclick: loadRootCall,
            title: "Open the family root package",
            meta: "This family is archived locally, so the root passport is the safest place to inspect it.",
          };
        default:
          return {
            onclick: openFamilyCall,
            title: "Open the active family package in Create",
            meta: "The best next move is local refinement on the active family package.",
          };
      }
    }

    async function runCreationLibraryFamilyWorkflowForKey(familyKey = "", mode = "publish") {
      const context = normalizeCreationProjectFacetFilterId(familyKey) === "all"
        ? currentCreationLibraryShelfFamilyContext()
        : creationLibraryFamilyContextByKey(familyKey);
      if (!context?.focusGroup) {
        setCreationStatus("No World Library family is active yet.");
        return null;
      }
      focusCreationLibraryFamilyByKey(context.familyKey, { render: true });
      return runCreationLibraryFamilyWorkflow(mode, { context });
    }

    async function runCreationLibraryFamilyWorkflow(mode = "publish", options = {}) {
      const context = options?.context && typeof options.context === "object"
        ? options.context
        : currentCreationLibraryFamilyPacketContext();
      if (!context?.focusGroup) {
        setCreationStatus("No World Library family is active yet.");
        return null;
      }
      const modeSpec = creationLibraryFamilyWorkflowModeSpec(mode);
      const targetGroups = creationLibraryFamilyWorkflowTargetGroups(context, modeSpec.id);
      if (!targetGroups.length) {
        setCreationStatus(`No family packages currently need ${modeSpec.label.toLowerCase()} inside ${context.label}.`);
        return null;
      }
      const suppressStatus = options?.suppressStatus === true;
      if (!suppressStatus) {
        setCreationStatus(`${modeSpec.pending} ${context.label}...`);
      }
      const performedLines = [];
      const skippedLines = [];
      const failedIds = [];
      let updatedCount = 0;
      let lastPublishId = "";
      let lastPackageKey = "";
      for (const targetGroup of targetGroups) {
        const packageKey = String(targetGroup?.packageKey || "").trim();
        let publishId = String(targetGroup?.activeEntry?.id || "").trim();
        const worldLabel = String(targetGroup?.worldName || packageKey || "World package").trim() || "World package";
        if (!packageKey || !publishId) {
          continue;
        }
        try {
          let currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || targetGroup;
          let activeEntry = currentGroup?.activeEntry || targetGroup?.activeEntry || {};
          let proof = creationPublishProofSummary(activeEntry);
          if (proof.state === "pending") {
            await focusCreationWorkflowPublishContext(publishId, packageKey, { openCreate: true });
            await runCurrentCreationWorkflowCreateOutput(publishId);
            performedLines.push(`Created the first world output for ${worldLabel}.`);
            updatedCount += 1;
            await refreshCreationPublishes();
            currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
            activeEntry = currentGroup?.activeEntry || activeEntry;
            publishId = String(activeEntry?.id || publishId).trim();
            proof = creationPublishProofSummary(activeEntry);
          }
          if (proof.state === "created" || proof.state === "partial") {
            await focusCreationWorkflowPublishContext(publishId, packageKey, { openCreate: true });
            const proofResult = await runCurrentCreationWorkflowFinishProof(publishId);
            if (proofResult?.blocked) {
              skippedLines.push(`${worldLabel}: ${proofResult.runtimeState?.summary || "Live proof is not available on this runtime right now."}`);
            } else {
              performedLines.push(`Finished live proof for ${worldLabel}.`);
              updatedCount += 1;
              await refreshCreationPublishes();
              currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
              activeEntry = currentGroup?.activeEntry || activeEntry;
              publishId = String(activeEntry?.id || publishId).trim();
            }
            proof = creationPublishProofSummary(activeEntry);
          }
          if (modeSpec.id === "queue") {
            currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
            activeEntry = currentGroup?.activeEntry || activeEntry;
            publishId = String(activeEntry?.id || publishId).trim();
            let laneState = creationWorkflowPublishLaneState(activeEntry);
            if (publishId && laneState === "draft") {
              await markCreationPublishReadyForDevSide(publishId);
              performedLines.push(`Marked ${worldLabel} ready for dev side.`);
              updatedCount += 1;
              await refreshCreationPublishes();
              currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
              activeEntry = currentGroup?.activeEntry || activeEntry;
              publishId = String(activeEntry?.id || publishId).trim();
              laneState = creationWorkflowPublishLaneState(activeEntry);
            }
            if (publishId && laneState === "handoff_ready") {
              await sendCreationPublishRecordToDevSide(publishId);
              performedLines.push(`Sent ${worldLabel} to the dev-side queue.`);
              updatedCount += 1;
              await refreshCreationPublishes();
              currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
              activeEntry = currentGroup?.activeEntry || activeEntry;
              publishId = String(activeEntry?.id || publishId).trim();
            }
          } else if (modeSpec.id === "keep") {
            currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
            activeEntry = currentGroup?.activeEntry || activeEntry;
            publishId = String(activeEntry?.id || publishId).trim();
            const latestProof = creationPublishProofSummary(activeEntry);
            if (publishId && creationWorkflowPublishLaneState(activeEntry) === "draft" && latestProof.state === "proved") {
              await promoteStoredCreationPublishRecord(publishId);
              performedLines.push(`Promoted ${worldLabel} as the kept local baseline.`);
              updatedCount += 1;
              await refreshCreationPublishes();
              currentGroup = latestCreationLibraryGroupByPackageKey(packageKey) || currentGroup;
              activeEntry = currentGroup?.activeEntry || activeEntry;
              publishId = String(activeEntry?.id || publishId).trim();
            } else if (publishId && latestProof.state !== "proved") {
              skippedLines.push(`${worldLabel}: Keep Local Baseline still needs finished proof before Studio can promote it.`);
            }
          }
          lastPublishId = String(publishId || lastPublishId).trim();
          lastPackageKey = String(packageKey || lastPackageKey).trim();
        } catch (error) {
          failedIds.push(`${worldLabel}: ${error.message}`);
        }
      }
      await refreshCreationPublishes();
      renderCreationLibrarySurface();
      if (lastPackageKey) {
        await loadCreationLibraryPackageFocus(lastPackageKey, lastPublishId);
      }
      renderCreationJourney();
      renderCreationEnginePreview();
      const finalContext = currentCreationLibraryFamilyPacketContext() || context;
      const statusLine = `${modeSpec.success} ${finalContext.label}. Updated ${updatedCount}${failedIds.length ? `; ${failedIds.length} failed` : ""}.`;
      if (!suppressStatus) {
        setCreationStatus(statusLine + (skippedLines.length ? " Some proof steps were skipped where runtime was unavailable." : ""));
      }
      return {
        mode: modeSpec.id,
        familyKey: String(finalContext?.familyKey || context.familyKey || "").trim(),
        familyLabel: String(finalContext?.label || context.label || "").trim(),
        workflowLine: creationWorkflowCountsSummary(finalContext?.packet?.workflowCounts, { includePublishRecord: true }) || "",
        reportLine: String(finalContext?.packet?.reportSummary || "").trim(),
        handoffLine: String(finalContext?.packet?.handoffSummary || "").trim(),
        performedLines,
        skippedLines,
        failedIds,
        updatedCount,
        lastPublishId,
        lastPackageKey,
      };
    }

    function creationProjectBranchTargets(entries = filteredCreationProjects(latestCreationProjects, creationProjectUiState)) {
      const normalizedEntries = Array.isArray(entries) ? entries : [];
      return normalizedEntries.filter(entry =>
        normalizeCreationProjectPublishStateFilterId(entry?.publishState?.state) === "published"
        && String(entry?.publishState?.latestPublishId || "").trim()
      );
    }

    async function branchVisibleCreationProjects(mode = "new_version") {
      const normalizedMode = String(mode || "new_version").trim().toLowerCase();
      const visibleEntries = filteredCreationProjects(latestCreationProjects, creationProjectUiState);
      const targetEntries = creationProjectBranchTargets(visibleEntries);
      const actionMeta = {
        new_version: {
          actionId: "new_version",
          label: "published projects",
          pending: "Creating new draft versions from the visible published shelf...",
          success: "Created new draft versions from the visible published shelf.",
        },
        variant: {
          actionId: "branch_variant",
          label: "published projects",
          pending: "Creating visible variant branches from the published shelf...",
          success: "Created visible variant branches from the published shelf.",
        },
        sequel: {
          actionId: "branch_sequel",
          label: "published projects",
          pending: "Creating visible sequel branches from the published shelf...",
          success: "Created visible sequel branches from the published shelf.",
        },
      }[normalizedMode] || {
        actionId: "new_version",
        label: "published projects",
        pending: "Creating new draft versions from the visible published shelf...",
        success: "Created new draft versions from the visible published shelf.",
      };
      if (!targetEntries.length) {
        setCreationStatus(`No visible ${actionMeta.label} are on this shelf.`);
        return;
      }
      setCreationStatus(actionMeta.pending);
      let createdCount = 0;
      const failedIds = [];
      for (const entry of targetEntries) {
        try {
          if (normalizedMode === "new_version") {
            await saveCreationProjectFirstPublish(entry.id, "draft");
          } else {
            const publishId = String(entry?.publishState?.latestPublishId || "").trim();
            if (!publishId) {
              throw new Error("Missing latest publish.");
            }
            const publish = await fetchJson("/studio/creation-publishes/" + encodeURIComponent(publishId));
            const derived = buildDerivedCreationProjectFromPublish(publish, normalizedMode);
            const savedProject = await saveStoredCreationProjectRecord(derived.derivedWorldName, derived.payload);
            await saveCreationProjectFirstPublish(savedProject.id || "", "draft");
          }
          createdCount += 1;
        } catch (_) {
          failedIds.push(entry?.id || "");
        }
      }
      creationProjectShelfAdvanceAfterLaneAction(actionMeta.actionId, createdCount);
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      if (failedIds.length) {
        setCreationStatus(`${actionMeta.success} Created ${createdCount}; ${failedIds.length} failed.`);
        return;
      }
      setCreationStatus(`${actionMeta.success} Created ${createdCount}.`);
    }

    async function updateCreationProjectFamilyPublishLane(actionId = "mark_ready") {
      const context = currentCreationProjectFamilyContext();
      if (!context) {
        setCreationStatus("No saved-project family is active on this shelf.");
        return;
      }
      const normalizedAction = String(actionId || "").trim().toLowerCase();
      const targetEntries = creationProjectPublishLaneActionTargets(normalizedAction, context.familyEntries);
      const actionMeta = {
        mark_ready: {
          label: "published drafts",
          pending: `Marking family ${context.label} published drafts ready for dev side...`,
          success: `Marked family ${context.label} published drafts ready for dev side.`,
        },
        send: {
          label: "ready-for-dev projects",
          pending: `Sending family ${context.label} ready-for-dev projects...`,
          success: `Sent family ${context.label} ready-for-dev projects.`,
        },
        claim: {
          label: "sent projects",
          pending: `Claiming family ${context.label} sent projects for dev side...`,
          success: `Claimed family ${context.label} sent projects for dev side.`,
        },
        return_to_sent: {
          label: "claimed projects",
          pending: `Returning family ${context.label} claimed projects to the sent lane...`,
          success: `Returned family ${context.label} claimed projects to the sent lane.`,
        },
        keep_local: {
          label: "remote queue projects",
          pending: `Returning family ${context.label} remote-queue projects to local ownership...`,
          success: `Returned family ${context.label} remote-queue projects to local ownership.`,
        },
        promote_kept: {
          label: "published projects that can become kept baselines",
          pending: `Promoting family ${context.label} published projects to kept local baselines...`,
          success: `Promoted family ${context.label} published projects to kept local baselines.`,
        },
        archive: {
          label: "published projects that can be archived",
          pending: `Archiving family ${context.label} published projects...`,
          success: `Archived family ${context.label} published projects.`,
        },
      }[normalizedAction] || {
        label: "projects",
        pending: `Updating family ${context.label} publish lane...`,
        success: `Updated family ${context.label} publish lane.`,
      };
      if (!targetEntries.length) {
        setCreationStatus(`No family ${context.label} ${actionMeta.label} are ready on this shelf.`);
        return;
      }
      setCreationStatus(actionMeta.pending);
      let updatedCount = 0;
      const failedIds = [];
      for (const entry of targetEntries) {
        const publishId = String(entry?.publishState?.latestPublishId || "").trim();
        if (!publishId) {
          continue;
        }
        try {
          if (normalizedAction === "promote_kept") {
            await promoteStoredCreationPublishRecord(publishId);
          } else if (normalizedAction === "archive") {
            await archiveStoredCreationPublishRecord(publishId);
          } else {
            await updateCreationProjectPublishLane(publishId, normalizedAction);
          }
          updatedCount += 1;
        } catch (_) {
          failedIds.push(entry?.id || publishId);
        }
      }
      creationProjectFamilyFocusAfterAction(context.familyKey, normalizedAction, updatedCount);
      await refreshCreationPublishes();
      await refreshCreationProjects();
      renderCreationJourney();
      renderCreationEnginePreview();
      if (failedIds.length) {
        setCreationStatus(`${actionMeta.success} Updated ${updatedCount}; ${failedIds.length} failed.`);
        return;
      }
      setCreationStatus(`${actionMeta.success} Updated ${updatedCount}.`);
    }

