    async function loadCreationPublish(publishId) {
      setCreationStatus("Loading world-pack publish record...");
      try {
        const publish = await fetchJson("/studio/creation-publishes/" + encodeURIComponent(publishId));
        activeCreationPublishId = String(publish.id || "").trim();
        if (publish.projectId) {
          await loadCreationProject(publish.projectId);
          activeCreationPublishId = String(publish.id || "").trim();
        } else if (publish.payload?.projectPayload) {
          applyCreationProjectPayload({
            id: publish.payload?.projectPayload?.id || "",
            name: publish.payload?.projectPayload?.name || publish.worldName || publish.name || "",
            payload: publish.payload.projectPayload,
          });
          activeCreationPublishId = String(publish.id || "").trim();
        }
        await refreshCreationPublishes();
        renderCreationJourney();
        renderCreationEnginePreview();
        scrollToElementId("creation-engine-publishes");
        setCreationStatus("Loaded publish record: " + (publish.name || publish.id || "publish"));
      } catch (error) {
        setCreationStatus("Load publish record failed: " + error.message);
      }
    }

    async function deleteCreationPublish(publishId) {
      setCreationStatus("Deleting world-pack publish record...");
      try {
        const response = await fetch("/studio/creation-publishes/" + encodeURIComponent(publishId), { method: "DELETE" });
        if (!response.ok) {
          throw new Error("/studio/creation-publishes/" + publishId + " -> " + response.status);
        }
        const deleted = await response.json();
        if (publishId === activeCreationPublishId) {
          activeCreationPublishId = "";
        }
        await refreshCreationPublishes();
        renderCreationJourney();
        renderCreationEnginePreview();
        setCreationStatus(deleted.message || "Deleted publish record.");
      } catch (error) {
        setCreationStatus("Delete publish record failed: " + error.message);
      }
    }

    async function exportCreationPublish(publishId) {
      try {
        const publish = await fetchJson("/studio/creation-publishes/" + encodeURIComponent(publishId));
        const safeName = String(publish.name || publish.id || "creation_publish").replace(/[^a-z0-9_-]+/ig, "_").toLowerCase();
        downloadJsonFile(safeName + ".json", publish);
        setCreationStatus("Exported publish record: " + (publish.name || publish.id || "publish"));
      } catch (error) {
        setCreationStatus("Export publish record failed: " + error.message);
      }
    }

