      const posture = state.roleSpeechAnchor || (mode === "new_afpc_draft" ? "practical, steady, draft-safe" : "warm, clear, draft-safe");
      const guidancePosture = state.roleGuidancePosture || posture;
      const worldName = String(state.creationWorldName || state.spawnZone || "this world").trim();
