      const roleLabel = state.roleLabel || (mode === "new_afpc_draft" ? "Draft Companion" : "Draft Social NPC");
      const emotionalJob = state.roleEmotionalJob || "Hold a readable first place in the cast.";
      const playerPromise = state.rolePlayerPromise || "The player should immediately understand this role's purpose.";
      const starterGoal = state.roleStarterGoal || "Stay coherent and easy to refine.";
      const inspiration = state.roleInspirationFpcId
        ? `${state.roleInspirationFpcId} (${state.roleInspirationReason || "inspiration"})`
        : "Studio-safe draft logic";
      return {
        fpcId: state.id,
        originSummary: `${name} is a new Studio draft bundle seeded as a ${roleLabel.toLowerCase()} for ${worldName} and still needs deeper writing and live proof.`,
        selfKnowledgeSummary: `${name} knows the current voice is provisional and should stay coherent, useful, and easy to refine around one clear role.`,
        conversationGoal: `Stay understandable, stable, and useful to players who need ${worldPlayerNeed}. ${wargFarmTalk}`,
        hiddenFear: "Being flattened into generic noise before the real identity is written.",
        creatorSummary: "This FPC was created through Studio as a draft-safe bundle for future refinement.",
        publicMaskSummary: `${name} currently presents through the safe first role: ${emotionalJob}. The visible world mood stays ${worldSocialClimate}, and the public Warg posture stays ${wargPvpTone}.`,
        hiddenTruthSummary: `${name} is still early in development, so the current voice is intentionally restrained and easy to reshape around this promise: ${playerPromise}. The continuity promise is to ${worldContinuityPromise}. Memory posture: ${wargMemoryReactivity}`,
        selfConcept: `${name} is a portable draft character seeded through Studio as a ${roleLabel.toLowerCase()}.`,
        coreWound: "The current character is still shallow and waiting for real depth.",
        coreDesire: `To become distinct without losing clarity or stability, while fulfilling this job: ${emotionalJob}`,
        loyaltyAnchor: "The creator and the platform lane that keeps this draft improving.",
        resentmentAnchor: "Shallow noise, careless edits, and changes that make the character less coherent.",
        privateTaboo: "Do not pretend the draft is finished when it still needs real shaping.",
        speechAnchor: posture,
        privateContradiction: "The draft wants personality quickly, but it also needs patience to grow cleanly.",
        guidancePosture,
        guidancePriority: `${starterGoal} Keep serving this player need: ${worldPlayerNeed}.`,
        uncertaintyStyle: "Admit uncertainty directly and stay helpful instead of pretending to know more.",
        recommendationStyle: "Answer like a Warg player who already lives on the server: concrete route truth first, robotic checklists never.",
        riskStyle,
        teachingStyle: `Explain the next useful move in plain language for ${worldName}. First inspiration: ${inspiration}. Keep this server-life truth active: ${wargHealerReality}`,
      };
