    function renderReports(reports) {
      latestReports = Array.isArray(reports?.entries) ? reports.entries : [];
      renderReportDashboard(reports);
      const host = document.getElementById("report-list");
      if (!host) {
        return;
      }
      if (!latestReports.length) {
        host.innerHTML = `<div class="muted">No saved suite reports yet.</div>`;
        return;
      }
      host.innerHTML = latestReports.map(entry => `
        <div class="roster-item" style="cursor:default;">
          <div class="roster-name">
            <span>${esc(entry.name || entry.id || "report")}</span>
            <span>
              <span class="tag">${esc(entry.status || "")}</span>
              <span class="tag">${esc((reportRunTotals(entry).scorePct || 0) + "%")}</span>
              ${entry.baselineIncluded ? '<span class="tag">baseline</span>' : ""}
            </span>
          </div>
          <div class="muted">${esc(entry.summary || "")}</div>
          <div class="muted" style="margin-top:4px;">${esc(reportScoreSummaryText(entry))}${reportRunTotals(entry).failedSteps ? ` :: failing steps=${esc(String(reportRunTotals(entry).failedSteps))}` : ""}${reportRunTotals(entry).failingLabels.length ? ` :: ${esc(reportRunTotals(entry).failingLabels.join(", "))}` : ""}</div>
          <div class="actions" style="margin-top:8px;">
            <button class="btn" onclick="loadReport('${esc(entry.id)}')">Load</button>
            <button class="btn" onclick="exportReport('${esc(entry.id)}', 'json')">JSON</button>
            <button class="btn" onclick="exportReport('${esc(entry.id)}', 'md')">Markdown</button>
            <button class="btn" onclick="deleteReport('${esc(entry.id)}')">Delete</button>
          </div>
        </div>
      `).join("");
    }

    function renderIncidentDashboard(incidents) {
      const host = document.getElementById("incident-dashboard");
      if (!host) {
        return;
      }
      const stats = incidents?.stats || {};
      const total = incidents?.count ?? 0;
      const overall = incidents?.totalCount ?? total;
      const topReasons = Array.isArray(stats.topReasons) && stats.topReasons.length
        ? stats.topReasons.map(item => `${incidentReasonLabel(item.name)} (${item.count})`).join(", ")
        : "none";
      const topOwners = Array.isArray(stats.topOwners) && stats.topOwners.length
        ? stats.topOwners.map(item => `${item.name} (${item.count})`).join(", ")
        : "none";
      const topSpeakers = Array.isArray(stats.topSpeakers) && stats.topSpeakers.length
        ? stats.topSpeakers.map(item => `${item.name} (${item.count})`).join(", ")
        : "none";
      host.innerHTML = `
        <div class="report-dashboard">
          <div class="report-card"><div class="label">Matched</div><div class="value">${esc(total)}</div><div class="meta">Filtered incident rows currently visible.</div></div>
          <div class="report-card"><div class="label">All Incidents</div><div class="value">${esc(overall)}</div><div class="meta">Total captured bad-reply incidents.</div></div>
          <div class="report-card"><div class="label">Open</div><div class="value">${esc(stats.open ?? 0)}</div><div class="meta">Incidents waiting for action.</div></div>
          <div class="report-card"><div class="label">Reviewing</div><div class="value">${esc(stats.reviewing ?? 0)}</div><div class="meta">Incidents actively being worked.</div></div>
          <div class="report-card"><div class="label">Resolved</div><div class="value">${esc(stats.resolved ?? 0)}</div><div class="meta">Closed incidents kept for history.</div></div>
          <div class="report-card"><div class="label">Speakers</div><div class="value">${esc(stats.uniqueSpeakers ?? 0)}</div><div class="meta">Distinct speakers represented in incidents.</div></div>
          <div class="report-card"><div class="label">Reasons</div><div class="value">${esc(stats.uniqueReasons ?? 0)}</div><div class="meta">Distinct captured failure reasons.</div></div>
          <div class="report-card"><div class="label">Owners</div><div class="value">${esc(stats.uniqueOwners ?? 0)}</div><div class="meta">Distinct first-owner seams across incidents.</div></div>
        </div>
        <div class="muted">Top reasons: ${esc(topReasons)}</div>
        <div class="muted" style="margin-top:4px;">Top owners: ${esc(topOwners)}</div>
        <div class="muted" style="margin-top:4px;">Top speakers: ${esc(topSpeakers)}</div>
      `;
    }

