    async function exportReport(reportId, format = "json") {
      try {
        const report = await fetchJson("/studio/reports/" + encodeURIComponent(reportId));
        const safeName = String(report.name || report.id || "suite_report").replace(/[^a-z0-9_-]+/ig, "_").toLowerCase();
        if (String(format).toLowerCase() === "md") {
          const markdown = currentReportMarkdown(report);
          const blob = new Blob([markdown], { type: "text/markdown" });
          const url = URL.createObjectURL(blob);
          const link = document.createElement("a");
          link.href = url;
          link.download = safeName + ".md";
          document.body.appendChild(link);
          link.click();
          link.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
        } else {
          downloadJsonFile(safeName + ".json", report);
        }
        setLabStatus("Exported suite report: " + (report.name || report.id || "report"));
      } catch (error) {
        setLabStatus("Export report failed: " + error.message);
      }
    }

