    function clearBundleImport() {
      const field = document.getElementById("bundle-import-json");
      if (field) {
        field.value = "";
      }
    }

    async function importBundle() {
      const field = document.getElementById("bundle-import-json");
      const raw = field?.value || "";
      if (!raw.trim()) {
        setLabStatus("Bundle JSON is empty.");
        return;
      }
      try {
        const parsed = JSON.parse(raw);
        const session = (parsed && typeof parsed === "object" && parsed.session && typeof parsed.session === "object") ? parsed.session : parsed;
        if (!session || typeof session !== "object") {
          throw new Error("Bundle does not contain a session payload.");
        }
        if (!String(session.name || "").trim()) {
          session.name = bookmarkSummary(session);
        }
        const saved = await postJson("/studio/bookmarks", session);
        clearBundleImport();
        await refreshBookmarks();
        setLabStatus("Imported bundle as saved session: " + (saved.name || saved.id || "session"));
      } catch (error) {
        setLabStatus("Import failed: " + error.message);
      }
    }

