    async function runProbeRequest(playerName, channel, text, options = {}) {
      const {
        updateOutput = true,
        updateStatus = true,
        refreshTrace = true,
      } = options;
      const output = document.getElementById("probe-output");
      if (!text.trim()) {
        throw new Error("Probe text is empty.");
      }
      if (updateStatus) {
        setLabStatus("Running conversation probe...");
      }
      if (output && updateOutput) {
        output.innerHTML = `<div class="muted">Waiting for result...</div>`;
      }
      const queued = await postJson("/studio/commands", { action: "conversation_probe", fpcId: activeId, playerName, channel, text });
      const result = await pollCommandResult(queued.commandId);
      const baseProbe = result.probe || result;
      const studioStatus = String(result.status || "unknown").trim().toLowerCase() || "unknown";
      latestProbeResult = {
        ...(baseProbe && typeof baseProbe === "object" ? baseProbe : {}),
        _studioFpcId: String(activeId || "").trim().toLowerCase(),
        _studioStatus: studioStatus,
        _studioMessage: String(result.message || "").trim(),
        _studioCommandId: String(result.commandId || queued.commandId || "").trim(),
      };
      latestRepairMode = suggestedRepairMode(latestProbeResult);
      rerenderCreationProofAwareSurfaces();
      if (updateStatus) {
        setLabStatus((result.status || "unknown") + ": " + (result.message || ""));
      }
      if (studioStatus !== "ok") {
        const error = new Error(String(result.message || `Conversation probe returned ${studioStatus}.`).trim() || `Conversation probe returned ${studioStatus}.`);
        error.studioResult = latestProbeResult;
        error.commandId = latestProbeResult._studioCommandId;
        throw error;
      }
      if (output && updateOutput) {
        renderProbeOutput(latestProbeResult);
      }
      refreshLabTabOutput(activeLabTab);
      if (refreshTrace) {
        renderCurrentContextCompare();
        await loadTrace("replies", false);
      }
      return latestProbeResult;
    }

    async function issueProbe() {
      if (!activeId) {
        return;
      }
      const playerName = document.getElementById("probe-player")?.value || "PlayerOne";
      const channel = document.getElementById("probe-channel")?.value || "whisper";
      const text = document.getElementById("probe-text")?.value || "";
      const output = document.getElementById("probe-output");
      try {
        await runProbeRequest(playerName, channel, text);
      } catch (error) {
        setLabStatus("Probe failed: " + error.message);
        if (output) {
          output.textContent = error.message;
        }
      }
    }

    async function runSelectedSuite(definition) {
      if (!activeId) {
        return;
      }
      const suite = selectedSuite(definition);
      if (!suite) {
        setLabStatus("Suite not found.");
        return;
      }
      const steps = resolveSuiteSteps(definition, suite);
      if (!steps.length) {
        setLabStatus("Suite has no runnable steps.");
        return;
      }
      setLabStatus("Running suite: " + suite.label + "...");
      latestSuiteRun = {
        suiteId: suite.id,
        label: suite.label,
        description: suite.description || "",
        ranAtMs: Date.now(),
        fpcId: activeId,
        fpcName: definition.name || definition.id || activeId,
        status: "running",
        steps: [],
      };
      recomputeSuiteRunTotals(latestSuiteRun);
      renderSuiteRun(latestSuiteRun);
      try {
        for (let index = 0; index < steps.length; index++) {
          const step = steps[index];
          applyProbeSpec(step);
          const result = await runProbeRequest(step.playerName || "PlayerOne", step.channel || "whisper", step.text || "", {
            updateOutput: index === steps.length - 1,
            updateStatus: false,
            refreshTrace: false,
          });
          const evaluation = evaluateSuiteStep(step, result);
          const routeProfile = result?.classification?.routeProfile || {};
          const triage = result?.qualityTriage || buildReplyQualityTriage(result, {});
          latestSuiteRun.steps.push({
            index: index + 1,
            presetId: step.id || "",
            label: step.label || ("Step " + String(index + 1)),
            playerName: step.playerName || "PlayerOne",
            channel: step.channel || "whisper",
            text: step.text || "",
            replyLine: result?.reply?.line || "",
            speakNow: Boolean(result?.reply?.speakNow),
            category: result?.classification?.messageCategory || "",
            focusIntent: result?.classification?.focusIntent || "",
            knowledgeType: result?.classification?.knowledgeType || "",
            routeLane: routeProfile.lane || result?.classification?.routeLane || "",
            routeSpeechAct: routeProfile.speechAct || result?.classification?.routeSpeechAct || "",
            routeKnowledgeNeed: routeProfile.knowledgeNeed || result?.classification?.routeKnowledgeNeed || "",
            routePrimaryTopic: routeProfile.primaryTopic || result?.classification?.routePrimaryTopic || "",
            triageOwner: triage?.owner || "",
            source: result?.reply?.source || "",
            expectedCategory: step.expectedCategory || "",
            expectedFocusIntent: step.expectedFocusIntent || "",
            expectedRouteLane: step.expectedRouteLane || "",
            expectedSpeechAct: step.expectedSpeechAct || "",
            expectedKnowledgeNeed: step.expectedKnowledgeNeed || "",
            expectedPrimaryTopic: step.expectedPrimaryTopic || "",
            expectedSpeakNow: typeof step.expectedSpeakNow === "boolean" ? step.expectedSpeakNow : null,
            expectedTriageOwner: step.expectedTriageOwner || "",
            maxReplyWords: Number.isFinite(Number(step.maxReplyWords)) ? Number(step.maxReplyWords) : null,
            requiredSource: step.requiredSource || "",
            requiredTerms: Array.isArray(step.requiredTerms) ? step.requiredTerms : [],
            requiredAnyTerms: Array.isArray(step.requiredAnyTerms) ? step.requiredAnyTerms : [],
            forbiddenTerms: Array.isArray(step.forbiddenTerms) ? step.forbiddenTerms : [],
            requiredNonEmptyPaths: Array.isArray(step.requiredNonEmptyPaths) ? step.requiredNonEmptyPaths : [],
            requiredAnyTermsInPaths: Array.isArray(step.requiredAnyTermsInPaths) ? step.requiredAnyTermsInPaths : [],
            checks: evaluation.checks,
            passedChecks: evaluation.passedChecks,
            totalChecks: evaluation.totalChecks,
            failed: evaluation.failed,
          });
          recomputeSuiteRunTotals(latestSuiteRun);
          renderSuiteRun(latestSuiteRun);
        }
        latestSuiteRun.status = "completed";
        recomputeSuiteRunTotals(latestSuiteRun);
        await loadTrace("replies", false);
        await issueSocialSnapshot(false);
        renderCurrentContextCompare();
        renderSuiteRun(latestSuiteRun);
        const reportName = document.getElementById("report-name");
        if (reportName && !String(reportName.value || "").trim()) {
          reportName.value = suiteSummary(latestSuiteRun);
        }
        await saveCurrentReport();
        setLabStatus("Completed suite: " + suiteSummary(latestSuiteRun));
      } catch (error) {
        latestSuiteRun.status = "failed";
        latestSuiteRun.error = error.message;
        recomputeSuiteRunTotals(latestSuiteRun);
        renderSuiteRun(latestSuiteRun);
        const reportName = document.getElementById("report-name");
        if (reportName && !String(reportName.value || "").trim()) {
          reportName.value = suiteSummary(latestSuiteRun);
        }
        await saveCurrentReport();
        setLabStatus("Suite failed: " + error.message);
      }
    }

    async function issueSocialSnapshot(updateStatus = true) {
      if (!activeId) {
        return;
      }
      const playerName = document.getElementById("probe-player")?.value || "PlayerOne";
      const output = document.getElementById("pair-output");
      if (!playerName.trim()) {
        setLabStatus("Player name is empty.");
        return;
      }
      if (updateStatus) {
        setLabStatus("Loading social pair snapshot...");
      }
      if (output) {
        output.innerHTML = `<div class="muted">Waiting for snapshot...</div>`;
      }
      try {
        const queued = await postJson("/studio/commands", { action: "social_snapshot", fpcId: activeId, playerName });
        const result = await pollCommandResult(queued.commandId);
        const snapshot = await fetchJson("/studio/social/" + encodeURIComponent(activeId) + "/" + encodeURIComponent(playerName));
        if (updateStatus) {
          setLabStatus((result.status || "unknown") + ": " + (result.message || ""));
        }
        latestSocialSnapshot = snapshot.snapshot || snapshot;
        if (output) {
          renderSocialSnapshotOutput(latestSocialSnapshot);
        }
        renderCurrentContextCompare();
      } catch (error) {
        setLabStatus("Social snapshot failed: " + error.message);
        if (output) {
          output.innerHTML = `<div class="muted">${esc(error.message)}</div>`;
        }
      }
    }

    async function loadTrace(traceName, updateStatus = true) {
      const output = document.getElementById("trace-output");
      const query = traceFilterQuery();
      if (updateStatus) {
        setLabStatus("Loading " + traceName + " trace...");
      }
      if (output) {
        output.textContent = "Waiting for trace...";
      }
      try {
        const trace = await fetchJson("/studio/traces/" + encodeURIComponent(traceName) + "?" + query);
        if (updateStatus) {
          setLabStatus("Loaded " + trace.returned + " of " + trace.matched + " matched " + traceName + " entries.");
        }
        if (output) {
          output.textContent = JSON.stringify(trace, null, 2);
        }
        if (traceName === "replies") {
          populateReplyCompare(trace.entries || []);
        }
      } catch (error) {
        setLabStatus("Trace load failed: " + error.message);
        if (output) {
          output.textContent = error.message;
        }
      }
    }

    async function loadDetail(id) {
      activeId = id;
      try {
        const liveData = await fetchJsonMaybe("/studio/fpc/" + encodeURIComponent(id));
        if (liveData?.definition) {
          renderDetail(liveData);
        } else {
          const sourceData = await fetchJsonMaybe("/studio/content/fpcs/" + encodeURIComponent(id));
          if (!sourceData?.entry) {
            throw new Error("/studio/fpc/" + id + " -> 404");
          }
          activeDefinition = sourceData.entry;
          const personaData = await fetchJsonMaybe("/studio/content/personas/" + encodeURIComponent(id));
          renderDetail({
            definition: sourceData.entry,
            runtime: {
              live: false,
              state: "source-only",
              zone: sourceData.entry?.spawnProfile?.zone || "",
              leaderName: "none",
              targetName: "none",
              debugCategories: "none",
            },
            persona: personaData?.entry || {},
            combatPower: {},
          });
        }
        const rosterData = await fetchJson("/studio/roster");
        renderRoster(rosterData);
      } catch (error) {
        renderSelectionMeta(null, null);
        document.getElementById("detail").innerHTML = `<div class="muted">Could not load detail: ${esc(error.message)}</div>`;
      }
    }

    async function refreshStudio() {
      const runtime = await fetchJsonWithRetry("/studio/runtime", { attempts: 3, delayMs: 250 });
      const roster = await fetchJsonWithRetry("/studio/roster", { attempts: 3, delayMs: 250 });
      renderRuntime(runtime);
      renderRoster(roster);
      renderStudioGuideSurface();
      if (activeId) {
        await loadDetail(activeId);
      }
    }

    async function boot() {
      try {
        studioUxMode = loadStudioUxMode();
        studioWorkspace = loadStudioWorkspace();
        creationAdvancedVisible = loadCreationAdvancedVisible();
        creationQueueUiState = loadCreationQueueUiState();
        creationProjectUiState = loadCreationProjectUiState();
        renderStudioModeChrome();
        updateStudioWorkspacePath(studioWorkspace, { replace: true });
        window.addEventListener("popstate", () => {
          studioWorkspace = loadStudioWorkspace();
          renderStudioModeChrome();
        });
        renderCreationBriefExamples();
        renderRoutingWizardFamilyHelper();
        renderRoutingWizardResultOptions();
        updateRoutingWizardPreview();
        const rosterFilter = document.getElementById("roster-filter");
        if (rosterFilter) {
          rosterFilter.addEventListener("input", applyRosterFilter);
        }
        const rosterTypeFilter = document.getElementById("roster-type-filter");
        if (rosterTypeFilter) {
          rosterTypeFilter.addEventListener("change", applyRosterFilter);
        }
        await refreshStudio();
        await refreshPlatformManifest();
        await refreshPlatformSnapshots();
        await refreshPlatformWorkitems();
        await refreshCreationProjects();
        await refreshCreationPublishes();
        const roster = await fetchJsonWithRetry("/studio/roster", { attempts: 3, delayMs: 250 });
        if (roster.entries && roster.entries.length > 0) {
          await loadDetail((roster.entries[0].id || "").toLowerCase());
        }
      } catch (error) {
        document.getElementById("runtime").innerHTML = `<h2>Runtime</h2><div class="muted">Studio bootstrap failed: ${esc(error.message)}</div>`;
        document.getElementById("roster").innerHTML = `<div class="muted">Studio bootstrap failed: ${esc(error.message)}</div>`;
      }
    }

    boot();
